(389862,43318,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jövő évre a két ív ... az egész kanyont.'::text,'át fogja ívelni'::text,'átíveli'::text,'éppen átíveli'::text,'Jövő évre a két ív át fogja ívelni az egész kanyont.'::text),
(389865,43319,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Leiter die Lücke nicht überbrückt hätte, hätten die Feuerwehrleute das oberste Fenster ...'::text,'nicht erreichen können'::text,'nicht erreichen können'::text,'nicht erreicht'::text,'Wenn die Leiter die Lücke nicht überbrückt hätte, hätten die Feuerwehrleute das oberste Fenster nicht erreichen können.'::text),
(389869,43319,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби драбина не перекрила проміжок, пожежники ... до верхнього вікна.'::text,'не змогли б дістатися'::text,'не можуть дістатися'::text,'не дісталися'::text,'Якби драбина не перекрила проміжок, пожежники не змогли б дістатися до верхнього вікна.'::text),
(389868,43319,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la escalera no hubiera cubierto el hueco, los bomberos ... la ventana de arriba.'::text,'no habrían podido alcanzar'::text,'no pueden alcanzar'::text,'no alcanzaron'::text,'Si la escalera no hubiera cubierto el hueco, los bomberos no habrían podido alcanzar la ventana de arriba.'::text),
(389867,43319,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''échelle n''avait pas couvert l''écart, les pompiers ... la fenêtre du haut.'::text,'n''auraient pas pu atteindre'::text,'ne peuvent pas atteindre'::text,'n''ont pas atteint'::text,'Si l''échelle n''avait pas couvert l''écart, les pompiers n''auraient pas pu atteindre la fenêtre du haut.'::text),
(389870,43319,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Merdiven boşluğu kapatmasaydı, itfaiyeciler en üst pencereye ...'::text,'ulaşamazlardı'::text,'ulaşamıyorlar'::text,'ulaşmadılar'::text,'Merdiven boşluğu kapatmasaydı, itfaiyeciler en üst pencereye ulaşamazlardı.'::text),
(389871,43319,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a létra nem hidalta volna át a rést, a tűzoltók ... a legfelső ablakot.'::text,'nem tudták volna elérni'::text,'nem tudják elérni'::text,'nem érték el'::text,'Ha a létra nem hidalta volna át a rést, a tűzoltók nem tudták volna elérni a legfelső ablakot.'::text),
(389874,43320,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast vorgeschlagen, die Lücke mit der langen Leiter ..., und ehrlich, es hat geklappt.'::text,'zu überbrücken'::text,'zu überbrücken'::text,'überbrückt'::text,'Du hast vorgeschlagen, die Lücke mit der langen Leiter zu überbrücken, und ehrlich, es hat geklappt.'::text),
(389878,43320,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти запропонував ... проміжок довгою драбиною, і чесно, це спрацювало.'::text,'перекрити'::text,'перекрити'::text,'перекрив'::text,'Ти запропонував перекрити проміжок довгою драбиною, і чесно, це спрацювало.'::text),
(389877,43320,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Propusiste ... el hueco con la escalera larga y, sinceramente, funcionó.'::text,'cubrir'::text,'cubrir'::text,'cubriste'::text,'Propusiste cubrir el hueco con la escalera larga y, sinceramente, funcionó.'::text),
(389876,43320,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as proposé de ... l''écart avec la longue échelle, et franchement, ça a marché.'::text,'combler'::text,'combler'::text,'comblé'::text,'Tu as proposé de combler l''écart avec la longue échelle, et franchement, ça a marché.'::text),
(389879,43320,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boşluğu uzun merdivenle ... önerdin ve açıkçası işe yaradı.'::text,'kapatmayı'::text,'kapatmayı'::text,'kapattın'::text,'Boşluğu uzun merdivenle kapatmayı önerdin ve açıkçası işe yaradı.'::text),
(389880,43320,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt javasoltad, hogy ... a rést a hosszú létrával, és őszintén, bejött.'::text,'hidaljuk át'::text,'hidaljuk át'::text,'áthidaltad'::text,'Azt javasoltad, hogy hidaljuk át a rést a hosszú létrával, és őszintén, bejött.'::text),
(389883,43321,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... die Lücke zuerst ausgemessen haben; die Leiter überbrückt sie perfekt.'::text,'musst'::text,'kannst nicht'::text,'solltest nicht'::text,'Ehrlich gesagt, du musst die Lücke zuerst ausgemessen haben; die Leiter überbrückt sie perfekt.'::text),
(389887,43321,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти ... спочатку виміряв проміжок; ця драбина ідеально його перекриває.'::text,'точно'::text,'точно не'::text,'даремно'::text,'Не буду брехати, ти точно спочатку виміряв проміжок; ця драбина ідеально його перекриває.'::text),
(389886,43321,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, ... medido el hueco primero; esa escalera lo cubre perfectamente.'::text,'debes de haber'::text,'no puedes haber'::text,'no deberías haber'::text,'No voy a mentir, debes de haber medido el hueco primero; esa escalera lo cubre perfectamente.'::text),
(389885,43321,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... mesuré l''écart d''abord ; cette échelle le couvre parfaitement.'::text,'as dû'::text,'ne peux pas avoir'::text,'n''aurais pas dû'::text,'Je vais pas mentir, tu as dû mesuré l''écart d''abord ; cette échelle le couvre parfaitement.'::text),
(389888,43321,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, boşluğu önce ...; o merdiven onu mükemmel şekilde kapatıyor.'::text,'ölçmüş olmalısın'::text,'ölçmüş olamazsın'::text,'ölçmemeliydin'::text,'Yalan yok, boşluğu önce ölçmüş olmalısın; o merdiven onu mükemmel şekilde kapatıyor.'::text),
(389889,43321,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, előbb ... a rést; az a létra tökéletesen áthidalja.'::text,'biztos lemérted'::text,'nem mérhetted le'::text,'nem kellett volna lemérned'::text,'Nem hazudok, előbb biztos lemérted a rést; az a létra tökéletesen áthidalja.'::text),
(389892,43322,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast die Lücke in Sekunden von einer einzigen Leiter ... lassen.'::text,'überbrücken'::text,'überbrücken'::text,'überbrücken'::text,'Ehrlich, du hast die Lücke in Sekunden von einer einzigen Leiter überbrücken lassen.'::text),
(389896,43322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти за лічені секунди домігся, щоб проміжок ... однією драбиною.'::text,'перекрили'::text,'перекрили'::text,'перекрити'::text,'Чесно, ти за лічені секунди домігся, щоб проміжок перекрили однією драбиною.'::text),
(389895,43322,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, hiciste que una sola escalera ... el hueco en segundos.'::text,'cubriera'::text,'cubra'::text,'cubrir'::text,'Sinceramente, hiciste que una sola escalera cubriera el hueco en segundos.'::text),
(389894,43322,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as fait ... l''écart par une seule échelle en quelques secondes.'::text,'combler'::text,'combler'::text,'combler'::text,'Franchement, tu as fait combler l''écart par une seule échelle en quelques secondes.'::text),
(389897,43322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, boşluğu saniyeler içinde tek bir merdivene ...'::text,'kapattırdın'::text,'kapattırdın'::text,'kapattırmak'::text,'Açıkçası, boşluğu saniyeler içinde tek bir merdivene kapattırdın.'::text),
(389898,43322,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, egyetlen létrával pár másodperc alatt ... a rést.'::text,'áthidaltattad'::text,'áthidaltattad'::text,'áthidaltatni'::text,'Őszintén, egyetlen létrával pár másodperc alatt áthidaltattad a rést.'::text),
(389901,43323,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kranführer wünscht sich, der Ausleger ... ein bisschen weiter reichen. Ein minimal zu kurzer Kran.'::text,'könnte'::text,'kann'::text,'wird'::text,'Der Kranführer wünscht sich, der Ausleger könnte ein bisschen weiter reichen. Ein minimal zu kurzer Kran.'::text),
(389905,43323,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кранівник хотів би, щоб стріла ... трохи далі. Трохи закороткий кран.'::text,'могла сягати'::text,'може сягати'::text,'сягатиме'::text,'Кранівник хотів би, щоб стріла могла сягати трохи далі. Трохи закороткий кран.'::text),
(389904,43323,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El gruista desearía que el brazo ... un poco más lejos. Una grúa ligeramente corta.'::text,'pudiera llegar'::text,'puede llegar'::text,'llegará'::text,'El gruista desearía que el brazo pudiera llegar un poco más lejos. Una grúa ligeramente corta.'::text),
(389903,43323,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grutier aimerait que la flèche ... un peu plus loin. Une grue légèrement courte.'::text,'puisse aller'::text,'peut aller'::text,'ira'::text,'Le grutier aimerait que la flèche puisse aller un peu plus loin. Une grue légèrement courte.'::text),
(389906,43323,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vinç operatörü, bomun biraz daha uzağa ... diliyor. Hafifçe kısa bir vinç.'::text,'uzanabilmesini'::text,'uzanabildiğini'::text,'uzanacağını'::text,'Vinç operatörü, bomun biraz daha uzağa uzanabilmesini diliyor. Hafifçe kısa bir vinç.'::text),
(389907,43323,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A darukezelő azt szeretné, ha a gém ... egy kicsit messzebb. Kicsit rövid daru.'::text,'érhetne'::text,'érhet'::text,'fog érni'::text,'A darukezelő azt szeretné, ha a gém érhetne egy kicsit messzebb. Kicsit rövid daru.'::text),
(389910,43324,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Canyon, ... Fluss tief unten fließt, wird von Bögen überspannt, die sich nicht treffen. Makellos.'::text,'dessen'::text,'der'::text,'wo'::text,'Der Canyon, dessen Fluss tief unten fließt, wird von Bögen überspannt, die sich nicht treffen. Makellos.'::text),
(389914,43324,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Каньйон, ... річка тече глибоко внизу, перекривають арки, які не сходяться. Бездоганно.'::text,'чия'::text,'який'::text,'де'::text,'Каньйон, чия річка тече глибоко внизу, перекривають арки, які не сходяться. Бездоганно.'::text),
(389913,43324,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cañón, ... río corre muy abajo, está cruzado por arcos que no se juntan. Impecable.'::text,'cuyo'::text,'que'::text,'donde'::text,'El cañón, cuyo río corre muy abajo, está cruzado por arcos que no se juntan. Impecable.'::text),
(389912,43324,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le canyon, ... la rivière coule tout en bas, est enjambé par des arches qui ne se rejoignent pas. Impeccable.'::text,'dont'::text,'qui'::text,'où'::text,'Le canyon, dont la rivière coule tout en bas, est enjambé par des arches qui ne se rejoignent pas. Impeccable.'::text),
(389915,43324,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nehri çok aşağıdan akan kanyon ... birleşmeyen kemerlerle aşılıyor. Kusursuz.'::text,''::text,NULL::text,NULL::text,'Nehri çok aşağıdan akan kanyon birleşmeyen kemerlerle aşılıyor. Kusursuz.'::text),
(389916,43324,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kanyont, ... folyója mélyen lent folyik, olyan ívek hidalják át, amelyek nem érnek össze. Hibátlan.'::text,'amelynek'::text,'amely'::text,'ahol'::text,'A kanyont, amelynek folyója mélyen lent folyik, olyan ívek hidalják át, amelyek nem érnek össze. Hibátlan.'::text),
(389919,43325,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Bögen werden den Canyon überspannen, ... sich beide Hälften wirklich treffen. Kein großes Ding.'::text,'vorausgesetzt, dass'::text,'für den Fall, dass'::text,'aufgrund dessen, dass'::text,'Die Bögen werden den Canyon überspannen, vorausgesetzt, dass sich beide Hälften wirklich treffen. Kein großes Ding.'::text),
(389923,43325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Арки перекриють каньйон, ... обидві половини справді зійдуться. Нічого особливого.'::text,'за умови, що'::text,'на випадок, якщо'::text,'завдяки тому, що'::text,'Арки перекриють каньйон, за умови, що обидві половини справді зійдуться. Нічого особливого.'::text),
(389922,43325,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los arcos cruzarán el cañón, ... las dos mitades de verdad se junten. Nada del otro mundo.'::text,'siempre que'::text,'por si'::text,'debido a que'::text,'Los arcos cruzarán el cañón, siempre que las dos mitades de verdad se junten. Nada del otro mundo.'::text),
(389921,43325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les arches enjamberont le canyon, ... les deux moitiés se rejoignent vraiment. Rien de fou.'::text,'à condition que'::text,'au cas où'::text,'en raison du fait que'::text,'Les arches enjamberont le canyon, à condition que les deux moitiés se rejoignent vraiment. Rien de fou.'::text),
(389924,43325,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kemerler, iki yarı gerçekten ... kanyonu aşacak. Çok da önemli değil.'::text,'birleştiği takdirde'::text,'birleşir diye'::text,'birleştiği için'::text,'Kemerler, iki yarı gerçekten birleştiği takdirde kanyonu aşacak. Çok da önemli değil.'::text),
(389925,43325,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ívek átívelik majd a kanyont, ... a két fél tényleg összeér. Semmi extra.'::text,'feltéve, hogy'::text,'arra az esetre, ha'::text,'amiatt, hogy'::text,'Az ívek átívelik majd a kanyont, feltéve, hogy a két fél tényleg összeér. Semmi extra.'::text),
(396030,44004,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Zelt ... fest auf dem Rasen, während der aufblasbare Bogen in sich zusammenfiel.'::text,'stand'::text,'stand'::text,'hat gestanden'::text,'Das Zelt stand fest auf dem Rasen, während der aufblasbare Bogen in sich zusammenfiel.'::text),
(396034,44004,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Намет ... міцно на газоні, поки надувна арка здувалася.'::text,'стояв'::text,'стояв'::text,'простояв'::text,'Намет стояв міцно на газоні, поки надувна арка здувалася.'::text),
(396033,44004,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carpa ... firme en el césped mientras el arco inflable se desinflaba.'::text,'estaba'::text,'estuvo'::text,'ha estado'::text,'La carpa estaba firme en el césped mientras el arco inflable se desinflaba.'::text),
(396032,44004,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tente ... bien droite sur la pelouse pendant que l''arche gonflable s''affaissait.'::text,'se tenait'::text,'se tint'::text,'s''est tenue'::text,'La tente se tenait bien droite sur la pelouse pendant que l''arche gonflable s''affaissait.'::text),
(396035,44004,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şişme kemer inerken çadır çimde sağlam bir şekilde ...'::text,'duruyordu'::text,'durdu'::text,'durmuştur'::text,'Şişme kemer inerken çadır çimde sağlam bir şekilde duruyordu.'::text),
(396036,44004,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sátor szilárdan ... a gyepen, miközben a felfújható ív összeesett.'::text,'állt'::text,'állt'::text,'állt'::text,'A sátor szilárdan állt a gyepen, miközben a felfújható ív összeesett.'::text),
(396039,44005,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das weiße Zelt ... seit dem Morgen auf dem Rasen.'::text,'steht'::text,'steht'::text,'steht'::text,'Das weiße Zelt steht seit dem Morgen auf dem Rasen.'::text),
(396043,44005,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Білий намет ... на газоні з самого ранку.'::text,'стоїть'::text,'стоїть'::text,'стоїть'::text,'Білий намет стоїть на газоні з самого ранку.'::text),
(396042,44005,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carpa blanca ... en el césped desde por la mañana.'::text,'está'::text,'está'::text,'está'::text,'La carpa blanca está en el césped desde por la mañana.'::text),
(396041,44005,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tente blanche ... sur la pelouse depuis ce matin.'::text,'est plantée'::text,'est plantée'::text,'est plantée'::text,'La tente blanche est plantée sur la pelouse depuis ce matin.'::text),
(396044,44005,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beyaz çadır sabahtan beri çimde ...'::text,'duruyor'::text,'duruyor'::text,'durur'::text,'Beyaz çadır sabahtan beri çimde duruyor.'::text),
(396045,44005,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fehér sátor reggel óta ... a gyepen.'::text,'áll'::text,'áll'::text,'áll'::text,'A fehér sátor reggel óta áll a gyepen.'::text),
(396048,44006,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bogen ..., gleich nachdem die Kamera am Zelt vorbeigefahren war.'::text,'erschlaffte'::text,'erschlaffte gerade'::text,'ist erschlafft'::text,'Der Bogen erschlaffte, gleich nachdem die Kamera am Zelt vorbeigefahren war.'::text),
(396052,44006,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Арка ... одразу після того, як камера проїхала повз намет.'::text,'здулася'::text,'здувалася'::text,'здулася'::text,'Арка здулася одразу після того, як камера проїхала повз намет.'::text),
(396051,44006,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El arco ... justo después de que la cámara pasara junto a la carpa.'::text,'se desinfló'::text,'se estaba desinflando'::text,'se ha desinflado'::text,'El arco se desinfló justo después de que la cámara pasara junto a la carpa.'::text),
(396050,44006,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''arche ... juste après que la caméra est passée devant la tente.'::text,'s''est affaissée'::text,'s''affaissait'::text,'s''est affaissée'::text,'L''arche s''est affaissée juste après que la caméra est passée devant la tente.'::text),
(396053,44006,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kamera çadırın önünden geçtikten hemen sonra kemer ...'::text,'söndü'::text,'sönüyordu'::text,'sönmüştür'::text,'Kamera çadırın önünden geçtikten hemen sonra kemer söndü.'::text),
(396054,44006,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ív ... közvetlenül azután, hogy a kamera elhaladt a sátor mellett.'::text,'összeesett'::text,'éppen összeesett'::text,'összeesett'::text,'Az ív összeesett közvetlenül azután, hogy a kamera elhaladt a sátor mellett.'::text),
(396057,44007,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Zelt ... heute schon zwei Windböen, was auf eine gut beschwerte Konstruktion hindeutet.'::text,'überstand'::text,'überstand'::text,'übersteht'::text,'Das Zelt überstand heute schon zwei Windböen, was auf eine gut beschwerte Konstruktion hindeutet.'::text),
(396061,44007,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Намет сьогодні ... два пориви вітру, що вказує на добре обважену конструкцію.'::text,'витримав'::text,'витримував'::text,'витримує'::text,'Намет сьогодні витримав два пориви вітру, що вказує на добре обважену конструкцію.'::text),
(396060,44007,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La carpa ... dos ráfagas de viento hoy, lo que indica una estructura bien lastrada.'::text,'ha resistido'::text,'ha estado resistiendo'::text,'está resistiendo'::text,'La carpa ha resistido dos ráfagas de viento hoy, lo que indica una estructura bien lastrada.'::text),
(396059,44007,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tente ... deux rafales de vent aujourd''hui, ce qui indique une structure bien lestée.'::text,'a résisté à'::text,'a résisté à'::text,'résiste à'::text,'La tente a résisté à deux rafales de vent aujourd''hui, ce qui indique une structure bien lestée.'::text),
(396062,44007,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çadır bugün iki rüzgâr darbesini ..., bu da iyi ağırlıklandırılmış bir yapıya işaret ediyor.'::text,'atlattı'::text,'atlatıyordu'::text,'atlatıyor'::text,'Çadır bugün iki rüzgâr darbesini atlattı, bu da iyi ağırlıklandırılmış bir yapıya işaret ediyor.'::text),
(396063,44007,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sátor ma két széllökést ..., ami jól lesúlyozott szerkezetre utal.'::text,'vészelt át'::text,'vészelt át'::text,'vészel át'::text,'A sátor ma két széllökést vészelt át, ami jól lesúlyozott szerkezetre utal.'::text),
(396075,44009,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Zelt weiter steht, ... es oben, weil stehen oben sein heißt.'::text,'bleibt'::text,'bliebe'::text,'blieb'::text,'Wenn das Zelt weiter steht, bleibt es oben, weil stehen oben sein heißt.'::text),
(396079,44009,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо намет і далі стоятиме, він ... вгорі, бо стояти означає бути вгорі.'::text,'залишиться'::text,'залишився б'::text,'залишився'::text,'Якщо намет і далі стоятиме, він залишиться вгорі, бо стояти означає бути вгорі.'::text),
(396078,44009,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la carpa sigue en pie, ... arriba, porque estar en pie es estar arriba.'::text,'seguirá'::text,'seguiría'::text,'siguió'::text,'Si la carpa sigue en pie, seguirá arriba, porque estar en pie es estar arriba.'::text),
(396077,44009,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la tente reste debout, elle ... en haut, parce qu''être debout, c''est être en haut.'::text,'restera'::text,'resterait'::text,'est restée'::text,'Si la tente reste debout, elle restera en haut, parce qu''être debout, c''est être en haut.'::text),
(396080,44009,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çadır durmaya devam ederse yukarıda ..., çünkü durmak yukarıda olmak demek.'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Çadır durmaya devam ederse yukarıda kalacak, çünkü durmak yukarıda olmak demek.'::text),
(396081,44009,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sátor tovább áll, fent ..., mert állni annyi, mint fent lenni.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha a sátor tovább áll, fent marad, mert állni annyi, mint fent lenni.'::text),
(396084,44010,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Zelt wie der Bogen zusammenbräche, ... die ganze Party ruiniert!'::text,'wäre'::text,'wird'::text,'ist'::text,'Wenn das Zelt wie der Bogen zusammenbräche, wäre die ganze Party ruiniert!'::text),
(396088,44010,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби намет завалився, як арка, уся вечірка ... зіпсована!'::text,'була б'::text,'буде'::text,'є'::text,'Якби намет завалився, як арка, уся вечірка була б зіпсована!'::text),
(396087,44010,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si la carpa se cayera como el arco, toda la fiesta ... arruinada!'::text,'estaría'::text,'estará'::text,'está'::text,'¡Si la carpa se cayera como el arco, toda la fiesta estaría arruinada!'::text),
(396086,44010,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la tente s''effondrait comme l''arche, toute la fête ... fichue !'::text,'serait'::text,'sera'::text,'est'::text,'Si la tente s''effondrait comme l''arche, toute la fête serait fichue !'::text),
(396089,44010,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çadır kemer gibi çökse bütün parti ...!'::text,'mahvolurdu'::text,'mahvolacak'::text,'mahvoldu'::text,'Çadır kemer gibi çökse bütün parti mahvolurdu!'::text),
(396090,44010,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a sátor összeomlana, mint az ív, az egész buli ...!'::text,'tönkremenne'::text,'tönkremegy'::text,'tönkrement'::text,'Ha a sátor összeomlana, mint az ív, az egész buli tönkremenne!'::text),
(396093,44011,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Partyzelt ... auf dem Rasen aufgebaut, und dann stürzte die Rutsche ein! Totale Katastrophe!'::text,'wurde'::text,'hat'::text,'wird'::text,'Das Partyzelt wurde auf dem Rasen aufgebaut, und dann stürzte die Rutsche ein! Totale Katastrophe!'::text),
(396097,44011,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Святковий намет ... на газоні, а потім завалилася гірка! Повна катастрофа!'::text,'було встановлено'::text,'встановив'::text,'встановлюють'::text,'Святковий намет було встановлено на газоні, а потім завалилася гірка! Повна катастрофа!'::text),
(396096,44011,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La carpa de la fiesta ... en el césped y luego se derrumbó el tobogán! ¡Desastre total!'::text,'fue montada'::text,'montó'::text,'es montada'::text,'¡La carpa de la fiesta fue montada en el césped y luego se derrumbó el tobogán! ¡Desastre total!'::text),
(396095,44011,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tente de fête ... sur la pelouse, et puis le toboggan s''est effondré ! Catastrophe totale !'::text,'a été montée'::text,'a monté'::text,'est montée'::text,'La tente de fête a été montée sur la pelouse, et puis le toboggan s''est effondré ! Catastrophe totale !'::text),
(396098,44011,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parti çadırı çimlere ... ve sonra kaydırak çöktü! Tam bir felaket!'::text,'kuruldu'::text,'kurdu'::text,'kuruluyor'::text,'Parti çadırı çimlere kuruldu ve sonra kaydırak çöktü! Tam bir felaket!'::text),
(396099,44011,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A partisátrat ... a gyepen, aztán összeomlott a csúszda! Totális katasztrófa!'::text,'felállították'::text,'felállította'::text,'felállítják'::text,'A partisátrat felállították a gyepen, aztán összeomlott a csúszda! Totális katasztrófa!'::text),
(396102,44012,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay also, ich hab gehört, jemand hat das Zelt mit einem schweren Gewicht am Fuß ...'::text,'beschwert'::text,'wurde beschwert'::text,'beschwerend'::text,'Okay also, ich hab gehört, jemand hat das Zelt mit einem schweren Gewicht am Fuß beschwert.'::text),
(396106,44012,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що хтось ... намет важким вантажем біля основи.'::text,'притиснув'::text,'був притиснутий'::text,'притискаючи'::text,'Коротше, я чула, що хтось притиснув намет важким вантажем біля основи.'::text),
(396105,44012,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, o sea, oí que alguien ... la carpa con un peso grande en la base.'::text,'sujetó'::text,'fue sujetado'::text,'sujetando'::text,'Vale, o sea, oí que alguien sujetó la carpa con un peso grande en la base.'::text),
(396104,44012,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, j''ai entendu dire que quelqu''un ... la tente avec un gros poids au pied.'::text,'a lesté'::text,'a été lesté'::text,'lestant'::text,'Bon alors, j''ai entendu dire que quelqu''un a lesté la tente avec un gros poids au pied.'::text),
(396107,44012,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, duydum ki biri çadırı dibine ağır bir ağırlık koyarak ...'::text,'sabitlemiş'::text,'sabitlenmiş'::text,'sabitleyerek'::text,'Tamam yani, duydum ki biri çadırı dibine ağır bir ağırlık koyarak sabitlemiş.'::text),
(396108,44012,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval hallottam, hogy valaki ... a sátrat egy nehéz súllyal az aljánál.'::text,'lesúlyozta'::text,'le volt súlyozva'::text,'lesúlyozva'::text,'Oké, szóval hallottam, hogy valaki lesúlyozta a sátrat egy nehéz súllyal az aljánál.'::text),
(396111,44013,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bogen ist platt, also ... das Zelt als Nächstes dran sein. Eine makellose Party, ganz klar.'::text,'könnte'::text,'muss'::text,'kann nicht'::text,'Der Bogen ist platt, also könnte das Zelt als Nächstes dran sein. Eine makellose Party, ganz klar.'::text),
(396115,44013,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Арка здулася, тож намет ... бути наступним. Бездоганна вечірка, очевидно.'::text,'може'::text,'мусить'::text,'не може'::text,'Арка здулася, тож намет може бути наступним. Бездоганна вечірка, очевидно.'::text),
(396114,44013,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El arco está desinflado, así que la carpa ... ser la siguiente. Una fiesta impecable, claramente.'::text,'podría'::text,'debe de'::text,'no puede'::text,'El arco está desinflado, así que la carpa podría ser la siguiente. Una fiesta impecable, claramente.'::text),
(396113,44013,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''arche est à plat, donc la tente ... être la prochaine. Une fête impeccable, clairement.'::text,'pourrait'::text,'doit'::text,'ne peut pas'::text,'L''arche est à plat, donc la tente pourrait être la prochaine. Une fête impeccable, clairement.'::text),
(396116,44013,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kemer sönük, yani sıradaki çadır ... Kusursuz bir parti, belli ki.'::text,'olabilir'::text,'olmalı'::text,'olamaz'::text,'Kemer sönük, yani sıradaki çadır olabilir Kusursuz bir parti, belli ki.'::text),
(396117,44013,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ív leeresztett, szóval a sátor ... a következő. Hibátlan buli, nyilván.'::text,'lehet'::text,'biztos'::text,'nem lehet'::text,'Az ív leeresztett, szóval a sátor lehet a következő. Hibátlan buli, nyilván.'::text),
(390072,43342,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Wasser im Glas ..., während der Lautsprecher Bässe raushaute.'::text,'zitterte'::text,'zitterte'::text,'hat gezittert'::text,'Das Wasser im Glas zitterte, während der Lautsprecher Bässe raushaute.'::text),
(390076,43342,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вода в склянці ..., поки колонка качала баси.'::text,'тремтіла'::text,'затремтіла'::text,'затремтіла'::text,'Вода в склянці тремтіла, поки колонка качала баси.'::text),
(390075,43342,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agua del vaso ... mientras el altavoz soltaba bajos.'::text,'temblaba'::text,'tembló'::text,'ha temblado'::text,'El agua del vaso temblaba mientras el altavoz soltaba bajos.'::text),
(390074,43342,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''eau dans le verre ... pendant que l''enceinte envoyait des basses.'::text,'tremblait'::text,'trembla'::text,'a tremblé'::text,'L''eau dans le verre tremblait pendant que l''enceinte envoyait des basses.'::text),
(390077,43342,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoparlör bas pompalarken bardaktaki su ...'::text,'titriyordu'::text,'titredi'::text,'titremiştir'::text,'Hoparlör bas pompalarken bardaktaki su titriyordu.'::text),
(390078,43342,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pohárban a víz ..., miközben a hangfal nyomta a basszust.'::text,'remegett'::text,'megremegett'::text,'megremegett'::text,'A pohárban a víz remegett, miközben a hangfal nyomta a basszust.'::text),
(390081,43343,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der große Lautsprecher ... schon die ganze Nacht Bässe in den Raum.'::text,'pumpt'::text,'pumpt'::text,'pumpt'::text,'Der große Lautsprecher pumpt schon die ganze Nacht Bässe in den Raum.'::text),
(390085,43343,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велика колонка ... баси в кімнату всю ніч.'::text,'качає'::text,'качає'::text,'качає'::text,'Велика колонка качає баси в кімнату всю ніч.'::text),
(390084,43343,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El altavoz grande ... bajos a la sala toda la noche.'::text,'ha estado metiendo'::text,'está metiendo'::text,'mete'::text,'El altavoz grande ha estado metiendo bajos a la sala toda la noche.'::text),
(390083,43343,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La grosse enceinte ... des basses dans la pièce toute la nuit.'::text,'balance'::text,'balance'::text,'balance'::text,'La grosse enceinte balance des basses dans la pièce toute la nuit.'::text),
(390086,43343,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük hoparlör bütün gece odaya bas ...'::text,'pompalıyor'::text,'pompalıyor'::text,'pompalar'::text,'Büyük hoparlör bütün gece odaya bas pompalıyor.'::text),
(390087,43343,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nagy hangfal egész éjjel ... a basszust a szobába.'::text,'nyomja'::text,'nyomja'::text,'nyomja'::text,'A nagy hangfal egész éjjel nyomja a basszust a szobába.'::text),
(390090,43344,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Glas ... auf dem Tisch, als der Lautsprecher plötzlich vor Bass explodierte!'::text,'stand'::text,'stand'::text,'hat gestanden'::text,'Das Glas stand auf dem Tisch, als der Lautsprecher plötzlich vor Bass explodierte!'::text),
(390094,43344,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Склянка ... на столі, коли колонка раптом вибухнула басом!'::text,'стояла'::text,'стояла'::text,'стояла'::text,'Склянка стояла на столі, коли колонка раптом вибухнула басом!'::text),
(390093,43344,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El vaso ... en la mesa cuando el altavoz de repente explotó de bajos!'::text,'estaba'::text,'estuvo'::text,'ha estado'::text,'¡El vaso estaba en la mesa cuando el altavoz de repente explotó de bajos!'::text),
(390092,43344,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le verre ... sur la table quand l''enceinte a soudain explosé de basses !'::text,'se trouvait'::text,'se trouva'::text,'s''est trouvé'::text,'Le verre se trouvait sur la table quand l''enceinte a soudain explosé de basses !'::text),
(390095,43344,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoparlör aniden basla patladığında bardak masada ...!'::text,'duruyordu'::text,'durdu'::text,'durmuştur'::text,'Hoparlör aniden basla patladığında bardak masada duruyordu!'::text),
(390096,43344,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pohár az asztalon ..., amikor a hangfal hirtelen felrobbant a basszustól!'::text,'állt'::text,'állt'::text,'állt'::text,'A pohár az asztalon állt, amikor a hangfal hirtelen felrobbant a basszustól!'::text),
(390099,43345,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, er hat mir erzählt, dass der Lautsprecher heute Abend schon drei Gläser vom Tisch ...'::text,'gerüttelt hat'::text,'gerüttelt hat'::text,'rüttelt'::text,'Omg, er hat mir erzählt, dass der Lautsprecher heute Abend schon drei Gläser vom Tisch gerüttelt hat.'::text),
(390103,43345,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Боже, він сказав мені, що та колонка сьогодні ввечері ... зі столу три склянки.'::text,'струсила'::text,'струшувала'::text,'струшує'::text,'Боже, він сказав мені, що та колонка сьогодні ввечері струсила зі столу три склянки.'::text),
(390102,43345,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dios, me dijo que ese altavoz ... tres vasos de la mesa esta noche.'::text,'ha tirado'::text,'ha estado tirando'::text,'está tirando'::text,'Dios, me dijo que ese altavoz ha tirado tres vasos de la mesa esta noche.'::text),
(390101,43345,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Omg, il m''a dit que cette enceinte ... trois verres de la table ce soir.'::text,'a fait tomber'::text,'a fait tomber'::text,'fait tomber'::text,'Omg, il m''a dit que cette enceinte a fait tomber trois verres de la table ce soir.'::text),
(390104,43345,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aman Tanrım, bana o hoparlörün bu gece masadan üç bardak ... söyledi.'::text,'düşürdüğünü'::text,'düşürüp durduğunu'::text,'düşürmekte olduğunu'::text,'Aman Tanrım, bana o hoparlörün bu gece masadan üç bardak düşürdüğünü söyledi.'::text),
(390105,43345,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úristen, azt mondta, hogy az a hangfal ma este három poharat ... le az asztalról.'::text,'rázott'::text,'rázogatott'::text,'ráz'::text,'Úristen, azt mondta, hogy az a hangfal ma este három poharat rázott le az asztalról.'::text),
(390108,43346,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay also, als die Tänzer kamen, ... der Lautsprecher das Wasser anscheinend schon aufgewühlt.'::text,'hatte'::text,'hat'::text,'hat'::text,'Okay also, als die Tänzer kamen, hatte der Lautsprecher das Wasser anscheinend schon aufgewühlt.'::text),
(390112,43346,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, поки прийшли танцюристи, колонка вже ... воду.'::text,'сколихнула'::text,'сколихнула'::text,'колихає'::text,'Коротше, кажуть, поки прийшли танцюристи, колонка вже сколихнула воду.'::text),
(390111,43346,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, o sea, parece que para cuando llegaron los bailarines, el altavoz ya ... el agua.'::text,'había agitado'::text,'ha agitado'::text,'agita'::text,'Vale, o sea, parece que para cuando llegaron los bailarines, el altavoz ya había agitado el agua.'::text),
(390110,43346,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment, quand les danseurs sont arrivés, l''enceinte ... l''eau.'::text,'avait agité'::text,'a agité'::text,'agite'::text,'Bon alors, apparemment, quand les danseurs sont arrivés, l''enceinte avait agité l''eau.'::text),
(390113,43346,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam yani, galiba dansçılar geldiğinde hoparlör suyu çoktan ...'::text,'sallamıştı'::text,'salladı'::text,'sallıyor'::text,'Tamam yani, galiba dansçılar geldiğinde hoparlör suyu çoktan sallamıştı.'::text),
(390114,43346,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag mire a táncosok megjöttek, a hangfal már ... a vizet.'::text,'felkavarta'::text,'felkavarta'::text,'felkavarja'::text,'Oké, szóval állítólag mire a táncosok megjöttek, a hangfal már felkavarta a vizet.'::text),
(390117,43347,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, anscheinend macht der Club zu, ... Lautsprecher das Wasserglas zum Zittern gebracht hat.'::text,'dessen'::text,'der'::text,'wer'::text,'Rate mal, anscheinend macht der Club zu, dessen Lautsprecher das Wasserglas zum Zittern gebracht hat.'::text),
(390121,43347,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, кажуть, клуб, ... колонка трусила склянку з водою, закривається.'::text,'чия'::text,'який'::text,'хто'::text,'Вгадай що, кажуть, клуб, чия колонка трусила склянку з водою, закривається.'::text),
(390120,43347,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, parece que el club ... altavoz hizo temblar el vaso de agua va a cerrar.'::text,'cuyo'::text,'que'::text,'quien'::text,'Adivina qué, parece que el club cuyo altavoz hizo temblar el vaso de agua va a cerrar.'::text),
(390119,43347,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, apparemment le club ... l''enceinte a fait trembler le verre d''eau ferme.'::text,'dont'::text,'que'::text,'qui'::text,'Devine quoi, apparemment le club dont l''enceinte a fait trembler le verre d''eau ferme.'::text),
(390122,43347,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, galiba ... hoparlörü su bardağını titreten kulüp kapanıyor.'::text,''::text,NULL::text,NULL::text,'Bil bakalım, galiba hoparlörü su bardağını titreten kulüp kapanıyor.'::text),
(390123,43347,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, állítólag bezár a klub, ... hangfala megrázta a vizespoharat.'::text,'amelynek'::text,'amely'::text,'aki'::text,'Képzeld, állítólag bezár a klub, amelynek hangfala megrázta a vizespoharat.'::text),
(390126,43348,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast gesagt, dieser Lautsprecher ... den besten Bass der Stadt, und ehrlich, du hattest recht.'::text,'hätte'::text,'hat'::text,'bekommt'::text,'Du hast gesagt, dieser Lautsprecher hätte den besten Bass der Stadt, und ehrlich, du hattest recht.'::text),
(390130,43348,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти казав, що ця колонка ... найкращі баси в місті, і чесно, ти мав рацію.'::text,'має'::text,'має'::text,'матиме'::text,'Ти казав, що ця колонка має найкращі баси в місті, і чесно, ти мав рацію.'::text),
(390129,43348,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijiste que este altavoz ... los mejores bajos de la ciudad y, sinceramente, tenías razón.'::text,'tenía'::text,'tiene'::text,'tendrá'::text,'Dijiste que este altavoz tenía los mejores bajos de la ciudad y, sinceramente, tenías razón.'::text),
(390128,43348,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu as dit que cette enceinte ... les meilleures basses de la ville, et franchement, tu avais raison.'::text,'avait'::text,'a'::text,'aura'::text,'Tu as dit que cette enceinte avait les meilleures basses de la ville, et franchement, tu avais raison.'::text),
(390131,43348,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu hoparlörün şehirdeki en iyi basa ... söyledin ve açıkçası haklıydın.'::text,'sahip olduğunu'::text,'sahip olduğunu'::text,'sahip olacağını'::text,'Bu hoparlörün şehirdeki en iyi basa sahip olduğunu söyledin ve açıkçası haklıydın.'::text),
(390132,43348,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, ennek a hangfalnak ... a legjobb basszusa a városban, és őszintén, igazad volt.'::text,'van'::text,'van'::text,'lesz'::text,'Azt mondtad, ennek a hangfalnak van a legjobb basszusa a városban, és őszintén, igazad volt.'::text),
(390144,43350,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Glas kommt neben dem Lautsprecher aus dem ... gar nicht mehr raus. Ein sehr ruhiger Tisch, ganz klar.'::text,'Zittern'::text,'Zittern'::text,'Zittern'::text,'Das Glas kommt neben dem Lautsprecher aus dem Zittern gar nicht mehr raus. Ein sehr ruhiger Tisch, ganz klar.'::text),
(390148,43350,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Склянка не може перестати ... біля колонки. Дуже спокійний стіл, очевидно.'::text,'тремтіти'::text,'тремтіти'::text,'тремтіти'::text,'Склянка не може перестати тремтіти біля колонки. Дуже спокійний стіл, очевидно.'::text),
(390147,43350,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El vaso no puede dejar de ... junto al altavoz. Una mesa muy tranquila, claramente.'::text,'temblar'::text,'temblar'::text,'temblar'::text,'El vaso no puede dejar de temblar junto al altavoz. Una mesa muy tranquila, claramente.'::text),
(390146,43350,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le verre n''arrête pas de ... à côté de l''enceinte. Une table très calme, clairement.'::text,'trembler'::text,'trembler'::text,'trembler'::text,'Le verre n''arrête pas de trembler à côté de l''enceinte. Une table très calme, clairement.'::text),
(390149,43350,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bardak hoparlörün yanında ... duramıyor. Çok sakin bir masa, belli ki.'::text,'titremeden'::text,'titremeden'::text,'titremeden'::text,'Bardak hoparlörün yanında titremeden duramıyor. Çok sakin bir masa, belli ki.'::text),
(390150,43350,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pohár nem tudja abbahagyni a ... a hangfal mellett. Nagyon nyugodt asztal, nyilván.'::text,'remegést'::text,'remegést'::text,'remegést'::text,'A pohár nem tudja abbahagyni a remegést a hangfal mellett. Nagyon nyugodt asztal, nyilván.'::text),
(390153,43351,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Lautsprecher ... gerade den ganzen Club. Ein kleines bisschen laut, wenn man die Augen zukneift.'::text,'erschüttert'::text,'erschüttert'::text,'erschütterte'::text,'Der Lautsprecher erschüttert gerade den ganzen Club. Ein kleines bisschen laut, wenn man die Augen zukneift.'::text),
(390157,43351,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колонка ... весь клуб прямо зараз. Трохи гучно, якщо примружитися.'::text,'трясе'::text,'трясе'::text,'струснула'::text,'Колонка трясе весь клуб прямо зараз. Трохи гучно, якщо примружитися.'::text),
(390156,43351,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El altavoz ... todo el club ahora mismo. Un pelín alto, si entrecierras los ojos.'::text,'está sacudiendo'::text,'sacude'::text,'ha sacudido'::text,'El altavoz está sacudiendo todo el club ahora mismo. Un pelín alto, si entrecierras los ojos.'::text),
(390155,43351,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''enceinte ... tout le club en ce moment. Légèrement fort, si on plisse les yeux.'::text,'fait trembler'::text,'fait trembler'::text,'a fait trembler'::text,'L''enceinte fait trembler tout le club en ce moment. Légèrement fort, si on plisse les yeux.'::text),
(390158,43351,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoparlör bütün kulübü ... şu anda. Gözünü kısarsan biraz gürültülü.'::text,'sallıyor'::text,'sallar'::text,'salladı'::text,'Hoparlör bütün kulübü sallıyor şu anda. Gözünü kısarsan biraz gürültülü.'::text),
(390159,43351,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hangfal éppen ... az egész klubot. Kicsit hangos, ha hunyorogsz.'::text,'rázza'::text,'rázza'::text,'megrázta'::text,'A hangfal éppen rázza az egész klubot. Kicsit hangos, ha hunyorogsz.'::text),
(336207,37357,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während zwei Hände den Apfelzweig zu einem Bogen ..., fielen ein paar Blätter ins Gras.'::text,'bogen'::text,'bogen'::text,'gebogen haben'::text,'Während zwei Hände den Apfelzweig zu einem Bogen bogen, fielen ein paar Blätter ins Gras.'::text),
(336211,37357,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки дві руки ... яблуневу гілку в дугу, кілька листків упало на траву.'::text,'згинали'::text,'зігнули'::text,'зігнули'::text,'Поки дві руки згинали яблуневу гілку в дугу, кілька листків упало на траву.'::text),
(336210,37357,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras dos manos ... la rama del manzano en un arco, unas hojas cayeron al césped.'::text,'doblaban'::text,'doblaron'::text,'han doblado'::text,'Mientras dos manos doblaban la rama del manzano en un arco, unas hojas cayeron al césped.'::text),
(336209,37357,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que deux mains ... la branche du pommier en arc, quelques feuilles sont tombées sur l''herbe.'::text,'pliaient'::text,'plièrent'::text,'ont plié'::text,'Pendant que deux mains pliaient la branche du pommier en arc, quelques feuilles sont tombées sur l''herbe.'::text),
(336212,37357,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki el elma dalını kavis şeklinde ..., birkaç yaprak çimlere düştü.'::text,'bükerken'::text,'büktüğünde'::text,'bükmüşken'::text,'İki el elma dalını kavis şeklinde bükerken, birkaç yaprak çimlere düştü.'::text),
(336213,37357,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben két kéz ívbe ... az almafaágat, néhány levél a fűre hullott.'::text,'hajlította'::text,'meghajlította'::text,'meghajlította'::text,'Miközben két kéz ívbe hajlította az almafaágat, néhány levél a fűre hullott.'::text),
(336216,37358,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diese Hände ... schon seit zehn Minuten an demselben armen Apfelzweig. Super Arbeit.'::text,'ziehen'::text,'ziehen'::text,'ziehen'::text,'Diese Hände ziehen schon seit zehn Minuten an demselben armen Apfelzweig. Super Arbeit.'::text),
(336220,37358,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ці руки ... ту саму бідну яблуневу гілку вже десять хвилин. Чудова робота.'::text,'тягнуть'::text,'тягнуть'::text,'тягнуть'::text,'Ці руки тягнуть ту саму бідну яблуневу гілку вже десять хвилин. Чудова робота.'::text),
(336219,37358,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esas manos ... de la misma pobre rama de manzano desde hace diez minutos. Buen trabajo.'::text,'han estado tirando'::text,'están tirando'::text,'tiran'::text,'Esas manos han estado tirando de la misma pobre rama de manzano desde hace diez minutos. Buen trabajo.'::text),
(336218,37358,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ces mains ... sur la même pauvre branche de pommier depuis dix minutes. Beau travail.'::text,'tirent'::text,'tirent'::text,'tirent'::text,'Ces mains tirent sur la même pauvre branche de pommier depuis dix minutes. Beau travail.'::text),
(336221,37358,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O eller on dakikadır ... aynı zavallı elma dalını. Harika iş.'::text,'çekiştiriyor'::text,'çekiştiriyor'::text,'çekiştirir'::text,'O eller on dakikadır çekiştiriyor aynı zavallı elma dalını. Harika iş.'::text),
(336222,37358,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azok a kezek már tíz perce ... ugyanazt a szegény almafaágat. Szép munka.'::text,'húzzák'::text,'húzzák'::text,'húzzák'::text,'Azok a kezek már tíz perce húzzák ugyanazt a szegény almafaágat. Szép munka.'::text),
(336234,37360,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bisher ... jemand einen Plastikstreifen und einen Apfelzweig zu Kurven gebogen. Ein echter Profi.'::text,'hat'::text,'hat'::text,'hat'::text,'Bisher hat jemand einen Plastikstreifen und einen Apfelzweig zu Kurven gebogen. Ein echter Profi.'::text),
(336238,37360,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки що хтось ... в дуги пластикову смужку і яблуневу гілку. Справжній професіонал.'::text,'зігнув'::text,'згинав'::text,'зігнув'::text,'Поки що хтось зігнув в дуги пластикову смужку і яблуневу гілку. Справжній професіонал.'::text),
(336237,37360,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta ahora, alguien ... una tira de plástico y una rama de manzano en curvas. Todo un profesional.'::text,'ha doblado'::text,'ha estado doblando'::text,'dobló'::text,'Hasta ahora, alguien ha doblado una tira de plástico y una rama de manzano en curvas. Todo un profesional.'::text),
(336236,37360,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jusqu''ici, quelqu''un ... une bande de plastique et une branche de pommier en courbes. Un vrai pro.'::text,'a plié'::text,'a plié'::text,'plia'::text,'Jusqu''ici, quelqu''un a plié une bande de plastique et une branche de pommier en courbes. Un vrai pro.'::text),
(336239,37360,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdiye kadar biri bir plastik şeridi ve bir elma dalını kavis şeklinde ... Gerçek bir profesyonel.'::text,'büktü'::text,'büküp duruyor'::text,'büktü'::text,'Şimdiye kadar biri bir plastik şeridi ve bir elma dalını kavis şeklinde büktü Gerçek bir profesyonel.'::text),
(336240,37360,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eddig valaki ívesre ... egy műanyag csíkot és egy almafaágat. Igazi profi.'::text,'hajlított'::text,'hajlítgatott'::text,'hajlított'::text,'Eddig valaki ívesre hajlított egy műanyag csíkot és egy almafaágat. Igazi profi.'::text),
(336243,37361,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor jemand sie aufhalten konnte, ... die Hände den Zweig zu einem furchterregenden Bogen gezogen!'::text,'hatten'::text,'haben'::text,'ziehen'::text,'Bevor jemand sie aufhalten konnte, hatten die Hände den Zweig zu einem furchterregenden Bogen gezogen!'::text),
(336247,37361,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж хтось встиг їх зупинити, руки ... гілку в страшну дугу!'::text,'вже зігнули'::text,'зігнули'::text,'згинають'::text,'Перш ніж хтось встиг їх зупинити, руки вже зігнули гілку в страшну дугу!'::text),
(336246,37361,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Antes de que nadie pudiera detenerlas, las manos ... la rama en un arco aterrador!'::text,'habían tirado de'::text,'han tirado de'::text,'tiran de'::text,'¡Antes de que nadie pudiera detenerlas, las manos habían tirado de la rama en un arco aterrador!'::text),
(336245,37361,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant que quiconque puisse les arrêter, les mains ... la branche en un arc terrifiant !'::text,'avaient tiré'::text,'ont tiré'::text,'tirent'::text,'Avant que quiconque puisse les arrêter, les mains avaient tiré la branche en un arc terrifiant !'::text),
(336248,37361,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse onları durduramadan eller dalı korkunç bir kavis haline ...!'::text,'getirmişti'::text,'getirdi'::text,'getiriyor'::text,'Kimse onları durduramadan eller dalı korkunç bir kavis haline getirmişti!'::text),
(336249,37361,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt bárki megállíthatta volna őket, a kezek ... az ágat egy ijesztő ívbe!'::text,'már lehúzták'::text,'lehúzták'::text,'lehúzzák'::text,'Mielőtt bárki megállíthatta volna őket, a kezek már lehúzták az ágat egy ijesztő ívbe!'::text),
(336252,37362,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn diese Hände noch fester ziehen, ... der Zweig in zwei Teile! Katastrophe!'::text,'bricht'::text,'bräche'::text,'brach'::text,'Wenn diese Hände noch fester ziehen, bricht der Zweig in zwei Teile! Katastrophe!'::text),
(336256,37362,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ці руки потягнуть ще сильніше, гілка ... навпіл! Катастрофа!'::text,'зламається'::text,'зламалася б'::text,'зламалася'::text,'Якщо ці руки потягнуть ще сильніше, гілка зламається навпіл! Катастрофа!'::text),
(336255,37362,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si esas manos tiran más fuerte, la rama ... en dos! ¡Desastre!'::text,'se partirá'::text,'se partiría'::text,'se partió'::text,'¡Si esas manos tiran más fuerte, la rama se partirá en dos! ¡Desastre!'::text),
(336254,37362,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si ces mains tirent encore plus fort, la branche ... en deux ! Catastrophe !'::text,'cassera'::text,'casserait'::text,'a cassé'::text,'Si ces mains tirent encore plus fort, la branche cassera en deux ! Catastrophe !'::text),
(336257,37362,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O eller biraz daha sert çekerse dal ikiye ...! Felaket!'::text,'kırılacak'::text,'kırılırdı'::text,'kırıldı'::text,'O eller biraz daha sert çekerse dal ikiye kırılacak! Felaket!'::text),
(336258,37362,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha azok a kezek még erősebben húzzák, az ág ... ketté! Katasztrófa!'::text,'törik'::text,'törne'::text,'tört'::text,'Ha azok a kezek még erősebben húzzák, az ág törik ketté! Katasztrófa!'::text),
(336261,37363,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Zweig so dick wie der Stahlträger wäre, ... ihn nur die Presse biegen.'::text,'würde'::text,'wird'::text,'wird'::text,'Wenn der Zweig so dick wie der Stahlträger wäre, würde ihn nur die Presse biegen.'::text),
(336265,37363,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби гілка була така товста, як сталева балка, її ... лише прес.'::text,'зігнув би'::text,'зігне'::text,'згинає'::text,'Якби гілка була така товста, як сталева балка, її зігнув би лише прес.'::text),
(336264,37363,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la rama fuera tan gruesa como la viga de acero, solo la prensa la ...'::text,'doblaría'::text,'doblará'::text,'dobla'::text,'Si la rama fuera tan gruesa como la viga de acero, solo la prensa la doblaría.'::text),
(336263,37363,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la branche était aussi épaisse que la poutre en acier, seule la presse la ...'::text,'plierait'::text,'pliera'::text,'plie'::text,'Si la branche était aussi épaisse que la poutre en acier, seule la presse la plierait.'::text),
(336266,37363,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dal çelik kiriş kadar kalın olsaydı, onu sadece pres ...'::text,'bükerdi'::text,'bükecek'::text,'büker'::text,'Dal çelik kiriş kadar kalın olsaydı, onu sadece pres bükerdi.'::text),
(336267,37363,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az ág olyan vastag lenne, mint az acélgerenda, csak a prés ...'::text,'hajlítaná meg'::text,'fogja meghajlítani'::text,'hajlítja meg'::text,'Ha az ág olyan vastag lenne, mint az acélgerenda, csak a prés hajlítaná meg.'::text),
(336270,37364,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ... dieser Apfelzweig gestern von zwei random Händen zu einem Bogen gezogen.'::text,'wurde'::text,'wird'::text,'zog'::text,'Bestie, anscheinend wurde dieser Apfelzweig gestern von zwei random Händen zu einem Bogen gezogen.'::text),
(336274,37364,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, та яблунева гілка вчора ... в дугу двома випадковими руками.'::text,'була зігнута'::text,'згинається'::text,'зігнула'::text,'Подруго, кажуть, та яблунева гілка вчора була зігнута в дугу двома випадковими руками.'::text),
(336273,37364,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, parece que esa rama de manzano ... en arco por dos manos random ayer.'::text,'fue curvada'::text,'es curvada'::text,'curvó'::text,'Amiga, parece que esa rama de manzano fue curvada en arco por dos manos random ayer.'::text),
(336272,37364,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment cette branche de pommier ... en arc par deux mains random hier.'::text,'a été tirée'::text,'est tirée'::text,'a tiré'::text,'Ma belle, apparemment cette branche de pommier a été tirée en arc par deux mains random hier.'::text),
(336275,37364,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, galiba o elma dalı dün rastgele iki el tarafından kavis şeklinde ...'::text,'çekilmiş'::text,'çekiliyor'::text,'çekmiş'::text,'Kanka, galiba o elma dalı dün rastgele iki el tarafından kavis şeklinde çekilmiş.'::text),
(336276,37364,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag azt az almafaágat tegnap két random kéz ... ívbe.'::text,'húzta'::text,'húzza'::text,'húzott'::text,'Csajszi, állítólag azt az almafaágat tegnap két random kéz húzta ívbe.'::text),
(336279,37365,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei Hände ... einen dicken Apfelzweig über dem Garten zu einem Bogen.'::text,'zogen'::text,'wurden gezogen'::text,'ziehend'::text,'Zwei Hände zogen einen dicken Apfelzweig über dem Garten zu einem Bogen.'::text),
(336283,37365,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві руки ... товсту яблуневу гілку в дугу над садом.'::text,'зігнули'::text,'були зігнуті'::text,'згинаючи'::text,'Дві руки зігнули товсту яблуневу гілку в дугу над садом.'::text),
(336282,37365,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dos manos ... una gruesa rama de manzano en arco sobre el jardín.'::text,'curvaron'::text,'fueron curvadas'::text,'curvando'::text,'Dos manos curvaron una gruesa rama de manzano en arco sobre el jardín.'::text),
(336281,37365,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux mains ... une grosse branche de pommier en arc au-dessus du jardin.'::text,'ont tiré'::text,'ont été tirées'::text,'tirant'::text,'Deux mains ont tiré une grosse branche de pommier en arc au-dessus du jardin.'::text),
(336284,37365,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki el kalın bir elma dalını bahçenin üzerinde kavis şeklinde ...'::text,'çekti'::text,'çekildi'::text,'çekerek'::text,'İki el kalın bir elma dalını bahçenin üzerinde kavis şeklinde çekti.'::text),
(336285,37365,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két kéz ... egy vastag almafaágat ívbe a kert fölött.'::text,'húzott'::text,'húzva volt'::text,'húzva'::text,'Két kéz húzott egy vastag almafaágat ívbe a kert fölött.'::text),
(336288,37366,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Zweig biegt sich zu einem Bogen, ohne zu knacken, also ... tot und trocken sein.'::text,'kann er nicht'::text,'muss er'::text,'könnte er'::text,'Der Zweig biegt sich zu einem Bogen, ohne zu knacken, also kann er nicht tot und trocken sein.'::text),
(336292,37366,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гілка згинається в дугу без тріску, тож вона ... бути мертвою й сухою.'::text,'не може'::text,'мусить'::text,'може'::text,'Гілка згинається в дугу без тріску, тож вона не може бути мертвою й сухою.'::text),
(336291,37366,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La rama se dobla en arco sin romperse, así que ... estar muerta y seca.'::text,'no puede'::text,'debe de'::text,'podría'::text,'La rama se dobla en arco sin romperse, así que no puede estar muerta y seca.'::text),
(336290,37366,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La branche se plie en arc sans craquer, donc elle ... être morte et sèche.'::text,'ne peut pas'::text,'doit'::text,'pourrait'::text,'La branche se plie en arc sans craquer, donc elle ne peut pas être morte et sèche.'::text),
(336293,37366,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dal çatlamadan kavis şeklinde bükülüyor, yani ölü ve kuru ...'::text,'olamaz'::text,'olmalı'::text,'olabilir'::text,'Dal çatlamadan kavis şeklinde bükülüyor, yani ölü ve kuru olamaz.'::text),
(336294,37366,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ág reccsenés nélkül ívbe hajlik, szóval ... halott és száraz.'::text,'nem lehet'::text,'biztos'::text,'lehet'::text,'Az ág reccsenés nélkül ívbe hajlik, szóval nem lehet halott és száraz.'::text),
(362514,40280,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Trainerin ... stundenlang denselben Kick, bevor das Holzbrett komplett zersplitterte!'::text,'übte'::text,'übt'::text,'übte gerade'::text,'Die Trainerin übte stundenlang denselben Kick, bevor das Holzbrett komplett zersplitterte!'::text),
(362518,40280,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Інструкторка ... той самий удар годинами, перш ніж дерев''яна дошка повністю розлетілася!'::text,'відпрацьовувала'::text,'відпрацьовує'::text,'відпрацьовувала'::text,'Інструкторка відпрацьовувала той самий удар годинами, перш ніж дерев''яна дошка повністю розлетілася!'::text),
(362517,40280,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La instructora ... la misma patada durante horas antes de que la tabla de madera se hiciera añicos!'::text,'había estado practicando'::text,'ha estado practicando'::text,'estaba practicando'::text,'¡La instructora había estado practicando la misma patada durante horas antes de que la tabla de madera se hiciera añicos!'::text),
(362516,40280,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''instructrice ... le même coup de pied pendant des heures avant que la planche en bois vole en éclats !'::text,'avait répété'::text,'a répété'::text,'répétait'::text,'L''instructrice avait répété le même coup de pied pendant des heures avant que la planche en bois vole en éclats !'::text),
(362519,40280,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahşap tahta tamamen parçalanmadan önce eğitmen aynı tekmeyi saatlerce ...!'::text,'çalışıyordu'::text,'çalışıyor'::text,'çalışıyordu'::text,'Ahşap tahta tamamen parçalanmadan önce eğitmen aynı tekmeyi saatlerce çalışıyordu!'::text),
(362520,40280,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az oktató órákon át ... ugyanazt a rúgást, mielőtt a fadeszka teljesen szétrepedt!'::text,'gyakorolta'::text,'gyakorolja'::text,'gyakorolta'::text,'Az oktató órákon át gyakorolta ugyanazt a rúgást, mielőtt a fadeszka teljesen szétrepedt!'::text),
(362523,40281,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, anscheinend wird die Trainerin bis Juni fünfzig neue Schwarzgurte ...'::text,'ausgebildet haben'::text,'ausbilden'::text,'am Ausbilden sein'::text,'Girl, anscheinend wird die Trainerin bis Juni fünfzig neue Schwarzgurte ausgebildet haben.'::text),
(362527,40281,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, до червня інструкторка ... п''ятдесят нових чорних поясів.'::text,'підготує'::text,'підготує'::text,'готуватиме'::text,'Подруго, кажуть, до червня інструкторка підготує п''ятдесят нових чорних поясів.'::text),
(362526,40281,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que para junio la instructora ... a cincuenta nuevos cinturones negros.'::text,'habrá entrenado'::text,'entrenará'::text,'estará entrenando'::text,'Tía, parece que para junio la instructora habrá entrenado a cincuenta nuevos cinturones negros.'::text),
(362525,40281,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment d''ici juin, l''instructrice ... cinquante nouvelles ceintures noires.'::text,'aura formé'::text,'formera'::text,'sera en train de former'::text,'Meuf, apparemment d''ici juin, l''instructrice aura formé cinquante nouvelles ceintures noires.'::text),
(362528,40281,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, galiba haziran ayına kadar eğitmen elli yeni siyah kuşak ...'::text,'yetiştirmiş olacak'::text,'yetiştirecek'::text,'yetiştiriyor olacak'::text,'Kızım, galiba haziran ayına kadar eğitmen elli yeni siyah kuşak yetiştirmiş olacak.'::text),
(362529,40281,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag júniusra az oktató ... ötven új fekete övest.'::text,'kiképez'::text,'ki fog képezni'::text,'képezni fog'::text,'Csajszi, állítólag júniusra az oktató kiképez ötven új fekete övest.'::text),
(362532,40282,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, dass die Trainerin im September schon zwanzig Jahre Karate ...'::text,'unterrichtet'::text,'unterrichten wird'::text,'unterrichtet haben wird'::text,'Hör mal, ich hab gehört, dass die Trainerin im September schon zwanzig Jahre Karate unterrichtet.'::text),
(362536,40282,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що у вересні інструкторка вже ... карате двадцять років.'::text,'викладатиме'::text,'викладатиме'::text,'викладатиме'::text,'Слухай, я чула, що у вересні інструкторка вже викладатиме карате двадцять років.'::text),
(362535,40282,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que para septiembre la instructora ... karate durante veinte años.'::text,'habrá estado enseñando'::text,'estará enseñando'::text,'habrá enseñado'::text,'Oye, me han dicho que para septiembre la instructora habrá estado enseñando karate durante veinte años.'::text),
(362534,40282,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''en septembre, l''instructrice ... le karaté depuis vingt ans.'::text,'enseignera'::text,'enseignera'::text,'aura enseigné'::text,'Écoute, j''ai entendu dire qu''en septembre, l''instructrice enseignera le karaté depuis vingt ans.'::text),
(362537,40282,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duydum ki eğitmen eylülde yirmi yıldır karate ...'::text,'öğretiyor olacak'::text,'öğretiyor olacak'::text,'öğretmiş olacak'::text,'Dinle, duydum ki eğitmen eylülde yirmi yıldır karate öğretiyor olacak.'::text),
(362538,40282,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy szeptemberre az oktató már húsz éve ... karatét.'::text,'tanít'::text,'fog tanítani'::text,'tanított'::text,'Figyelj, azt hallottam, hogy szeptemberre az oktató már húsz éve tanít karatét.'::text),
(362541,40283,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sich die Schüler nicht verbeugt hätten, ... die Trainerin mit der Stunde nicht angefangen.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn sich die Schüler nicht verbeugt hätten, hätte die Trainerin mit der Stunde nicht angefangen.'::text),
(362545,40283,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби учні не вклонилися, інструкторка ... заняття.'::text,'не почала б'::text,'не почне'::text,'не почала'::text,'Якби учні не вклонилися, інструкторка не почала б заняття.'::text),
(362544,40283,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si los alumnos no se hubieran inclinado, la instructora ... la clase.'::text,'no habría empezado'::text,'no empezará'::text,'no empezó'::text,'Si los alumnos no se hubieran inclinado, la instructora no habría empezado la clase.'::text),
(362543,40283,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les élèves ne s''étaient pas inclinés, l''instructrice ... le cours.'::text,'n''aurait pas commencé'::text,'ne commencera pas'::text,'n''a pas commencé'::text,'Si les élèves ne s''étaient pas inclinés, l''instructrice n''aurait pas commencé le cours.'::text),
(362546,40283,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğrenciler eğilmeseydi eğitmen derse ...'::text,'başlamazdı'::text,'başlamayacak'::text,'başlamadı'::text,'Öğrenciler eğilmeseydi eğitmen derse başlamazdı.'::text),
(362547,40283,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a diákok nem hajoltak volna meg, az oktató ... az órát.'::text,'nem kezdte volna el'::text,'nem kezdi el'::text,'nem kezdte el'::text,'Ha a diákok nem hajoltak volna meg, az oktató nem kezdte volna el az órát.'::text),
(362550,40284,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Trainerin nicht jahrelang trainiert hätte, ... sie jetzt keinen schwarzen Gürtel.'::text,'hätte'::text,'hätte'::text,'hat'::text,'Wenn die Trainerin nicht jahrelang trainiert hätte, hätte sie jetzt keinen schwarzen Gürtel.'::text),
(362554,40284,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби інструкторка не тренувалася роками, вона ... чорного пояса зараз.'::text,'не мала б'::text,'не мала б'::text,'не матиме'::text,'Якби інструкторка не тренувалася роками, вона не мала б чорного пояса зараз.'::text),
(362553,40284,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la instructora no hubiera entrenado durante años, ahora ... cinturón negro.'::text,'no tendría'::text,'no habría tenido'::text,'no tendrá'::text,'Si la instructora no hubiera entrenado durante años, ahora no tendría cinturón negro.'::text),
(362552,40284,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''instructrice ne s''était pas entraînée pendant des années, elle ... de ceinture noire maintenant.'::text,'n''aurait pas'::text,'n''aurait pas eu'::text,'n''aura pas'::text,'Si l''instructrice ne s''était pas entraînée pendant des années, elle n''aurait pas de ceinture noire maintenant.'::text),
(362555,40284,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitmen yıllarca çalışmasaydı, şimdi siyah kuşağı ...'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Eğitmen yıllarca çalışmasaydı, şimdi siyah kuşağı olmazdı.'::text),
(362556,40284,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az oktató nem edzett volna évekig, most ... fekete öve.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Ha az oktató nem edzett volna évekig, most nem lenne fekete öve.'::text),
(362559,40285,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Man glaubt, dass die Trainerin als junge Frau in Japan Karate ...'::text,'studiert hat'::text,'studiert'::text,'studierend'::text,'Man glaubt, dass die Trainerin als junge Frau in Japan Karate studiert hat.'::text),
(362563,40285,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що інструкторка ... карате в Японії, коли була молодою.'::text,'вивчала'::text,'вивчати'::text,'вивчення'::text,'Вважається, що інструкторка вивчала карате в Японії, коли була молодою.'::text),
(362562,40285,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la instructora ... karate en Japón de joven.'::text,'estudió'::text,'estudia'::text,'estudiando'::text,'Se cree que la instructora estudió karate en Japón de joven.'::text),
(362561,40285,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que l''instructrice ... le karaté au Japon quand elle était jeune.'::text,'a étudié'::text,'étudie'::text,'étudiant'::text,'On pense que l''instructrice a étudié le karaté au Japon quand elle était jeune.'::text),
(362564,40285,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitmenin genç bir kadınken Japonya''da karate ... düşünülüyor.'::text,'çalıştığı'::text,'çalışmak'::text,'çalışarak'::text,'Eğitmenin genç bir kadınken Japonya''da karate çalıştığı düşünülüyor.'::text),
(362565,40285,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy az oktató fiatal nőként Japánban ... karatét.'::text,'tanult'::text,'tanul'::text,'tanulva'::text,'Úgy tartják, hogy az oktató fiatal nőként Japánban tanult karatét.'::text),
(362568,40286,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Trainerin erinnerte die Klasse daran, sich vor jeder Stunde ...'::text,'zu verbeugen'::text,'zu verbeugen'::text,'verbeugen'::text,'Die Trainerin erinnerte die Klasse daran, sich vor jeder Stunde zu verbeugen.'::text),
(362572,40286,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Інструкторка нагадала класу, ... перед кожним заняттям.'::text,'щоб вклонялися'::text,'вклоняння'::text,'що вклонитися'::text,'Інструкторка нагадала класу, щоб вклонялися перед кожним заняттям.'::text),
(362571,40286,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La instructora le recordó a la clase ... antes de cada sesión.'::text,'que se inclinaran'::text,'inclinarse'::text,'que se inclinan'::text,'La instructora le recordó a la clase que se inclinaran antes de cada sesión.'::text),
(362570,40286,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''instructrice a rappelé à la classe ... avant chaque cours.'::text,'de saluer'::text,'saluer'::text,'qu''ils saluent'::text,'L''instructrice a rappelé à la classe de saluer avant chaque cours.'::text),
(362573,40286,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitmen sınıfa her dersten önce ... hatırlattı.'::text,'eğilmelerini'::text,'eğilmeyi'::text,'eğildiklerini'::text,'Eğitmen sınıfa her dersten önce eğilmelerini hatırlattı.'::text),
(362574,40286,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az oktató emlékeztette az osztályt, ... minden óra előtt.'::text,'hogy hajoljanak meg'::text,'a meghajlásra'::text,'hogy meghajolnak'::text,'Az oktató emlékeztette az osztályt, hogy hajoljanak meg minden óra előtt.'::text),
(362586,40288,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... führt eine Trainerin einen Kick mit solcher Präzision vor, wie hier beobachtet.'::text,''::text,'hat'::text,'ist'::text,'Selten führt eine Trainerin einen Kick mit solcher Präzision vor, wie hier beobachtet.'::text),
(362590,40288,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... інструктор демонструє удар з такою точністю, як тут спостерігається.'::text,''::text,'має'::text,'є'::text,'Рідко інструктор демонструє удар з такою точністю, як тут спостерігається.'::text),
(362589,40288,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... un instructor demuestra una patada con tanta precisión, como se observa aquí.'::text,''::text,'ha'::text,'es'::text,'Rara vez un instructor demuestra una patada con tanta precisión, como se observa aquí.'::text),
(362588,40288,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... un instructeur démontre un coup de pied avec une telle précision, comme observé ici.'::text,''::text,'a'::text,'est'::text,'Rarement un instructeur démontre un coup de pied avec une telle précision, comme observé ici.'::text),
(362591,40288,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren ... bir eğitmen, burada gözlemlendiği gibi, bir tekmeyi bu kadar hassasiyetle gösterir.'::text,''::text,NULL::text,NULL::text,'Nadiren bir eğitmen, burada gözlemlendiği gibi, bir tekmeyi bu kadar hassasiyetle gösterir.'::text),
(362592,40288,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... mutat be egy oktató ilyen pontossággal egy rúgást, ahogy itt megfigyelhető.'::text,''::text,NULL::text,NULL::text,'Ritkán mutat be egy oktató ilyen pontossággal egy rúgást, ahogy itt megfigyelhető.'::text),
(362595,40289,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Trainerin ließ die ganze Klasse diesen Kick hundertmal ...! Pure Qual!'::text,'wiederholen'::text,'wiederholen'::text,'wiederholen'::text,'Die Trainerin ließ die ganze Klasse diesen Kick hundertmal wiederholen! Pure Qual!'::text),
(362599,40289,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Інструкторка змусила весь клас ... той удар сто разів! Чиста мука!'::text,'повторити'::text,'повторити'::text,'повторення'::text,'Інструкторка змусила весь клас повторити той удар сто разів! Чиста мука!'::text),
(362598,40289,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La instructora hizo que toda la clase ... esa patada cien veces! ¡Puro sufrimiento!'::text,'repitiera'::text,'repitiera'::text,'repitiendo'::text,'¡La instructora hizo que toda la clase repitiera esa patada cien veces! ¡Puro sufrimiento!'::text),
(362597,40289,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''instructrice a fait ... ce coup de pied cent fois à toute la classe ! Pure agonie !'::text,'répéter'::text,'répéter'::text,'répétant'::text,'L''instructrice a fait répéter ce coup de pied cent fois à toute la classe ! Pure agonie !'::text),
(362600,40289,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eğitmen bütün sınıfa o tekmeyi yüz kez ...! Tam bir işkence!'::text,'tekrarlattı'::text,'tekrarlattı'::text,'tekrarlatarak'::text,'Eğitmen bütün sınıfa o tekmeyi yüz kez tekrarlattı! Tam bir işkence!'::text),
(362601,40289,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az oktató az egész osztállyal százszor ... azt a rúgást! Tiszta kínszenvedés!'::text,'megismételtette'::text,'megismételtette'::text,'ismételgetve'::text,'Az oktató az egész osztállyal százszor megismételtette azt a rúgást! Tiszta kínszenvedés!'::text),
(335973,37331,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sie das Armband am Handgelenk ihrer Freundin ..., summte eine Erinnerung an das Meeting um 18 Uhr.'::text,'schloss'::text,'schloss'::text,'geschlossen hat'::text,'Während sie das Armband am Handgelenk ihrer Freundin schloss, summte eine Erinnerung an das Meeting um 18 Uhr.'::text),
(335977,37331,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона ... браслет на зап''ясті подруги, задзижчало нагадування про зустріч о 18:00.'::text,'застібала'::text,'застібнула'::text,'застібнула'::text,'Поки вона застібала браслет на зап''ясті подруги, задзижчало нагадування про зустріч о 18:00.'::text),
(335976,37331,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras ... la pulsera en la muñeca de su amiga, sonó un recordatorio de la reunión de las 18:00.'::text,'abrochaba'::text,'abrochó'::text,'ha abrochado'::text,'Mientras abrochaba la pulsera en la muñeca de su amiga, sonó un recordatorio de la reunión de las 18:00.'::text),
(335975,37331,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant qu''elle ... le bracelet au poignet de son amie, un rappel de réunion à 18 h a vibré.'::text,'attachait'::text,'attacha'::text,'a attaché'::text,'Pendant qu''elle attachait le bracelet au poignet de son amie, un rappel de réunion à 18 h a vibré.'::text),
(335978,37331,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, arkadaşının bileğine bilekliği ..., saat 18.00 toplantı hatırlatıcısı titredi.'::text,'takarken'::text,'taktığında'::text,'takmışken'::text,'O, arkadaşının bileğine bilekliği takarken, saat 18.00 toplantı hatırlatıcısı titredi.'::text),
(335979,37331,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben ő ... a karkötőt a barátnője csuklóján, rezgett egy emlékeztető a 18:00-s megbeszélésről.'::text,'csatolta'::text,'becsatolta'::text,'becsatolta'::text,'Miközben ő csatolta a karkötőt a barátnője csuklóján, rezgett egy emlékeztető a 18:00-s megbeszélésről.'::text),
(335982,37332,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit zwei Minuten an dem Armband, weil sie noch nicht fertig ist.'::text,'zupft'::text,'zupft'::text,'zupft'::text,'Sie zupft seit zwei Minuten an dem Armband, weil sie noch nicht fertig ist.'::text),
(335986,37332,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... браслет уже дві хвилини, бо ще не закінчила.'::text,'поправляє'::text,'поправляє'::text,'поправляє'::text,'Вона поправляє браслет уже дві хвилини, бо ще не закінчила.'::text),
(335985,37332,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... la pulsera desde hace dos minutos porque todavía no ha terminado.'::text,'ha estado ajustando'::text,'está ajustando'::text,'ajusta'::text,'Ella ha estado ajustando la pulsera desde hace dos minutos porque todavía no ha terminado.'::text),
(335984,37332,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le bracelet depuis deux minutes parce qu''elle n''a pas encore fini.'::text,'ajuste'::text,'ajuste'::text,'ajuste'::text,'Elle ajuste le bracelet depuis deux minutes parce qu''elle n''a pas encore fini.'::text),
(335987,37332,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki dakikadır bilekliği ..., çünkü henüz bitirmedi.'::text,'düzeltiyor'::text,'düzeltiyor'::text,'düzeltir'::text,'İki dakikadır bilekliği düzeltiyor, çünkü henüz bitirmedi.'::text),
(335988,37332,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két perce ... a karkötőt, mert még nincs kész.'::text,'igazgatja'::text,'igazgatja'::text,'igazgatja'::text,'Két perce igazgatja a karkötőt, mert még nincs kész.'::text),
(335991,37333,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie beobachtet, ... die Frau am Armband, als ihre Freundin sie plötzlich umarmte.'::text,'zupfte gerade'::text,'zupfte'::text,'zupfte'::text,'Wie beobachtet, zupfte gerade die Frau am Armband, als ihre Freundin sie plötzlich umarmte.'::text),
(335995,37333,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як було помічено, жінка ... браслет, коли подруга раптом її обійняла.'::text,'поправляла'::text,'поправила'::text,'поправила'::text,'Як було помічено, жінка поправляла браслет, коли подруга раптом її обійняла.'::text),
(335994,37333,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según lo observado, la mujer ... la pulsera cuando su amiga de repente la abrazó.'::text,'estaba ajustando'::text,'ajustó'::text,'ha ajustado'::text,'Según lo observado, la mujer estaba ajustando la pulsera cuando su amiga de repente la abrazó.'::text),
(335993,37333,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Comme observé, la femme ... le bracelet quand son amie l''a soudain serrée dans ses bras.'::text,'ajustait'::text,'ajusta'::text,'a ajusté'::text,'Comme observé, la femme ajustait le bracelet quand son amie l''a soudain serrée dans ses bras.'::text),
(335996,37333,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gözlemlendiği üzere, arkadaşı ona aniden sarıldığında kadın bilekliği ...'::text,'düzeltiyordu'::text,'düzeltti'::text,'düzeltmiştir'::text,'Gözlemlendiği üzere, arkadaşı ona aniden sarıldığında kadın bilekliği düzeltiyordu.'::text),
(335997,37333,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahogy megfigyelhető, a nő ... a karkötőt, amikor a barátnője hirtelen megölelte.'::text,'éppen igazgatta'::text,'megigazította'::text,'megigazította'::text,'Ahogy megfigyelhető, a nő éppen igazgatta a karkötőt, amikor a barátnője hirtelen megölelte.'::text),
(336000,37334,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Sie hat das Armband dreimal ..., und es ist immer noch locker!'::text,'nachgestellt'::text,'nachgestellt'::text,'nachgestellt'::text,'Albtraum! Sie hat das Armband dreimal nachgestellt, und es ist immer noch locker!'::text),
(336004,37334,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Вона ... браслет тричі, а він досі вільний!'::text,'поправила'::text,'поправляла'::text,'поправляє'::text,'Жах! Вона поправила браслет тричі, а він досі вільний!'::text),
(336003,37334,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Qué pesadilla! ¡... la pulsera tres veces y sigue floja!'::text,'Ha ajustado'::text,'Ha estado ajustando'::text,'Ajusta'::text,'¡Qué pesadilla! ¡Ha ajustado la pulsera tres veces y sigue floja!'::text),
(336002,37334,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Elle ... le bracelet trois fois et il est toujours lâche !'::text,'a ajusté'::text,'a ajusté'::text,'ajuste'::text,'Cauchemar ! Elle a ajusté le bracelet trois fois et il est toujours lâche !'::text),
(336005,37334,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Bilekliği üç kez ... ve hâlâ gevşek!'::text,'düzeltti'::text,'düzeltip durdu'::text,'düzeltiyor'::text,'Kâbus! Bilekliği üç kez düzeltti ve hâlâ gevşek!'::text),
(336006,37334,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Háromszor ... a karkötőt, és még mindig laza!'::text,'igazította meg'::text,'igazgatta'::text,'igazítja meg'::text,'Rémálom! Háromszor igazította meg a karkötőt, és még mindig laza!'::text),
(336009,37335,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... Handgelenk das Armband bekommt, umarmt ihre Freundin im Gras.'::text,'deren'::text,'die'::text,'das'::text,'Die Frau, deren Handgelenk das Armband bekommt, umarmt ihre Freundin im Gras.'::text),
(336013,37335,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... зап''ястя отримує браслет, обіймає подругу на траві.'::text,'чиє'::text,'яка'::text,'яке'::text,'Жінка, чиє зап''ястя отримує браслет, обіймає подругу на траві.'::text),
(336012,37335,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... muñeca recibe la pulsera abraza a su amiga en el césped.'::text,'cuya'::text,'que'::text,'la cual'::text,'La mujer cuya muñeca recibe la pulsera abraza a su amiga en el césped.'::text),
(336011,37335,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... le poignet reçoit le bracelet serre son amie dans ses bras sur l''herbe.'::text,'dont'::text,'qui'::text,'que'::text,'La femme dont le poignet reçoit le bracelet serre son amie dans ses bras sur l''herbe.'::text),
(336014,37335,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bileğine bileklik takılan kadın çimenlerde arkadaşına sarılıyor.'::text,''::text,NULL::text,NULL::text,'Bileğine bileklik takılan kadın çimenlerde arkadaşına sarılıyor.'::text),
(336015,37335,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a nő, ... csuklójára a karkötő kerül, megöleli a barátnőjét a füvön.'::text,'akinek a'::text,'aki'::text,'amely'::text,'Az a nő, akinek a csuklójára a karkötő kerül, megöleli a barátnőjét a füvön.'::text),
(336027,37337,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie Kinder waren, ... die zwei Freundinnen jeden Sommer Armbänder füreinander.'::text,'bastelten'::text,'bastelten'::text,'bastelten'::text,'Als sie Kinder waren, bastelten die zwei Freundinnen jeden Sommer Armbänder füreinander.'::text),
(336031,37337,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли вони були дітьми, дві подруги ... плести одна одній браслети щоліта.'::text,'мали звичку'::text,'мали звичку'::text,'звикли'::text,'Коли вони були дітьми, дві подруги мали звичку плести одна одній браслети щоліта.'::text),
(336030,37337,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando eran niñas, las dos amigas ... hacerse pulseras cada verano.'::text,'solían'::text,'solían'::text,'estaban acostumbradas a'::text,'Cuando eran niñas, las dos amigas solían hacerse pulseras cada verano.'::text),
(336029,37337,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elles étaient petites, les deux amies ... des bracelets l''une pour l''autre chaque été.'::text,'faisaient'::text,'faisaient'::text,'avaient l''habitude de faire'::text,'Quand elles étaient petites, les deux amies faisaient des bracelets l''une pour l''autre chaque été.'::text),
(336032,37337,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocukken iki arkadaş her yaz birbirlerine bileklik ...'::text,'yaparlardı'::text,'yaparlardı'::text,'yapmaya alışkındı'::text,'Çocukken iki arkadaş her yaz birbirlerine bileklik yaparlardı.'::text),
(336033,37337,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gyerekkorukban a két barátnő minden nyáron ... karkötőt készíteni egymásnak.'::text,'szokott'::text,'szokott'::text,'hozzá volt szokva'::text,'Gyerekkorukban a két barátnő minden nyáron szokott karkötőt készíteni egymásnak.'::text),
(336036,37338,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hat offensichtlich Spaß daran, eine ganze Minute mit dem winzigen Verschluss des Armbands ...'::text,'herumzufummeln'::text,'herumzufummeln'::text,'herumfummeln'::text,'Sie hat offensichtlich Spaß daran, eine ganze Minute mit dem winzigen Verschluss des Armbands herumzufummeln.'::text),
(336040,37338,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Їй явно подобається ... з крихітною застібкою браслета цілу хвилину.'::text,'вовтузитися'::text,'вовтузитися'::text,'вовтузитися'::text,'Їй явно подобається вовтузитися з крихітною застібкою браслета цілу хвилину.'::text),
(336039,37338,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Está claro que disfruta ... con el cierre diminuto de la pulsera durante un minuto entero.'::text,'trasteando'::text,'trastear'::text,'trastea'::text,'Está claro que disfruta trasteando con el cierre diminuto de la pulsera durante un minuto entero.'::text),
(336038,37338,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle adore visiblement ... avec le minuscule fermoir du bracelet pendant une minute entière.'::text,'galérer'::text,'galérer'::text,'galérer'::text,'Elle adore visiblement galérer avec le minuscule fermoir du bracelet pendant une minute entière.'::text),
(336041,37338,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki bilekliğin minicik klipsiyle tam bir dakika ... bayılıyor.'::text,'uğraşmaya'::text,'uğraşmaya'::text,'uğraşmaya'::text,'Belli ki bilekliğin minicik klipsiyle tam bir dakika uğraşmaya bayılıyor.'::text),
(336042,37338,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván élvezi, hogy egy teljes percig ... a karkötő apró kapcsával.'::text,'babrál'::text,'babrál'::text,'babrál'::text,'Nyilván élvezi, hogy egy teljes percig babrál a karkötő apró kapcsával.'::text),
(336045,37339,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar ein schneller Job: ... an ihrem Handgelenk zu schließen dauerte ganze zwei Minuten.'::text,'das Armband'::text,'ein Armband'::text,'Armband'::text,'Ganz klar ein schneller Job: das Armband an ihrem Handgelenk zu schließen dauerte ganze zwei Minuten.'::text),
(336049,37339,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно швидка справа: ... на її зап''ясті застібали цілі дві хвилини.'::text,'браслет'::text,'браслет'::text,'браслет'::text,'Явно швидка справа: браслет на її зап''ясті застібали цілі дві хвилини.'::text),
(336048,37339,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente un trabajo rápido: ... de su muñeca tardó dos minutos enteros en abrocharse.'::text,'la pulsera'::text,'una pulsera'::text,'pulsera'::text,'Claramente un trabajo rápido: la pulsera de su muñeca tardó dos minutos enteros en abrocharse.'::text),
(336047,37339,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un travail rapide : ... à son poignet a mis deux bonnes minutes à être attaché.'::text,'le bracelet'::text,'un bracelet'::text,'bracelet'::text,'Clairement un travail rapide : le bracelet à son poignet a mis deux bonnes minutes à être attaché.'::text),
(336050,37339,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki hızlı bir iş: bileğindeki ... takmak tam iki dakika sürdü.'::text,'bilekliği'::text,'bir bilekliği'::text,'bilekliği'::text,'Belli ki hızlı bir iş: bileğindeki bilekliği takmak tam iki dakika sürdü.'::text),
(336051,37339,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván gyors meló: ... a csuklóján két teljes percig tartott becsatolni.'::text,'a karkötőt'::text,'egy karkötőt'::text,'karkötőt'::text,'Nyilván gyors meló: a karkötőt a csuklóján két teljes percig tartott becsatolni.'::text),
(336063,37341,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die ... so zehn Minuten lang, bevor das Armband endlich zu war, echt jetzt.'::text,'lachten'::text,'lachen'::text,'lachen'::text,'Digga, die lachten so zehn Minuten lang, bevor das Armband endlich zu war, echt jetzt.'::text),
(336067,37341,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вони ... хвилин десять, поки браслет нарешті не застібнувся, реально.'::text,'сміялися'::text,'сміються'::text,'сміються'::text,'Бро, вони сміялися хвилин десять, поки браслет нарешті не застібнувся, реально.'::text),
(336066,37341,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ... como diez minutos riéndose antes de que la pulsera por fin se cerrara, en serio.'::text,'se habían pasado'::text,'se han pasado'::text,'se pasan'::text,'Bro, se habían pasado como diez minutos riéndose antes de que la pulsera por fin se cerrara, en serio.'::text),
(336065,37341,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elles ... genre dix minutes avant que le bracelet se ferme enfin, grave.'::text,'avaient ri'::text,'ont ri'::text,'rient'::text,'Frérot, elles avaient ri genre dix minutes avant que le bracelet se ferme enfin, grave.'::text),
(336068,37341,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bileklik sonunda kapanana kadar on dakika falan ..., cidden.'::text,'gülmüşlerdi'::text,'gülüyorlar'::text,'gülüyorlar'::text,'Kanka, bileklik sonunda kapanana kadar on dakika falan gülmüşlerdi, cidden.'::text),
(336069,37341,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, vagy tíz percig ..., mire végre bekattant a karkötő, komolyan.'::text,'nevettek'::text,'nevetnek'::text,'nevetnek'::text,'Tesó, vagy tíz percig nevettek, mire végre bekattant a karkötő, komolyan.'::text),
(391467,43497,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... er wieder ihre Einkäufe die Treppe hoch.'::text,'trägt'::text,'trägt'::text,'trägt'::text,'Morgen um diese Zeit trägt er wieder ihre Einkäufe die Treppe hoch.'::text),
(391471,43497,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о цій порі він знову ... їй покупки нагору сходами.'::text,'нестиме'::text,'понесе'::text,'несе'::text,'Завтра о цій порі він знову нестиме їй покупки нагору сходами.'::text),
(391470,43497,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora ... otra vez su compra escaleras arriba.'::text,'estará subiendo'::text,'subirá'::text,'sube'::text,'Mañana a esta hora estará subiendo otra vez su compra escaleras arriba.'::text),
(391469,43497,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, il ... encore ses courses dans l''escalier.'::text,'sera en train de monter'::text,'montera'::text,'monte'::text,'Demain à la même heure, il sera en train de monter encore ses courses dans l''escalier.'::text),
(391472,43497,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde yine onun alışverişini merdivenlerden yukarı ...'::text,'taşıyor olacak'::text,'taşıyacak'::text,'taşıyor'::text,'Yarın bu saatlerde yine onun alışverişini merdivenlerden yukarı taşıyor olacak.'::text),
(391473,43497,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor megint ... neki a bevásárlást a lépcsőn.'::text,'fel fogja vinni'::text,'felviszi'::text,'felviszi'::text,'Holnap ilyenkor megint fel fogja vinni neki a bevásárlást a lépcsőn.'::text),
(391476,43498,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kann die Taschen nicht heben, also sagt er, er ... sie die Treppe hoch.'::text,'trägt'::text,'trägt'::text,'trägt gerade'::text,'Sie kann die Taschen nicht heben, also sagt er, er trägt sie die Treppe hoch.'::text),
(391480,43498,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона не може підняти сумки, тож він каже, що ... їх нагору сходами.'::text,'занесе'::text,'заноситиме'::text,'заносить'::text,'Вона не може підняти сумки, тож він каже, що занесе їх нагору сходами.'::text),
(391479,43498,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella no puede levantar las bolsas, así que él dice que las ... escaleras arriba.'::text,'subirá'::text,'estará subiendo'::text,'está subiendo'::text,'Ella no puede levantar las bolsas, así que él dice que las subirá escaleras arriba.'::text),
(391478,43498,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''arrive pas à soulever les sacs, alors il dit qu''il les ... dans l''escalier.'::text,'montera'::text,'sera en train de monter'::text,'monte'::text,'Elle n''arrive pas à soulever les sacs, alors il dit qu''il les montera dans l''escalier.'::text),
(391481,43498,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın poşetleri kaldıramıyor, o yüzden adam onları merdivenlerden yukarı ... söylüyor.'::text,'taşıyacağını'::text,'taşıyor olacağını'::text,'taşıdığını'::text,'Kadın poşetleri kaldıramıyor, o yüzden adam onları merdivenlerden yukarı taşıyacağını söylüyor.'::text),
(391482,43498,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő nem bírja felemelni a szatyrokat, ezért a srác azt mondja, ... őket a lépcsőn.'::text,'felviszi'::text,'fel fogja vinni'::text,'éppen viszi'::text,'Ő nem bírja felemelni a szatyrokat, ezért a srác azt mondja, felviszi őket a lépcsőn.'::text),
(391485,43499,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du die Treppe hochgehst, ... du höher, weil Treppen nach oben gehen.'::text,'kommst'::text,'kommst'::text,'kamst'::text,'Wenn du die Treppe hochgehst, kommst du höher, weil Treppen nach oben gehen.'::text),
(391489,43499,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо йдеш сходами нагору, ... вище, бо сходи ведуть нагору.'::text,'потрапляєш'::text,'потрапиш'::text,'потрапив'::text,'Якщо йдеш сходами нагору, потрапляєш вище, бо сходи ведуть нагору.'::text),
(391488,43499,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si subes las escaleras, ... más alto, porque las escaleras van hacia arriba.'::text,'llegas'::text,'llegarás'::text,'llegaste'::text,'Si subes las escaleras, llegas más alto, porque las escaleras van hacia arriba.'::text),
(391487,43499,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu montes l''escalier, tu ... plus haut, parce que l''escalier monte.'::text,'arrives'::text,'arriveras'::text,'es arrivé'::text,'Si tu montes l''escalier, tu arrives plus haut, parce que l''escalier monte.'::text),
(391490,43499,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Merdivenlerden çıkarsan daha yukarı ..., çünkü merdivenler yukarı gider.'::text,'çıkarsın'::text,'çıkacaksın'::text,'çıktın'::text,'Merdivenlerden çıkarsan daha yukarı çıkarsın, çünkü merdivenler yukarı gider.'::text),
(391491,43499,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha felmész a lépcsőn, magasabbra ..., mert a lépcső felfelé vezet.'::text,'jutsz'::text,'fogsz jutni'::text,'jutottál'::text,'Ha felmész a lépcsőn, magasabbra jutsz, mert a lépcső felfelé vezet.'::text),
(391494,43500,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er beide Taschen trägt, ... die Frau die Treppe mit erheblich weniger Aufwand hinauf.'::text,'steigt'::text,'stiege'::text,'stieg'::text,'Wenn er beide Taschen trägt, steigt die Frau die Treppe mit erheblich weniger Aufwand hinauf.'::text),
(391498,43500,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він нестиме обидві сумки, жінка ... сходами зі значно меншими зусиллями.'::text,'підніметься'::text,'піднялася б'::text,'піднялася'::text,'Якщо він нестиме обидві сумки, жінка підніметься сходами зі значно меншими зусиллями.'::text),
(391497,43500,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si él lleva las dos bolsas, la mujer ... las escaleras con considerablemente menos esfuerzo.'::text,'subirá'::text,'subiría'::text,'subió'::text,'Si él lleva las dos bolsas, la mujer subirá las escaleras con considerablemente menos esfuerzo.'::text),
(391496,43500,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il porte les deux sacs, la femme ... l''escalier avec considérablement moins d''effort.'::text,'montera'::text,'monterait'::text,'a monté'::text,'S''il porte les deux sacs, la femme montera l''escalier avec considérablement moins d''effort.'::text),
(391499,43500,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam iki poşeti de taşırsa kadın merdivenleri çok daha az çabayla ...'::text,'çıkacak'::text,'çıkardı'::text,'çıktı'::text,'Adam iki poşeti de taşırsa kadın merdivenleri çok daha az çabayla çıkacak.'::text),
(391500,43500,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ő viszi mindkét szatyrot, a nő jelentősen kisebb erőfeszítéssel ... fel a lépcsőn.'::text,'megy'::text,'menne'::text,'ment'::text,'Ha ő viszi mindkét szatyrot, a nő jelentősen kisebb erőfeszítéssel megy fel a lépcsőn.'::text),
(391503,43501,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er die Taschen auf der Treppe fallen ließe, ... die Orangen überallhin! Totale Katastrophe!'::text,'rollten'::text,'rollen'::text,'rollten'::text,'Wenn er die Taschen auf der Treppe fallen ließe, rollten die Orangen überallhin! Totale Katastrophe!'::text),
(391507,43501,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він упустив сумки на сходах, апельсини ... всюди! Повна катастрофа!'::text,'розкотилися б'::text,'розкотяться'::text,'розкотилися'::text,'Якби він упустив сумки на сходах, апельсини розкотилися б всюди! Повна катастрофа!'::text),
(391506,43501,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si se le cayeran las bolsas en las escaleras, las naranjas ... por todas partes! ¡Desastre total!'::text,'rodarían'::text,'rodarán'::text,'rodaron'::text,'¡Si se le cayeran las bolsas en las escaleras, las naranjas rodarían por todas partes! ¡Desastre total!'::text),
(391505,43501,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il lâchait les sacs dans l''escalier, les oranges ... partout ! Catastrophe totale !'::text,'rouleraient'::text,'rouleront'::text,'ont roulé'::text,'S''il lâchait les sacs dans l''escalier, les oranges rouleraient partout ! Catastrophe totale !'::text),
(391508,43501,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Poşetleri merdivende düşürse portakallar her yere ...! Tam bir felaket!'::text,'yuvarlanırdı'::text,'yuvarlanacak'::text,'yuvarlandı'::text,'Poşetleri merdivende düşürse portakallar her yere yuvarlanırdı! Tam bir felaket!'::text),
(391509,43501,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elejtené a szatyrokat a lépcsőn, a narancsok mindenfelé ...! Totális katasztrófa!'::text,'gurulnának'::text,'gurulnak'::text,'gurultak'::text,'Ha elejtené a szatyrokat a lépcsőn, a narancsok mindenfelé gurulnának! Totális katasztrófa!'::text),
(391512,43502,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Taschen ... von einem Fremden die Treppe hochgetragen! Sie wird sich für immer daran erinnern!'::text,'wurden'::text,'werden'::text,'trugen'::text,'Die Taschen wurden von einem Fremden die Treppe hochgetragen! Sie wird sich für immer daran erinnern!'::text),
(391516,43502,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сумки ... нагору сходами незнайомцем! Вона пам''ятатиме це назавжди!'::text,'були занесені'::text,'заносяться'::text,'занесли'::text,'Сумки були занесені нагору сходами незнайомцем! Вона пам''ятатиме це назавжди!'::text),
(391515,43502,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Las bolsas ... escaleras arriba por un desconocido! ¡Lo recordará para siempre!'::text,'fueron subidas'::text,'son subidas'::text,'subieron'::text,'¡Las bolsas fueron subidas escaleras arriba por un desconocido! ¡Lo recordará para siempre!'::text),
(391514,43502,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les sacs ... dans l''escalier par un inconnu ! Elle s''en souviendra pour toujours !'::text,'ont été montés'::text,'sont montés'::text,'ont monté'::text,'Les sacs ont été montés dans l''escalier par un inconnu ! Elle s''en souviendra pour toujours !'::text),
(391517,43502,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Poşetler bir yabancı tarafından merdivenlerden yukarı ...! Bunu sonsuza dek hatırlayacak!'::text,'taşındı'::text,'taşınıyor'::text,'taşıdı'::text,'Poşetler bir yabancı tarafından merdivenlerden yukarı taşındı! Bunu sonsuza dek hatırlayacak!'::text),
(391518,43502,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szatyrokat egy idegen ... fel a lépcsőn! Örökre emlékezni fog rá!'::text,'vitte'::text,'viszi'::text,'vitte'::text,'A szatyrokat egy idegen vitte fel a lépcsőn! Örökre emlékezni fog rá!'::text),
(391521,43503,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... mit zwei schweren Taschen die Treppe hoch! Absolut heldenhaft!'::text,'stieg'::text,'wurde gestiegen'::text,'steigend'::text,'Er stieg mit zwei schweren Taschen die Treppe hoch! Absolut heldenhaft!'::text),
(391525,43503,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... сходами нагору з двома важкими сумками! Абсолютно героїчно!'::text,'піднявся'::text,'був піднятий'::text,'піднімаючись'::text,'Він піднявся сходами нагору з двома важкими сумками! Абсолютно героїчно!'::text),
(391524,43503,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Él ... las escaleras con dos bolsas pesadas! ¡Totalmente heroico!'::text,'subió'::text,'fue subido'::text,'subiendo'::text,'¡Él subió las escaleras con dos bolsas pesadas! ¡Totalmente heroico!'::text),
(391523,43503,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... l''escalier avec deux sacs lourds ! Absolument héroïque !'::text,'a monté'::text,'a été monté'::text,'montant'::text,'Il a monté l''escalier avec deux sacs lourds ! Absolument héroïque !'::text),
(391526,43503,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki ağır poşetle merdivenlerden ...! Tamamen kahramanca!'::text,'çıktı'::text,'çıkıldı'::text,'çıkarak'::text,'İki ağır poşetle merdivenlerden çıktı! Tamamen kahramanca!'::text),
(391527,43503,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két nehéz szatyorral ... fel a lépcsőn! Abszolút hősies!'::text,'ment'::text,'lett menve'::text,'menve'::text,'Két nehéz szatyorral ment fel a lépcsőn! Abszolút hősies!'::text),
(391530,43504,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Warte, laut ihr ... ihr Nachbar sein, weil er wusste, welche Treppe er nehmen musste.'::text,'muss er'::text,'kann er nicht'::text,'sollte er'::text,'Warte, laut ihr muss er ihr Nachbar sein, weil er wusste, welche Treppe er nehmen musste.'::text),
(391534,43504,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, за її словами, він ... бути її сусідом, бо знав, якими сходами йти.'::text,'мусить'::text,'не може'::text,'мав би'::text,'Стривай, за її словами, він мусить бути її сусідом, бо знав, якими сходами йти.'::text),
(391533,43504,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, según ella, ... ser su vecino, porque sabía qué escaleras tomar.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Espera, según ella, debe de ser su vecino, porque sabía qué escaleras tomar.'::text),
(391532,43504,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, d''après elle, il ... être son voisin, parce qu''il savait quel escalier prendre.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Attends, d''après elle, il doit être son voisin, parce qu''il savait quel escalier prendre.'::text),
(391535,43504,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, ona göre adam onun komşusu ..., çünkü hangi merdivenden çıkacağını biliyordu.'::text,'olmalı'::text,'olamaz'::text,'olmalı'::text,'Dur, ona göre adam onun komşusu olmalı, çünkü hangi merdivenden çıkacağını biliyordu.'::text),
(391536,43504,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, szerinte a srác ... a szomszédja, mert tudta, melyik lépcsőn kell menni.'::text,'biztos'::text,'nem lehet'::text,'kellene legyen'::text,'Várj, szerinte a srác biztos a szomszédja, mert tudta, melyik lépcsőn kell menni.'::text),
(391548,43506,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Unter uns, sie hat mir gesagt, die Treppe ... jetzt zu steil für sie.'::text,'sei'::text,'ist'::text,'wird'::text,'Unter uns, sie hat mir gesagt, die Treppe sei jetzt zu steil für sie.'::text),
(391552,43506,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Між нами, вона сказала мені, що сходи ... для неї тепер надто круті.'::text,'були'::text,'є'::text,'будуть'::text,'Між нами, вона сказала мені, що сходи були для неї тепер надто круті.'::text),
(391551,43506,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nosotros, me dijo que las escaleras ... demasiado empinadas para ella ahora.'::text,'eran'::text,'son'::text,'serán'::text,'Entre nosotros, me dijo que las escaleras eran demasiado empinadas para ella ahora.'::text),
(391550,43506,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Entre nous, elle m''a dit que l''escalier ... trop raide pour elle maintenant.'::text,'était'::text,'est'::text,'sera'::text,'Entre nous, elle m''a dit que l''escalier était trop raide pour elle maintenant.'::text),
(391553,43506,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aramızda kalsın, bana merdivenlerin artık onun için çok dik ... söyledi.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Aramızda kalsın, bana merdivenlerin artık onun için çok dik olduğunu söyledi.'::text),
(391554,43506,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köztünk szólva, azt mondta, hogy a lépcső most már ... túl meredek neki.'::text,''::text,NULL::text,'lesz'::text,'Köztünk szólva, azt mondta, hogy a lépcső most már túl meredek neki.'::text),
(391557,43507,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Treppe mit Taschen hochsteigen, aber jetzt braucht sie Hilfe.'::text,'konnte früher'::text,'konnte'::text,'konnte'::text,'Sie konnte früher die Treppe mit Taschen hochsteigen, aber jetzt braucht sie Hilfe.'::text),
(391561,43507,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... підніматися сходами з сумками, але тепер їй потрібна допомога.'::text,'колись могла'::text,'могла'::text,'могла'::text,'Вона колись могла підніматися сходами з сумками, але тепер їй потрібна допомога.'::text),
(391560,43507,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... subir las escaleras con bolsas, pero ahora necesita ayuda.'::text,'solía poder'::text,'podía'::text,'estaba acostumbrada a poder'::text,'Ella solía poder subir las escaleras con bolsas, pero ahora necesita ayuda.'::text),
(391559,43507,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... monter l''escalier avec des sacs, mais maintenant elle a besoin d''aide.'::text,'pouvait autrefois'::text,'pouvait'::text,'avait l''habitude de pouvoir'::text,'Elle pouvait autrefois monter l''escalier avec des sacs, mais maintenant elle a besoin d''aide.'::text),
(391562,43507,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın merdivenleri poşetlerle ..., ama şimdi yardıma ihtiyacı var.'::text,'çıkabilirdi'::text,'çıkabilirdi'::text,'çıkabilmeye alışkındı'::text,'Kadın merdivenleri poşetlerle çıkabilirdi, ama şimdi yardıma ihtiyacı var.'::text),
(391563,43507,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... felmenni a lépcsőn szatyrokkal, de most segítségre van szüksége.'::text,'régen tudott'::text,'tudott'::text,'tudott'::text,'Ő régen tudott felmenni a lépcsőn szatyrokkal, de most segítségre van szüksége.'::text),
(368355,40929,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das Mitgliedsformular, als die Studierenden ihre Kameras hoben und jubelten.'::text,'unterschrieb gerade'::text,'unterschrieb'::text,'hat unterschrieben'::text,'Sie unterschrieb gerade das Mitgliedsformular, als die Studierenden ihre Kameras hoben und jubelten.'::text),
(368359,40929,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... заявку на членство, коли студенти підняли камери й радісно закричали.'::text,'підписувала'::text,'підписала'::text,'підписала'::text,'Вона підписувала заявку на членство, коли студенти підняли камери й радісно закричали.'::text),
(368358,40929,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el formulario de membresía cuando los estudiantes levantaron sus cámaras y aplaudieron.'::text,'estaba firmando'::text,'firmó'::text,'ha firmado'::text,'Ella estaba firmando el formulario de membresía cuando los estudiantes levantaron sus cámaras y aplaudieron.'::text),
(368357,40929,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le formulaire d''adhésion quand les étudiants ont levé leurs appareils photo en criant de joie.'::text,'signait'::text,'signa'::text,'a signé'::text,'Elle signait le formulaire d''adhésion quand les étudiants ont levé leurs appareils photo en criant de joie.'::text),
(368360,40929,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğrenciler fotoğraf makinelerini kaldırıp tezahürat yaptığında o üyelik formunu ...'::text,'imzalıyordu'::text,'imzaladı'::text,'imzalamıştır'::text,'Öğrenciler fotoğraf makinelerini kaldırıp tezahürat yaptığında o üyelik formunu imzalıyordu.'::text),
(368361,40929,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a tagsági űrlapot, amikor a diákok felemelték a fényképezőgépüket és ujjongtak.'::text,'éppen írta alá'::text,'aláírta'::text,'aláírta'::text,'Ő éppen írta alá a tagsági űrlapot, amikor a diákok felemelték a fényképezőgépüket és ujjongtak.'::text),
(368373,40931,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Kamera ans Auge, als sie beschloss: Mitgliedschaft für immer!'::text,'hob gerade'::text,'hob'::text,'hat gehoben'::text,'Sie hob gerade die Kamera ans Auge, als sie beschloss: Mitgliedschaft für immer!'::text),
(368377,40931,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... камеру до ока, коли вирішила: членство назавжди!'::text,'підносила'::text,'піднесла'::text,'піднесла'::text,'Вона підносила камеру до ока, коли вирішила: членство назавжди!'::text),
(368376,40931,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ella ... la cámara al ojo cuando decidió: membresía para siempre!'::text,'estaba levantando'::text,'levantó'::text,'ha levantado'::text,'¡Ella estaba levantando la cámara al ojo cuando decidió: membresía para siempre!'::text),
(368375,40931,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... l''appareil à son œil quand elle a décidé : adhésion pour toujours !'::text,'portait'::text,'porta'::text,'a porté'::text,'Elle portait l''appareil à son œil quand elle a décidé : adhésion pour toujours !'::text),
(368378,40931,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O, fotoğraf makinesini gözüne ... karar verdi: sonsuza dek üyelik!'::text,'kaldırırken'::text,'kaldırdığında'::text,'kaldırmışken'::text,'O, fotoğraf makinesini gözüne kaldırırken karar verdi: sonsuza dek üyelik!'::text),
(368379,40931,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ő ... a szeméhez a gépet, amikor eldöntötte: tagság örökre!'::text,'emelte éppen'::text,'emelte'::text,'emelte'::text,'Ő emelte éppen a szeméhez a gépet, amikor eldöntötte: tagság örökre!'::text),
(368382,40932,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich wünschte, ich ... schon vor Jahren die Mitgliedschaft in diesem Fotoclub bekommen! Mein Leben ist ruiniert!'::text,'hätte'::text,'habe'::text,'würde'::text,'Ich wünschte, ich hätte schon vor Jahren die Mitgliedschaft in diesem Fotoclub bekommen! Mein Leben ist ruiniert!'::text),
(368386,40932,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ж я ... членство в тому фотоклубі ще багато років тому! Моє життя зруйноване!'::text,'отримала'::text,'отримала'::text,'отримала'::text,'Якби ж я отримала членство в тому фотоклубі ще багато років тому! Моє життя зруйноване!'::text),
(368385,40932,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ojalá ... la membresía de ese club de fotografía hace años! ¡Mi vida está arruinada!'::text,'hubiera conseguido'::text,'consiguiera'::text,'consiguiera'::text,'¡Ojalá hubiera conseguido la membresía de ese club de fotografía hace años! ¡Mi vida está arruinada!'::text),
(368384,40932,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si seulement ... ma carte de membre de ce club photo il y a des années ! Ma vie est fichue !'::text,'j''avais pris'::text,'je prenais'::text,'je prendrais'::text,'Si seulement j''avais pris ma carte de membre de ce club photo il y a des années ! Ma vie est fichue !'::text),
(368387,40932,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keşke o fotoğraf kulübüne yıllar önce üye ...! Hayatım mahvoldu!'::text,'olsaydım'::text,'olsam'::text,'olsam'::text,'Keşke o fotoğraf kulübüne yıllar önce üye olsaydım! Hayatım mahvoldu!'::text),
(368388,40932,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bárcsak már évekkel ezelőtt ... tagságot abban a fotóklubban! Tönkrement az életem!'::text,'szereztem volna'::text,'szereznék'::text,'szereznék'::text,'Bárcsak már évekkel ezelőtt szereztem volna tagságot abban a fotóklubban! Tönkrement az életem!'::text),
(368391,40933,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fotoclub, ... Mitgliedschaft komplett kostenlos war, ist der absolut beste!'::text,'dessen'::text,'der'::text,'den'::text,'Der Fotoclub, dessen Mitgliedschaft komplett kostenlos war, ist der absolut beste!'::text),
(368395,40933,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фотоклуб, ... членство було повністю безкоштовним, — абсолютно найкращий!'::text,'чиє'::text,'який'::text,'що'::text,'Фотоклуб, чиє членство було повністю безкоштовним, — абсолютно найкращий!'::text),
(368394,40933,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El club de fotografía, ... membresía era totalmente gratis, es lo mejor de lo mejor!'::text,'cuya'::text,'que'::text,'el cual'::text,'¡El club de fotografía, cuya membresía era totalmente gratis, es lo mejor de lo mejor!'::text),
(368393,40933,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le club photo, ... l''adhésion était entièrement gratuite, est carrément le meilleur !'::text,'dont'::text,'qui'::text,'que'::text,'Le club photo, dont l''adhésion était entièrement gratuite, est carrément le meilleur !'::text),
(368396,40933,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... üyeliği tamamen ücretsiz olan fotoğraf kulübü kesinlikle en iyisi!'::text,''::text,NULL::text,NULL::text,'Üyeliği tamamen ücretsiz olan fotoğraf kulübü kesinlikle en iyisi!'::text),
(368397,40933,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fotóklub, ... tagsága teljesen ingyenes volt, abszolút a legjobb!'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A fotóklub, amelynek a tagsága teljesen ingyenes volt, abszolút a legjobb!'::text),
(368400,40934,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Also hör zu, sie hat ihre Mitgliedschaft anscheinend direkt vor Ort ... bezahlt.'::text,'bar'::text,'mit dem Bargeld'::text,'bar'::text,'Also hör zu, sie hat ihre Mitgliedschaft anscheinend direkt vor Ort bar bezahlt.'::text),
(368404,40934,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, вона заплатила за членство ... одразу на місці.'::text,'готівкою'::text,'готівкою'::text,'готівкою'::text,'Слухай, кажуть, вона заплатила за членство готівкою одразу на місці.'::text),
(368403,40934,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, parece que pagó su membresía en ... en el acto.'::text,'efectivo'::text,'el efectivo'::text,'efectivo'::text,'Oye, parece que pagó su membresía en efectivo en el acto.'::text),
(368402,40934,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon écoute, apparemment elle a payé son adhésion en ... sur place.'::text,'espèces'::text,'les espèces'::text,'espèces'::text,'Bon écoute, apparemment elle a payé son adhésion en espèces sur place.'::text),
(368405,40934,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, galiba üyeliğini hemen orada ... ödemiş.'::text,'nakit'::text,'nakit'::text,'nakit'::text,'Dinle, galiba üyeliğini hemen orada nakit ödemiş.'::text),
(368406,40934,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szóval figyelj, állítólag a tagságát ... fizette ki a helyszínen.'::text,'készpénzben'::text,'a készpénzben'::text,'készpénzben'::text,'Szóval figyelj, állítólag a tagságát készpénzben fizette ki a helyszínen.'::text),
(368409,40935,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sie nie eine Filmkamera benutzt hatte, unterschrieb sie das Mitgliedsformular.'::text,'Obwohl'::text,'Trotz'::text,'Wegen'::text,'Obwohl sie nie eine Filmkamera benutzt hatte, unterschrieb sie das Mitgliedsformular.'::text),
(368413,40935,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вона ніколи не користувалася плівковим фотоапаратом, підписала заявку на членство.'::text,'Хоча'::text,'Попри'::text,'Через'::text,'Хоча вона ніколи не користувалася плівковим фотоапаратом, підписала заявку на членство.'::text),
(368412,40935,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... nunca había usado una cámara de carrete, firmó el formulario de membresía.'::text,'Aunque'::text,'A pesar de'::text,'Debido a'::text,'Aunque nunca había usado una cámara de carrete, firmó el formulario de membresía.'::text),
(368411,40935,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... elle n''avait jamais utilisé d''appareil argentique, elle a signé le formulaire d''adhésion.'::text,'Même si'::text,'Malgré'::text,'À cause de'::text,'Même si elle n''avait jamais utilisé d''appareil argentique, elle a signé le formulaire d''adhésion.'::text),
(368414,40935,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha önce hiç analog fotoğraf makinesi kullanmamış ..., üyelik formunu imzaladı.'::text,'olsa da'::text,'olmasına rağmen'::text,'olduğu için'::text,'Daha önce hiç analog fotoğraf makinesi kullanmamış olsa da, üyelik formunu imzaladı.'::text),
(368415,40935,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... soha nem használt filmes fényképezőgépet, aláírta a tagsági űrlapot.'::text,'Bár'::text,'Annak ellenére'::text,'Amiatt'::text,'Bár soha nem használt filmes fényképezőgépet, aláírta a tagsági űrlapot.'::text),
(368418,40936,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat mir erzählt, sie wusste, dass sie die Mitgliedschaft ..., sobald sie die Kamera in der Hand hielt.'::text,'beantragen würde'::text,'beantragen wird'::text,'beantragt'::text,'Rate mal, sie hat mir erzählt, sie wusste, dass sie die Mitgliedschaft beantragen würde, sobald sie die Kamera in der Hand hielt.'::text),
(368422,40936,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, вона сказала, що знала, що ... членство, щойно взяла в руки той фотоапарат.'::text,'подасть заявку на'::text,'подасть заявку на'::text,'подає заявку на'::text,'Вгадай що, вона сказала, що знала, що подасть заявку на членство, щойно взяла в руки той фотоапарат.'::text),
(368421,40936,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué, me dijo que supo que ... la membresía en cuanto tuvo esa cámara en las manos.'::text,'solicitaría'::text,'solicitará'::text,'solicita'::text,'Adivina qué, me dijo que supo que solicitaría la membresía en cuanto tuvo esa cámara en las manos.'::text),
(368420,40936,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle m''a dit qu''elle savait qu''elle ... l''adhésion dès qu''elle a tenu cet appareil.'::text,'demanderait'::text,'demandera'::text,'demande'::text,'Devine quoi, elle m''a dit qu''elle savait qu''elle demanderait l''adhésion dès qu''elle a tenu cet appareil.'::text),
(368423,40936,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, o fotoğraf makinesini tuttuğu an üyeliğe ... bildiğini söyledi.'::text,'başvuracağını'::text,'başvuracağını'::text,'başvurduğunu'::text,'Bil bakalım, o fotoğraf makinesini tuttuğu an üyeliğe başvuracağını bildiğini söyledi.'::text),
(368424,40936,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, tudta, hogy ... a tagságért, amint kézbe vette azt a gépet.'::text,'jelentkezni fog'::text,'jelentkezni fog'::text,'jelentkezik'::text,'Képzeld, azt mondta, tudta, hogy jelentkezni fog a tagságért, amint kézbe vette azt a gépet.'::text),
(368427,40937,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... diese Filmkamera wie ein Profi, und deine Mitgliedschaft ist brandneu.'::text,'hältst'::text,'hältst'::text,'hieltest'::text,'Ehrlich, du hältst diese Filmkamera wie ein Profi, und deine Mitgliedschaft ist brandneu.'::text),
(368431,40937,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... цей плівковий фотоапарат як профі, а твоє членство зовсім нове.'::text,'тримаєш'::text,'тримаєш'::text,'тримала'::text,'Чесно, ти тримаєш цей плівковий фотоапарат як профі, а твоє членство зовсім нове.'::text),
(368430,40937,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, ... esa cámara de carrete como una pro, y tu membresía es nuevecita.'::text,'estás sujetando'::text,'sujetas'::text,'has sujetado'::text,'Sinceramente, estás sujetando esa cámara de carrete como una pro, y tu membresía es nuevecita.'::text),
(368429,40937,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... cet appareil argentique comme une pro, et ton adhésion est toute neuve.'::text,'tiens'::text,'tiens'::text,'as tenu'::text,'Franchement, tu tiens cet appareil argentique comme une pro, et ton adhésion est toute neuve.'::text),
(368432,40937,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, o analog makineyi profesyonel gibi ... ve üyeliğin yepyeni.'::text,'tutuyorsun'::text,'tutarsın'::text,'tuttun'::text,'Açıkçası, o analog makineyi profesyonel gibi tutuyorsun ve üyeliğin yepyeni.'::text),
(368433,40937,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, úgy ... azt a filmes gépet, mint egy profi, és a tagságod vadonatúj.'::text,'tartod'::text,'tartod'::text,'tartottad'::text,'Őszintén, úgy tartod azt a filmes gépet, mint egy profi, és a tagságod vadonatúj.'::text),
(368436,40938,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor sie das Mitgliedsformular unterschrieb, ... sie die alte Filmkamera ausprobiert.'::text,'hatte'::text,'hat'::text,'hatte gerade'::text,'Bevor sie das Mitgliedsformular unterschrieb, hatte sie die alte Filmkamera ausprobiert.'::text),
(368440,40938,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж підписати заявку на членство, вона ... старий плівковий фотоапарат.'::text,'випробувала'::text,'випробувала'::text,'пробувала'::text,'Перш ніж підписати заявку на членство, вона випробувала старий плівковий фотоапарат.'::text),
(368439,40938,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de firmar el formulario de membresía, ... la vieja cámara de carrete.'::text,'había probado'::text,'ha probado'::text,'estaba probando'::text,'Antes de firmar el formulario de membresía, había probado la vieja cámara de carrete.'::text),
(368438,40938,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant de signer le formulaire d''adhésion, elle ... le vieil appareil argentique.'::text,'avait essayé'::text,'a essayé'::text,'essayait'::text,'Avant de signer le formulaire d''adhésion, elle avait essayé le vieil appareil argentique.'::text),
(368441,40938,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üyelik formunu imzalamadan önce eski analog makineyi ...'::text,'denemişti'::text,'denedi'::text,'deniyordu'::text,'Üyelik formunu imzalamadan önce eski analog makineyi denemişti.'::text),
(368442,40938,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt aláírta a tagsági űrlapot, ... a régi filmes gépet.'::text,'kipróbálta'::text,'kipróbálta'::text,'próbálgatta'::text,'Mielőtt aláírta a tagsági űrlapot, kipróbálta a régi filmes gépet.'::text),
(341238,37916,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gemeinschaft ... vor dem großen Jubel nur ein paar Setzlinge gepflanzt. Eine riesige Ernte, natürlich.'::text,'hatte'::text,'hat'::text,'pflanzt'::text,'Die Gemeinschaft hatte vor dem großen Jubel nur ein paar Setzlinge gepflanzt. Eine riesige Ernte, natürlich.'::text),
(341242,37916,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Громада ... лише кілька саджанців до великих оплесків. Величезний урожай, очевидно.'::text,'посадила'::text,'посадила'::text,'садить'::text,'Громада посадила лише кілька саджанців до великих оплесків. Величезний урожай, очевидно.'::text),
(341241,37916,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La comunidad ... solo unas pocas plántulas antes de la gran ovación. Una cosecha enorme, obviamente.'::text,'había plantado'::text,'ha plantado'::text,'planta'::text,'La comunidad había plantado solo unas pocas plántulas antes de la gran ovación. Una cosecha enorme, obviamente.'::text),
(341240,37916,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La communauté ... seulement quelques plants avant la grande acclamation. Une récolte énorme, évidemment.'::text,'avait planté'::text,'a planté'::text,'plante'::text,'La communauté avait planté seulement quelques plants avant la grande acclamation. Une récolte énorme, évidemment.'::text),
(341243,37916,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topluluk büyük tezahürattan önce sadece birkaç fide ... Devasa bir hasat, belli ki.'::text,'dikmişti'::text,'dikti'::text,'dikiyor'::text,'Topluluk büyük tezahürattan önce sadece birkaç fide dikmişti Devasa bir hasat, belli ki.'::text),
(341244,37916,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A közösség a nagy ujjongás előtt csak néhány palántát ... el. Óriási termés, nyilván.'::text,'ültetett'::text,'ültetett'::text,'ültet'::text,'A közösség a nagy ujjongás előtt csak néhány palántát ültetett el. Óriási termés, nyilván.'::text),
(341247,37917,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... die Gemeinschaft wieder dieselben sechs Setzlinge. Spannend.'::text,'gießt'::text,'gießt'::text,'gießt'::text,'Morgen um diese Zeit gießt die Gemeinschaft wieder dieselben sechs Setzlinge. Spannend.'::text),
(341251,37917,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о цій порі громада знову ... ті самі шість саджанців. Захопливо.'::text,'поливатиме'::text,'поллє'::text,'поливає'::text,'Завтра о цій порі громада знову поливатиме ті самі шість саджанців. Захопливо.'::text),
(341250,37917,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, la comunidad ... otra vez las mismas seis plántulas. Emocionante.'::text,'estará regando'::text,'regará'::text,'riega'::text,'Mañana a esta hora, la comunidad estará regando otra vez las mismas seis plántulas. Emocionante.'::text),
(341249,37917,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, la communauté ... encore les six mêmes plants. Palpitant.'::text,'sera en train d''arroser'::text,'arrosera'::text,'arrose'::text,'Demain à la même heure, la communauté sera en train d''arroser encore les six mêmes plants. Palpitant.'::text),
(341252,37917,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatlerde topluluk yine aynı altı fideyi ... Heyecan verici.'::text,'suluyor olacak'::text,'sulayacak'::text,'sular'::text,'Yarın bu saatlerde topluluk yine aynı altı fideyi suluyor olacak Heyecan verici.'::text),
(341253,37917,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor a közösség megint ugyanazt a hat palántát ... Izgalmas.'::text,'fogja locsolni'::text,'locsolja meg'::text,'locsolja'::text,'Holnap ilyenkor a közösség megint ugyanazt a hat palántát fogja locsolni Izgalmas.'::text),
(341256,37918,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die Gemeinschaft schwört, dass sie jeden Setzling am Leben ..., ohne Scheiß.'::text,'halten wird'::text,'halten wird'::text,'gerade hält'::text,'Digga, die Gemeinschaft schwört, dass sie jeden Setzling am Leben halten wird, ohne Scheiß.'::text),
(341260,37918,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, громада клянеться, що ... кожен саджанець живим, без жартів.'::text,'збереже'::text,'зберігатиме'::text,'зберігає'::text,'Бро, громада клянеться, що збереже кожен саджанець живим, без жартів.'::text),
(341259,37918,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la comunidad jura que ... vivas todas las plántulas, sin mentir.'::text,'mantendrá'::text,'estará manteniendo'::text,'está manteniendo'::text,'Bro, la comunidad jura que mantendrá vivas todas las plántulas, sin mentir.'::text),
(341258,37918,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, la communauté jure qu''elle ... chaque plant en vie, sans mentir.'::text,'gardera'::text,'sera en train de garder'::text,'garde'::text,'Frérot, la communauté jure qu''elle gardera chaque plant en vie, sans mentir.'::text),
(341261,37918,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, topluluk her fideyi hayatta ... yemin ediyor, yalan yok.'::text,'tutacağına'::text,'tutuyor olacağına'::text,'tuttuğuna'::text,'Kanka, topluluk her fideyi hayatta tutacağına yemin ediyor, yalan yok.'::text),
(341262,37918,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a közösség esküszik, hogy minden palántát életben ..., komolyan.'::text,'fog tartani'::text,'fog tartani'::text,'tart'::text,'Tesó, a közösség esküszik, hogy minden palántát életben fog tartani, komolyan.'::text),
(341265,37919,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, wenn eine Gemeinschaft ..., ihren Garten zu gießen, vertrocknen die Setzlinge, echt.'::text,'vergisst'::text,'vergaß'::text,'vergessen wird'::text,'Digga, wenn eine Gemeinschaft vergisst, ihren Garten zu gießen, vertrocknen die Setzlinge, echt.'::text),
(341269,37919,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якщо громада ... полити свій сад, саджанці висихають, реально.'::text,'забуває'::text,'забула'::text,'забуде'::text,'Бро, якщо громада забуває полити свій сад, саджанці висихають, реально.'::text),
(341268,37919,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si una comunidad ... regar su huerto, las plántulas se secan, en serio.'::text,'olvida'::text,'olvidó'::text,'olvidará'::text,'Bro, si una comunidad olvida regar su huerto, las plántulas se secan, en serio.'::text),
(341267,37919,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si une communauté ... d''arroser son jardin, les plants sèchent, grave.'::text,'oublie'::text,'a oublié'::text,'oubliera'::text,'Frérot, si une communauté oublie d''arroser son jardin, les plants sèchent, grave.'::text),
(341270,37919,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bir topluluk bahçesini sulamayı ..., fideler kurur, cidden.'::text,'unutursa'::text,'unuttuysa'::text,'unutacaksa'::text,'Kanka, bir topluluk bahçesini sulamayı unutursa, fideler kurur, cidden.'::text),
(341271,37919,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha egy közösség ... meglocsolni a kertjét, a palánták kiszáradnak, komolyan.'::text,'elfelejti'::text,'elfelejtette'::text,'el fogja felejteni'::text,'Tesó, ha egy közösség elfelejti meglocsolni a kertjét, a palánták kiszáradnak, komolyan.'::text),
(341274,37920,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Gemeinschaft 20 weitere Setzlinge pflanzt, ... der Garten sein Ernteziel.'::text,'erreicht'::text,'erreichte'::text,'erreichte'::text,'Wenn die Gemeinschaft 20 weitere Setzlinge pflanzt, erreicht der Garten sein Ernteziel.'::text),
(341278,37920,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо громада посадить ще 20 саджанців, сад ... своєї цілі з урожаю.'::text,'досягне'::text,'досяг би'::text,'досяг'::text,'Якщо громада посадить ще 20 саджанців, сад досягне своєї цілі з урожаю.'::text),
(341277,37920,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la comunidad planta 20 plántulas más, el huerto ... su objetivo de cosecha.'::text,'alcanzará'::text,'alcanzaría'::text,'alcanzó'::text,'Si la comunidad planta 20 plántulas más, el huerto alcanzará su objetivo de cosecha.'::text),
(341276,37920,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la communauté plante 20 plants de plus, le jardin ... son objectif de récolte.'::text,'atteindra'::text,'atteindrait'::text,'a atteint'::text,'Si la communauté plante 20 plants de plus, le jardin atteindra son objectif de récolte.'::text),
(341279,37920,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topluluk 20 fide daha dikerse bahçe hasat hedefine ...'::text,'ulaşacak'::text,'ulaşırdı'::text,'ulaştı'::text,'Topluluk 20 fide daha dikerse bahçe hasat hedefine ulaşacak.'::text),
(341280,37920,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a közösség még 20 palántát ültet, a kert ... a terméscélját.'::text,'eléri'::text,'elérné'::text,'elérte'::text,'Ha a közösség még 20 palántát ültet, a kert eléri a terméscélját.'::text),
(341283,37921,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn die Gemeinschaft keine Setzlinge hätte, ... sie nichts zu gießen. Deshalb pflanzt sie welche.'::text,'hätte'::text,'hätte'::text,'hat'::text,'Wenn die Gemeinschaft keine Setzlinge hätte, hätte sie nichts zu gießen. Deshalb pflanzt sie welche.'::text),
(341287,37921,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби громада не мала саджанців, їй ... нічого поливати. Тому вона їх і садить.'::text,'не було б'::text,'не буде'::text,'немає'::text,'Якби громада не мала саджанців, їй не було б нічого поливати. Тому вона їх і садить.'::text),
(341286,37921,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la comunidad no tuviera plántulas, no ... nada que regar. Por eso las planta.'::text,'tendría'::text,'tendrá'::text,'tiene'::text,'Si la comunidad no tuviera plántulas, no tendría nada que regar. Por eso las planta.'::text),
(341285,37921,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la communauté n''avait pas de plants, elle ... rien à arroser. C''est pour ça qu''elle en plante.'::text,'n''aurait'::text,'n''aura'::text,'n''a'::text,'Si la communauté n''avait pas de plants, elle n''aurait rien à arroser. C''est pour ça qu''elle en plante.'::text),
(341288,37921,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topluluğun hiç fidesi olmasaydı sulayacak hiçbir şeyi ... Bu yüzden onları dikiyor.'::text,'olmazdı'::text,'olmayacak'::text,'yok'::text,'Topluluğun hiç fidesi olmasaydı sulayacak hiçbir şeyi olmazdı Bu yüzden onları dikiyor.'::text),
(341289,37921,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a közösségnek nem lennének palántái, nem ... mit locsolnia. Ezért ülteti őket.'::text,'lenne'::text,'lesz'::text,'van'::text,'Ha a közösségnek nem lennének palántái, nem lenne mit locsolnia. Ezért ülteti őket.'::text),
(341301,37923,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die ganze Gemeinschaft ..., als das Schild hochging! Absolutes Chaos!'::text,'jubelte'::text,'wurde bejubelt'::text,'jubelnd'::text,'Die ganze Gemeinschaft jubelte, als das Schild hochging! Absolutes Chaos!'::text),
(341305,37923,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уся громада ..., коли підняли табличку! Абсолютний хаос!'::text,'раділа'::text,'була вшанована'::text,'радіючи'::text,'Уся громада раділа, коли підняли табличку! Абсолютний хаос!'::text),
(341304,37923,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Toda la comunidad ... cuando subieron el cartel! ¡Caos absoluto!'::text,'vitoreó'::text,'fue vitoreada'::text,'vitoreando'::text,'¡Toda la comunidad vitoreó cuando subieron el cartel! ¡Caos absoluto!'::text),
(341303,37923,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toute la communauté ... quand le panneau a été levé ! Chaos absolu !'::text,'a applaudi'::text,'a été applaudie'::text,'applaudissant'::text,'Toute la communauté a applaudi quand le panneau a été levé ! Chaos absolu !'::text),
(341306,37923,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabela kaldırıldığında bütün topluluk ...! Tam bir kaos!'::text,'alkışladı'::text,'alkışlandı'::text,'alkışlayarak'::text,'Tabela kaldırıldığında bütün topluluk alkışladı! Tam bir kaos!'::text),
(341307,37923,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész közösség ..., amikor felkerült a tábla! Totális káosz!'::text,'ujjongott'::text,'meg lett éljenezve'::text,'ujjongva'::text,'Az egész közösség ujjongott, amikor felkerült a tábla! Totális káosz!'::text),
(341310,37924,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alle in der Gemeinschaft jubeln, also ... mit dem Garten zufrieden sein.'::text,'müssen sie'::text,'können sie nicht'::text,'sollten sie'::text,'Alle in der Gemeinschaft jubeln, also müssen sie mit dem Garten zufrieden sein.'::text),
(341314,37924,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усі в громаді радіють, тож вони ... бути задоволені садом.'::text,'мусять'::text,'не можуть'::text,'мали б'::text,'Усі в громаді радіють, тож вони мусять бути задоволені садом.'::text),
(341313,37924,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todos en la comunidad están aplaudiendo, así que ... estar contentos con el huerto.'::text,'deben de'::text,'no pueden'::text,'deberían'::text,'Todos en la comunidad están aplaudiendo, así que deben de estar contentos con el huerto.'::text),
(341312,37924,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le monde dans la communauté applaudit, donc ils ... être contents du jardin.'::text,'doivent'::text,'ne peuvent pas'::text,'devraient'::text,'Tout le monde dans la communauté applaudit, donc ils doivent être contents du jardin.'::text),
(341315,37924,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Topluluktaki herkes tezahürat yapıyor, yani bahçeden memnun ...'::text,'olmalılar'::text,'olamazlar'::text,'olmalılar'::text,'Topluluktaki herkes tezahürat yapıyor, yani bahçeden memnun olmalılar.'::text),
(341316,37924,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A közösségben mindenki ujjong, szóval ... elégedettek a kerttel.'::text,'biztos'::text,'nem lehetnek'::text,'kellene legyenek'::text,'A közösségben mindenki ujjong, szóval biztos elégedettek a kerttel.'::text),
(341319,37925,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der kleine Junge ist einer der Nachbarn, ... der Gemeinschaft beim Pflanzen der Setzlinge helfen.'::text,'die'::text,'die'::text,'deren'::text,'Der kleine Junge ist einer der Nachbarn, die der Gemeinschaft beim Pflanzen der Setzlinge helfen.'::text),
(341323,37925,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленький хлопчик — один із сусідів, ... допомагають громаді садити саджанці.'::text,'які'::text,'котрі'::text,'чиї'::text,'Маленький хлопчик — один із сусідів, які допомагають громаді садити саджанці.'::text),
(341322,37925,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El niño pequeño es uno de los vecinos ... ayudan a la comunidad a plantar plántulas.'::text,'que'::text,'los cuales'::text,'cuyos'::text,'El niño pequeño es uno de los vecinos que ayudan a la comunidad a plantar plántulas.'::text),
(341321,37925,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le petit garçon est l''un des voisins ... aident la communauté à planter des plants.'::text,'qui'::text,'lesquels'::text,'dont'::text,'Le petit garçon est l''un des voisins qui aident la communauté à planter des plants.'::text),
(341324,37925,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük çocuk, topluluğun fide dikmesine ... yardım eden komşulardan biri.'::text,''::text,NULL::text,NULL::text,'Küçük çocuk, topluluğun fide dikmesine yardım eden komşulardan biri.'::text),
(341325,37925,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kisfiú azon szomszédok egyike, ... segítenek a közösségnek palántákat ültetni.'::text,'akik'::text,'amelyek'::text,'akiknek a'::text,'A kisfiú azon szomszédok egyike, akik segítenek a közösségnek palántákat ültetni.'::text),
(341328,37926,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzten Frühling sagte die junge Frau der Gemeinschaft, dass sie die Setzlinge jeden Tag ...'::text,'gießen würde'::text,'gießen wird'::text,'gießt'::text,'Letzten Frühling sagte die junge Frau der Gemeinschaft, dass sie die Setzlinge jeden Tag gießen würde.'::text),
(341332,37926,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулої весни молода жінка сказала громаді, що ... саджанці щодня.'::text,'поливатиме'::text,'поливатиме'::text,'поливає'::text,'Минулої весни молода жінка сказала громаді, що поливатиме саджанці щодня.'::text),
(341331,37926,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La primavera pasada, la joven le dijo a la comunidad que ... las plántulas todos los días.'::text,'regaría'::text,'regará'::text,'riega'::text,'La primavera pasada, la joven le dijo a la comunidad que regaría las plántulas todos los días.'::text),
(341330,37926,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le printemps dernier, la jeune femme a dit à la communauté qu''elle ... les plants tous les jours.'::text,'arroserait'::text,'arrosera'::text,'arrose'::text,'Le printemps dernier, la jeune femme a dit à la communauté qu''elle arroserait les plants tous les jours.'::text),
(341333,37926,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen bahar genç kadın topluluğa fideleri her gün ... söyledi.'::text,'sulayacağını'::text,'sulayacağını'::text,'suladığını'::text,'Geçen bahar genç kadın topluluğa fideleri her gün sulayacağını söyledi.'::text),
(341334,37926,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavaly tavasszal a fiatal nő azt mondta a közösségnek, hogy minden nap ... a palántákat.'::text,'locsolni fogja'::text,'locsolni fogja'::text,'locsolja'::text,'Tavaly tavasszal a fiatal nő azt mondta a közösségnek, hogy minden nap locsolni fogja a palántákat.'::text),
(397812,44202,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, anscheinend sind sie den ganzen Pfad lachend hochgeklettert, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Girl, anscheinend sind sie den ganzen Pfad lachend hochgeklettert, oder?'::text),
(397816,44202,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вони піднялися всією тією стежкою, сміючись, ...?'::text,'так?'::text,'так?'::text,'так?'::text,'Подруго, кажуть, вони піднялися всією тією стежкою, сміючись, так?'::text)
