(397815,44202,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que subieron todo ese sendero riéndose, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Tía, parece que subieron todo ese sendero riéndose, ¿verdad?'::text),
(397814,44202,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment ils ont grimpé tout ce sentier en rigolant, ... ?'::text,'non ?'::text,'non ?'::text,'non ?'::text,'Meuf, apparemment ils ont grimpé tout ce sentier en rigolant, non ?'::text),
(397817,44202,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, galiba o bütün patikayı gülerek tırmandılar, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Kızım, galiba o bütün patikayı gülerek tırmandılar, değil mi?'::text),
(397818,44202,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag végigmásztak azon az egész ösvényen nevetve, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Csajszi, állítólag végigmásztak azon az egész ösvényen nevetve, ugye?'::text),
