(397825,44203,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, кажуть, йому подобався кожен корінь на тій стежці, і ...'::text,'його другові також'::text,'його другові також'::text,'його другові ні'::text,'Слухай, кажуть, йому подобався кожен корінь на тій стежці, і його другові також.'::text),
(397824,44203,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, parece que le encantó cada raíz de ese sendero, y ...'::text,'a su amigo también'::text,'a su amigo también'::text,'a su amigo tampoco'::text,'Oye, parece que le encantó cada raíz de ese sendero, y a su amigo también.'::text),
(397823,44203,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, apparemment il a adoré chaque racine de ce sentier, et ...'::text,'son pote aussi'::text,'son pote aussi'::text,'son pote non plus'::text,'Écoute, apparemment il a adoré chaque racine de ce sentier, et son pote aussi.'::text),
(397826,44203,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, galiba o patikadaki her kökü sevmiş, ...'::text,'arkadaşı da öyle'::text,'arkadaşı da öyle'::text,'arkadaşı da sevmemiş'::text,'Dinle, galiba o patikadaki her kökü sevmiş, arkadaşı da öyle.'::text),
(397827,44203,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, állítólag imádott minden gyökeret azon az ösvényen, és ...'::text,'a haverja is'::text,'a haverja is'::text,'a haverja sem'::text,'Figyelj, állítólag imádott minden gyökeret azon az ösvényen, és a haverja is.'::text),
(397830,44204,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab gehört, sie ... drei Stunden lang diesen Pfad hinauf, bevor sie oben ankamen.'::text,'kletterten'::text,'klettern'::text,'kletterten gerade'::text,'Bestie, ich hab gehört, sie kletterten drei Stunden lang diesen Pfad hinauf, bevor sie oben ankamen.'::text),
(397834,44204,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що вони ... тією стежкою три години, перш ніж дісталися вершини.'::text,'підіймалися'::text,'підіймаються'::text,'підіймалися'::text,'Подруго, я чула, що вони підіймалися тією стежкою три години, перш ніж дісталися вершини.'::text),
(397833,44204,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, oí que ... tres horas subiendo ese sendero antes de llegar a la cima.'::text,'habían estado'::text,'han estado'::text,'estaban'::text,'Amiga, oí que habían estado tres horas subiendo ese sendero antes de llegar a la cima.'::text),
(397832,44204,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, j''ai entendu dire qu''ils ... ce sentier pendant trois heures avant d''atteindre le sommet.'::text,'avaient grimpé'::text,'ont grimpé'::text,'grimpaient'::text,'Ma belle, j''ai entendu dire qu''ils avaient grimpé ce sentier pendant trois heures avant d''atteindre le sommet.'::text),
(397835,44204,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duydum ki zirveye ulaşmadan önce üç saat boyunca o patikadan ...'::text,'tırmanıyorlarmış'::text,'tırmanıyorlar'::text,'tırmanıyorlardı'::text,'Kanka, duydum ki zirveye ulaşmadan önce üç saat boyunca o patikadan tırmanıyorlarmış.'::text),
(397836,44204,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy három órán át ... azon az ösvényen, mielőtt felértek a csúcsra.'::text,'másztak felfelé'::text,'másznak felfelé'::text,'másztak felfelé'::text,'Csajszi, azt hallottam, hogy három órán át másztak felfelé azon az ösvényen, mielőtt felértek a csúcsra.'::text),
(397848,44206,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um zwölf ... du schon fünf Stunden auf diesem Pfad unterwegs, und du lachst immer noch? Respekt.'::text,'bist'::text,'bist'::text,'bist'::text,'Um zwölf bist du schon fünf Stunden auf diesem Pfad unterwegs, und du lachst immer noch? Respekt.'::text),
(397852,44206,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До полудня ти ... цією стежкою вже п''ять годин, і досі смієшся? Респект.'::text,'йтимеш'::text,'йтимеш'::text,'пройдеш'::text,'До полудня ти йтимеш цією стежкою вже п''ять годин, і досі смієшся? Респект.'::text),
(397851,44206,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía ... cinco horas por este sendero, ¿y sigues riéndote? Respeto.'::text,'habrás estado caminando'::text,'estarás caminando'::text,'habrás caminado'::text,'Para el mediodía habrás estado caminando cinco horas por este sendero, ¿y sigues riéndote? Respeto.'::text),
(397850,44206,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À midi, tu ... sur ce sentier depuis cinq heures, et tu rigoles encore ? Respect.'::text,'marcheras'::text,'marcheras'::text,'auras marché'::text,'À midi, tu marcheras sur ce sentier depuis cinq heures, et tu rigoles encore ? Respect.'::text),
(397853,44206,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlen olduğunda bu patikada beş saattir ... ve hâlâ gülüyor musun? Saygı.'::text,'yürüyor olacaksın'::text,'yürüyor olacaksın'::text,'yürümüş olacaksın'::text,'Öğlen olduğunda bu patikada beş saattir yürüyor olacaksın ve hâlâ gülüyor musun? Saygı.'::text),
(397854,44206,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre öt órája ... ezen az ösvényen, és még mindig nevetsz? Respekt.'::text,'gyalogolsz'::text,'gyalogolsz'::text,'gyalogoltál'::text,'Délre öt órája gyalogolsz ezen az ösvényen, és még mindig nevetsz? Respekt.'::text),
(397857,44207,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makellose Planung. Wenn sie auf die Karte geschaut hätten, ... sie den felsigen Pfad nicht genommen.'::text,'hätten'::text,'werden'::text,'haben'::text,'Makellose Planung. Wenn sie auf die Karte geschaut hätten, hätten sie den felsigen Pfad nicht genommen.'::text),
(397861,44207,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганне планування. Якби вони подивилися на карту, то ... ту кам''янисту стежку.'::text,'не обрали б'::text,'не оберуть'::text,'не обрали'::text,'Бездоганне планування. Якби вони подивилися на карту, то не обрали б ту кам''янисту стежку.'::text),
(397860,44207,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planificación impecable. Si hubieran mirado el mapa, ... el sendero rocoso.'::text,'no habrían tomado'::text,'no tomarán'::text,'no tomaron'::text,'Planificación impecable. Si hubieran mirado el mapa, no habrían tomado el sendero rocoso.'::text),
(397859,44207,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Organisation impeccable. S''ils avaient regardé la carte, ils ... le sentier rocailleux.'::text,'n''auraient pas pris'::text,'ne prendront pas'::text,'n''ont pas pris'::text,'Organisation impeccable. S''ils avaient regardé la carte, ils n''auraient pas pris le sentier rocailleux.'::text),
(397862,44207,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz planlama. Haritaya baksalardı kayalık patikayı ...'::text,'seçmezlerdi'::text,'seçmeyecekler'::text,'seçmediler'::text,'Kusursuz planlama. Haritaya baksalardı kayalık patikayı seçmezlerdi.'::text),
(397863,44207,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan tervezés. Ha megnézték volna a térképet, ... a sziklás ösvényt.'::text,'nem választották volna'::text,'nem választják'::text,'nem választották'::text,'Hibátlan tervezés. Ha megnézték volna a térképet, nem választották volna a sziklás ösvényt.'::text),
(397866,44208,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie auf dem unteren Pfad geblieben wären, ... sie jetzt nicht auf dem felsigen Gipfel.'::text,'stünden'::text,'stünden'::text,'stehen'::text,'Wenn sie auf dem unteren Pfad geblieben wären, stünden sie jetzt nicht auf dem felsigen Gipfel.'::text),
(397870,44208,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вони залишилися на нижній стежці, вони ... зараз на скелястій вершині.'::text,'не стояли б'::text,'не стояли б'::text,'не стоятимуть'::text,'Якби вони залишилися на нижній стежці, вони не стояли б зараз на скелястій вершині.'::text),
(397869,44208,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se hubieran quedado en el sendero de abajo, ahora ... en la cima rocosa.'::text,'no estarían'::text,'no habrían estado'::text,'no estarán'::text,'Si se hubieran quedado en el sendero de abajo, ahora no estarían en la cima rocosa.'::text),
(397868,44208,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''ils étaient restés sur le sentier du bas, ils ... sur le sommet rocheux maintenant.'::text,'ne seraient pas'::text,'n''auraient pas été'::text,'ne seront pas'::text,'S''ils étaient restés sur le sentier du bas, ils ne seraient pas sur le sommet rocheux maintenant.'::text),
(397871,44208,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alt patikada kalsalardı şimdi kayalık zirvede ...'::text,'durmuyor olurlardı'::text,'durmamış olurlardı'::text,'durmayacaklar'::text,'Alt patikada kalsalardı şimdi kayalık zirvede durmuyor olurlardı.'::text),
(397872,44208,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha az alsó ösvényen maradtak volna, most ... a sziklás csúcson.'::text,'nem állnának'::text,'nem álltak volna'::text,'nem fognak állni'::text,'Ha az alsó ösvényen maradtak volna, most nem állnának a sziklás csúcson.'::text),
(397875,44209,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieser Pfad soll vor Hunderten von Jahren von Hirten ...'::text,'angelegt worden sein'::text,'angelegt werden'::text,'angelegt werden'::text,'Dieser Pfad soll vor Hunderten von Jahren von Hirten angelegt worden sein.'::text),
(397879,44209,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кажуть, цю стежку ... пастухи сотні років тому.'::text,'проклали'::text,'прокладають'::text,'прокладаючи'::text,'Кажуть, цю стежку проклали пастухи сотні років тому.'::text),
(397878,44209,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se dice que este sendero ... por pastores hace cientos de años.'::text,'fue hecho'::text,'es hecho'::text,'siendo hecho'::text,'Se dice que este sendero fue hecho por pastores hace cientos de años.'::text),
(397877,44209,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On dit que ce sentier ... par des bergers il y a des centaines d''années.'::text,'a été tracé'::text,'est tracé'::text,'étant tracé'::text,'On dit que ce sentier a été tracé par des bergers il y a des centaines d''années.'::text),
(397880,44209,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu patikanın yüzlerce yıl önce çobanlar tarafından ... söyleniyor.'::text,'açıldığı'::text,'açılacağı'::text,'açılmakta olduğu'::text,'Bu patikanın yüzlerce yıl önce çobanlar tarafından açıldığı söyleniyor.'::text),
(397881,44209,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondják, ezt az ösvényt pásztorok ... több száz évvel ezelőtt.'::text,'készítették'::text,'készítik'::text,'készítve'::text,'Azt mondják, ezt az ösvényt pásztorok készítették több száz évvel ezelőtt.'::text),
(397884,44210,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oben gab ein Wanderer zu, auf dem steilen Pfad außer Atem ...'::text,'gewesen zu sein'::text,'zu sein'::text,'sein'::text,'Oben gab ein Wanderer zu, auf dem steilen Pfad außer Atem gewesen zu sein.'::text),
(397888,44210,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На вершині один турист зізнався, що ... захеканий на крутій стежці.'::text,'був'::text,'бути'::text,'бути'::text,'На вершині один турист зізнався, що був захеканий на крутій стежці.'::text),
(397887,44210,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En la cima, un senderista admitió ... sin aliento en el sendero empinado.'::text,'haber estado'::text,'estar'::text,'estar'::text,'En la cima, un senderista admitió haber estado sin aliento en el sendero empinado.'::text),
(397886,44210,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au sommet, un randonneur a avoué ... à bout de souffle sur le sentier raide.'::text,'avoir été'::text,'être'::text,'être'::text,'Au sommet, un randonneur a avoué avoir été à bout de souffle sur le sentier raide.'::text),
(397889,44210,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zirvede bir yürüyüşçü dik patikada nefes nefese ... itiraf etti.'::text,'kaldığını'::text,'kalmayı'::text,'kalmak'::text,'Zirvede bir yürüyüşçü dik patikada nefes nefese kaldığını itiraf etti.'::text),
(397890,44210,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csúcson az egyik túrázó bevallotta, hogy ... a meredek ösvényen.'::text,'kifulladt'::text,'kifullad'::text,'kifulladni'::text,'A csúcson az egyik túrázó bevallotta, hogy kifulladt a meredek ösvényen.'::text),
(397893,44211,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... mich vor diesem Pfad warnen sollen! Das ist buchstäblich ein Albtraum aus Wurzeln!'::text,'hättest'::text,'musst'::text,'solltest'::text,'Du hättest mich vor diesem Pfad warnen sollen! Das ist buchstäblich ein Albtraum aus Wurzeln!'::text),
(397897,44211,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... попередити мене про цю стежку! Це буквально жах із коренів!'::text,'мав'::text,'мусив'::text,'маєш'::text,'Ти мав попередити мене про цю стежку! Це буквально жах із коренів!'::text),
(397896,44211,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... avisarme de este sendero! ¡Es literalmente una pesadilla de raíces!'::text,'Deberías haber'::text,'Tuviste que'::text,'Deberías'::text,'¡Deberías haber avisarme de este sendero! ¡Es literalmente una pesadilla de raíces!'::text),
(397895,44211,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... me prévenir pour ce sentier ! C''est littéralement un cauchemar de racines !'::text,'aurais dû'::text,'as dû'::text,'devrais'::text,'Tu aurais dû me prévenir pour ce sentier ! C''est littéralement un cauchemar de racines !'::text),
(397898,44211,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beni bu patika hakkında ...! Resmen kök kâbusu!'::text,'uyarmalıydın'::text,'uyarmış olmalısın'::text,'uyarmalısın'::text,'Beni bu patika hakkında uyarmalıydın! Resmen kök kâbusu!'::text),
(397899,44211,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... figyelmeztetned erre az ösvényre! Szó szerint egy gyökérrémálom!'::text,'Kellett volna'::text,'Biztos kellett'::text,'Kellene'::text,'Kellett volna figyelmeztetned erre az ösvényre! Szó szerint egy gyökérrémálom!'::text),
(338304,37590,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie ... schüchtern, aber jetzt kümmert sie sich um Patienten wie ein Profi, echt.'::text,'war früher'::text,'wäre'::text,'ist'::text,'Digga, sie war früher schüchtern, aber jetzt kümmert sie sich um Patienten wie ein Profi, echt.'::text),
(338308,37590,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... сором''язливою, але тепер доглядає пацієнтів як профі, реально.'::text,'колись була'::text,'була б'::text,'звикла бути'::text,'Бро, вона колись була сором''язливою, але тепер доглядає пацієнтів як профі, реально.'::text),
(338307,37590,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... ser tímida, pero ahora cuida a los pacientes como una pro, en serio.'::text,'solía'::text,'solía'::text,'está acostumbrada a'::text,'Bro, ella solía ser tímida, pero ahora cuida a los pacientes como una pro, en serio.'::text),
(338306,37590,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... timide, mais maintenant elle s''occupe des patients comme une pro, grave.'::text,'était avant'::text,'serait'::text,'a l''habitude d''être'::text,'Frérot, elle était avant timide, mais maintenant elle s''occupe des patients comme une pro, grave.'::text),
(338309,37590,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o eskiden utangaç ..., ama şimdi hastalara profesyonel gibi bakıyor, cidden.'::text,'biriydi'::text,'biri olurdu'::text,'olmaya alışkın'::text,'Kanka, o eskiden utangaç biriydi, ama şimdi hastalara profesyonel gibi bakıyor, cidden.'::text),
(338310,37590,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ő félénk ..., de most úgy ápolja a betegeket, mint egy profi, komolyan.'::text,'volt régen'::text,'lenne'::text,'szokott lenni'::text,'Tesó, ő félénk volt régen, de most úgy ápolja a betegeket, mint egy profi, komolyan.'::text),
(338313,37591,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie hat insgeheim richtig Bock drauf, sich um den Typen zu ..., schau dir das Lächeln an.'::text,'kümmern'::text,'kümmern'::text,'kümmern'::text,'Alter, sie hat insgeheim richtig Bock drauf, sich um den Typen zu kümmern, schau dir das Lächeln an.'::text),
(338317,37591,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, їй потай подобається ... про цього хлопця, глянь на цю усмішку.'::text,'піклуватися'::text,'піклуватися'::text,'піклуватися'::text,'Чувак, їй потай подобається піклуватися про цього хлопця, глянь на цю усмішку.'::text),
(338316,37591,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, en el fondo le encanta ... de este chico, mira esa sonrisa.'::text,'cuidar'::text,'cuidar'::text,'cuidar'::text,'Tío, en el fondo le encanta cuidar de este chico, mira esa sonrisa.'::text),
(338315,37591,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mec, elle kiffe un peu trop ... de ce gars, regarde ce sourire.'::text,'s''occuper'::text,'s''occuper'::text,'s''occuper'::text,'Mec, elle kiffe un peu trop s''occuper de ce gars, regarde ce sourire.'::text),
(338318,37591,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu çocuğa ... gizliden gizliye bayılıyor, şu gülümsemeye bak.'::text,'bakmaya'::text,'bakmaya'::text,'bakmaya'::text,'Kanka, bu çocuğa bakmaya gizliden gizliye bayılıyor, şu gülümsemeye bak.'::text),
(338319,37591,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Haver, titokban élvezi, hogy ... erről a srácról, nézd azt a mosolyt.'::text,'gondoskodik'::text,'gondoskodhat'::text,'gondoskodik'::text,'Haver, titokban élvezi, hogy gondoskodik erről a srácról, nézd azt a mosolyt.'::text),
(338322,37592,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Krankenschwester kümmert sich sehr sanft um den Patienten, ...?'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Die Krankenschwester kümmert sich sehr sanft um den Patienten, oder?'::text),
(338326,37592,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Медсестра дуже ніжно доглядає пацієнта, ...?'::text,'правда?'::text,'правда?'::text,'правда?'::text,'Медсестра дуже ніжно доглядає пацієнта, правда?'::text),
(338325,37592,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La enfermera cuida al paciente con mucha delicadeza, ...?'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'La enfermera cuida al paciente con mucha delicadeza, ¿verdad?'::text),
(338324,37592,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''infirmière s''occupe du patient très doucement, ... ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'n''est-ce pas ?'::text,'L''infirmière s''occupe du patient très doucement, n''est-ce pas ?'::text),
(338327,37592,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemşire hastaya çok nazik bakıyor, ...?'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Hemşire hastaya çok nazik bakıyor, değil mi?'::text),
(338328,37592,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ápolónő nagyon gyengéden gondoskodik a betegről, ...?'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Az ápolónő nagyon gyengéden gondoskodik a betegről, ugye?'::text),
(338340,37594,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich den ganzen Vormittag um den Patienten, bevor er endlich lachte.'::text,'kümmerte'::text,'kümmert'::text,'kümmerte gerade'::text,'Sie kümmerte sich den ganzen Vormittag um den Patienten, bevor er endlich lachte.'::text),
(338344,37594,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... пацієнта весь ранок, перш ніж він нарешті засміявся.'::text,'доглядала'::text,'доглядає'::text,'доглядала'::text,'Вона доглядала пацієнта весь ранок, перш ніж він нарешті засміявся.'::text),
(338343,37594,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... al paciente toda la mañana antes de que por fin se riera.'::text,'había estado cuidando'::text,'ha estado cuidando'::text,'estaba cuidando'::text,'Ella había estado cuidando al paciente toda la mañana antes de que por fin se riera.'::text),
(338342,37594,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... du patient toute la matinée avant qu''il rie enfin.'::text,'s''était occupée'::text,'s''est occupée'::text,'s''occupait'::text,'Elle s''était occupée du patient toute la matinée avant qu''il rie enfin.'::text),
(338345,37594,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hasta sonunda gülene kadar bütün sabah ona ...'::text,'bakıyordu'::text,'bakıyor'::text,'bakıyordu'::text,'Hasta sonunda gülene kadar bütün sabah ona bakıyordu.'::text),
(338346,37594,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész délelőtt ... a betegről, mielőtt az végre felnevetett.'::text,'gondoskodott'::text,'gondoskodik'::text,'gondoskodott'::text,'Egész délelőtt gondoskodott a betegről, mielőtt az végre felnevetett.'::text),
(338349,37595,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende ihrer Schicht wird sich die Krankenschwester um zwölf Patienten ...'::text,'gekümmert haben'::text,'kümmern'::text,'am Kümmern sein'::text,'Bis zum Ende ihrer Schicht wird sich die Krankenschwester um zwölf Patienten gekümmert haben.'::text),
(338353,37595,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця зміни медсестра ... дванадцять пацієнтів.'::text,'догляне'::text,'доглядатиме'::text,'доглядатиме'::text,'До кінця зміни медсестра догляне дванадцять пацієнтів.'::text),
(338352,37595,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el final de su turno, la enfermera ... a doce pacientes.'::text,'habrá cuidado'::text,'cuidará'::text,'estará cuidando'::text,'Para el final de su turno, la enfermera habrá cuidado a doce pacientes.'::text),
(338351,37595,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici la fin de son service, l''infirmière ... de douze patients.'::text,'se sera occupée'::text,'s''occupera'::text,'sera en train de s''occuper'::text,'D''ici la fin de son service, l''infirmière se sera occupée de douze patients.'::text),
(338354,37595,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vardiyasının sonuna kadar hemşire on iki hastaya ...'::text,'bakmış olacak'::text,'bakacak'::text,'bakıyor olacak'::text,'Vardiyasının sonuna kadar hemşire on iki hastaya bakmış olacak.'::text),
(338355,37595,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A műszakja végére az ápolónő tizenkét betegről ...'::text,'gondoskodott majd'::text,'fog gondoskodni'::text,'gondoskodni fog'::text,'A műszakja végére az ápolónő tizenkét betegről gondoskodott majd.'::text),
(338367,37597,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du dich nicht so lieb um ihn gekümmert hättest, ... er nicht so gelacht. Respekt.'::text,'hätte'::text,'wird'::text,'hat'::text,'Wenn du dich nicht so lieb um ihn gekümmert hättest, hätte er nicht so gelacht. Respekt.'::text),
(338371,37597,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ти не доглянула його так мило, він ... так. Респект.'::text,'не сміявся б'::text,'не сміятиметься'::text,'не сміявся'::text,'Якби ти не доглянула його так мило, він не сміявся б так. Респект.'::text),
(338370,37597,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no lo hubieras cuidado con tanto cariño, ... así. Respeto.'::text,'no se habría reído'::text,'no se reirá'::text,'no se rio'::text,'Si no lo hubieras cuidado con tanto cariño, no se habría reído así. Respeto.'::text),
(338369,37597,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu ne t''étais pas occupée de lui si gentiment, il ... comme ça. Respect.'::text,'n''aurait pas ri'::text,'ne rira pas'::text,'n''a pas ri'::text,'Si tu ne t''étais pas occupée de lui si gentiment, il n''aurait pas ri comme ça. Respect.'::text),
(338372,37597,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ona bu kadar güzel bakmasaydın öyle ... Saygı.'::text,'gülmezdi'::text,'gülmeyecek'::text,'gülmedi'::text,'Ona bu kadar güzel bakmasaydın öyle gülmezdi Saygı.'::text),
(338373,37597,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem gondoskodtál volna róla ilyen kedvesen, ... így. Respekt.'::text,'nem nevetett volna'::text,'nem fog nevetni'::text,'nem nevetett'::text,'Ha nem gondoskodtál volna róla ilyen kedvesen, nem nevetett volna így. Respekt.'::text),
(338376,37598,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du dich heute Morgen nicht um ihn gekümmert hättest, ... er jetzt nicht so glücklich. Ehrlich beeindruckend.'::text,'wäre'::text,'wäre'::text,'wird'::text,'Wenn du dich heute Morgen nicht um ihn gekümmert hättest, wäre er jetzt nicht so glücklich. Ehrlich beeindruckend.'::text),
(338380,37598,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби ти не доглянула його сьогодні вранці, він ... таким щасливим зараз. Чесно, вражає.'::text,'не був би'::text,'не був би'::text,'не буде'::text,'Якби ти не доглянула його сьогодні вранці, він не був би таким щасливим зараз. Чесно, вражає.'::text),
(338379,37598,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no lo hubieras cuidado esta mañana, ... tan feliz ahora. Sinceramente impresionante.'::text,'no estaría'::text,'no habría estado'::text,'no estará'::text,'Si no lo hubieras cuidado esta mañana, no estaría tan feliz ahora. Sinceramente impresionante.'::text),
(338378,37598,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu ne t''étais pas occupée de lui ce matin, il ... aussi heureux maintenant. Franchement impressionnant.'::text,'ne serait pas'::text,'n''aurait pas été'::text,'ne sera pas'::text,'Si tu ne t''étais pas occupée de lui ce matin, il ne serait pas aussi heureux maintenant. Franchement impressionnant.'::text),
(338381,37598,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah ona bakmasaydın şimdi bu kadar mutlu ... Açıkçası etkileyici.'::text,'olmazdı'::text,'olmamış olurdu'::text,'olmayacak'::text,'Bu sabah ona bakmasaydın şimdi bu kadar mutlu olmazdı Açıkçası etkileyici.'::text),
(338382,37598,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ma reggel nem gondoskodtál volna róla, most ... ilyen boldog. Őszintén lenyűgöző.'::text,'nem lenne'::text,'nem lett volna'::text,'nem lesz'::text,'Ha ma reggel nem gondoskodtál volna róla, most nem lenne ilyen boldog. Őszintén lenyűgöző.'::text),
(338385,37599,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bekanntlich wurde der Patient die ganze Woche wie ein König ... Könnte schlimmer sein.'::text,'umsorgt'::text,'umsorgen'::text,'umsorgend'::text,'Bekanntlich wurde der Patient die ganze Woche wie ein König umsorgt Könnte schlimmer sein.'::text),
(338389,37599,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відомо, що про пацієнта ... як про короля весь тиждень. Могло бути гірше.'::text,'дбали'::text,'дбати'::text,'дбаючи'::text,'Відомо, що про пацієнта дбали як про короля весь тиждень. Могло бути гірше.'::text),
(338388,37599,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se sabe que al paciente lo ... como a un rey toda la semana. Podría ser peor.'::text,'han cuidado'::text,'cuidar'::text,'cuidando'::text,'Se sabe que al paciente lo han cuidado como a un rey toda la semana. Podría ser peor.'::text),
(338387,37599,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On sait que le patient ... comme un roi toute la semaine. Ça pourrait être pire.'::text,'a été soigné'::text,'soigner'::text,'soignant'::text,'On sait que le patient a été soigné comme un roi toute la semaine. Ça pourrait être pire.'::text),
(338390,37599,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hastaya bütün hafta bir kral gibi ... biliniyor. Daha kötü olabilirdi.'::text,'bakıldığı'::text,'bakmak'::text,'bakarak'::text,'Hastaya bütün hafta bir kral gibi bakıldığı biliniyor. Daha kötü olabilirdi.'::text),
(338391,37599,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köztudott, hogy a betegről egész héten úgy ..., mint egy királyról. Lehetne rosszabb.'::text,'gondoskodtak'::text,'gondoskodni'::text,'gondoskodva'::text,'Köztudott, hogy a betegről egész héten úgy gondoskodtak, mint egy királyról. Lehetne rosszabb.'::text),
(338394,37600,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Krankenschwester stritt ab, sich liebevoller um ihn ... als um die anderen Patienten. Natürlich.'::text,'gekümmert zu haben'::text,'zu kümmern'::text,'kümmerte'::text,'Die Krankenschwester stritt ab, sich liebevoller um ihn gekümmert zu haben als um die anderen Patienten. Natürlich.'::text),
(338398,37600,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Медсестра заперечила, що ... про нього ніжніше, ніж про інших пацієнтів. Звісно.'::text,'дбала'::text,'дбати'::text,'дбала'::text,'Медсестра заперечила, що дбала про нього ніжніше, ніж про інших пацієнтів. Звісно.'::text),
(338397,37600,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La enfermera negó ... de él con más cariño que de los otros pacientes. Obviamente.'::text,'cuidar'::text,'cuidar'::text,'cuidó'::text,'La enfermera negó cuidar de él con más cariño que de los otros pacientes. Obviamente.'::text),
(338396,37600,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''infirmière a nié ... de lui plus gentiment que des autres patients. Évidemment.'::text,'s''occuper'::text,'s''occuper'::text,'s''être occupée'::text,'L''infirmière a nié s''occuper de lui plus gentiment que des autres patients. Évidemment.'::text),
(338399,37600,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hemşire ona diğer hastalardan daha şefkatle ... inkâr etti. Tabii ki.'::text,'baktığını'::text,'bakmayı'::text,'baktı'::text,'Hemşire ona diğer hastalardan daha şefkatle baktığını inkâr etti. Tabii ki.'::text),
(338400,37600,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ápolónő tagadta, hogy kedvesebben ... róla, mint a többi betegről. Nyilván.'::text,'gondoskodott'::text,'gondoskodni'::text,'gondoskodott'::text,'Az ápolónő tagadta, hogy kedvesebben gondoskodott róla, mint a többi betegről. Nyilván.'::text),
(353874,39320,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Eimer war voller Tropfen, also ... er das Rohr viel früher reparieren sollen.'::text,'hätte'::text,'muss'::text,'hätte nicht'::text,'Der Eimer war voller Tropfen, also hätte er das Rohr viel früher reparieren sollen.'::text),
(353878,39320,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Відро було повне крапель, тож він ... полагодити трубу набагато раніше.'::text,'мав'::text,'мусив'::text,'не мав'::text,'Відро було повне крапель, тож він мав полагодити трубу набагато раніше.'::text),
(353877,39320,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El cubo estaba lleno de gotas, así que ... arreglado la tubería mucho antes.'::text,'debería haber'::text,'debe de haber'::text,'no debería haber'::text,'El cubo estaba lleno de gotas, así que debería haber arreglado la tubería mucho antes.'::text),
(353876,39320,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le seau était plein de gouttes, donc il ... réparer le tuyau bien plus tôt.'::text,'aurait dû'::text,'a dû'::text,'n''aurait pas dû'::text,'Le seau était plein de gouttes, donc il aurait dû réparer le tuyau bien plus tôt.'::text),
(353879,39320,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kova damlalarla doluydu, yani boruyu çok daha önce ...'::text,'tamir etmeliydi'::text,'tamir etmiş olmalı'::text,'tamir etmemeliydi'::text,'Kova damlalarla doluydu, yani boruyu çok daha önce tamir etmeliydi.'::text),
(353880,39320,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vödör tele volt csöpögéssel, szóval sokkal hamarabb ... megjavítania a csövet.'::text,'kellett volna'::text,'biztos kellett'::text,'nem kellett volna'::text,'A vödör tele volt csöpögéssel, szóval sokkal hamarabb kellett volna megjavítania a csövet.'::text),
(353883,39321,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... so schnell mit nur einer Drehung des Schlüssels repariert.'::text,'wird ein Leck'::text,'ein Leck wird'::text,'ein Leck'::text,'Selten wird ein Leck so schnell mit nur einer Drehung des Schlüssels repariert.'::text),
(353887,39321,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... так швидко лише одним поворотом ключа.'::text,'усувають протікання'::text,'протікання усувають'::text,'протікання'::text,'Рідко усувають протікання так швидко лише одним поворотом ключа.'::text),
(353886,39321,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... tan rápido con solo una vuelta de llave.'::text,'se arregla una fuga'::text,'una fuga se arregla'::text,'una fuga'::text,'Rara vez se arregla una fuga tan rápido con solo una vuelta de llave.'::text),
(353885,39321,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... réparée aussi vite d''un seul tour de clé.'::text,'une fuite est-elle'::text,'une fuite est'::text,'une fuite'::text,'Rarement une fuite est-elle réparée aussi vite d''un seul tour de clé.'::text),
(353888,39321,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren ... tek bir anahtar çevirmesiyle bu kadar hızlı tamir edilir.'::text,'bir sızıntı'::text,'bir sızıntı'::text,'bir sızıntı'::text,'Nadiren bir sızıntı tek bir anahtar çevirmesiyle bu kadar hızlı tamir edilir.'::text),
(353889,39321,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... ilyen gyorsan egyetlen csavarkulcs-fordítással.'::text,'javítanak meg egy szivárgást'::text,'egy szivárgást megjavítanak'::text,'egy szivárgást'::text,'Ritkán javítanak meg egy szivárgást ilyen gyorsan egyetlen csavarkulcs-fordítással.'::text),
(353892,39322,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Girl, anscheinend hat seine Vermieterin ihn die Spüle selbst ... lassen.'::text,'reparieren'::text,'reparieren'::text,'reparieren'::text,'Girl, anscheinend hat seine Vermieterin ihn die Spüle selbst reparieren lassen.'::text),
(353896,39322,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, його хазяйка змусила його ... раковину самотужки.'::text,'полагодити'::text,'полагодити'::text,'лагодження'::text,'Подруго, кажуть, його хазяйка змусила його полагодити раковину самотужки.'::text),
(353895,39322,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, parece que su casera le hizo ... el fregadero él mismo.'::text,'arreglar'::text,'arreglar'::text,'arreglando'::text,'Tía, parece que su casera le hizo arreglar el fregadero él mismo.'::text),
(353894,39322,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, apparemment sa proprio lui a fait ... l''évier lui-même.'::text,'réparer'::text,'réparer'::text,'réparant'::text,'Meuf, apparemment sa proprio lui a fait réparer l''évier lui-même.'::text),
(353897,39322,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, galiba ev sahibesi lavaboyu ona kendi kendine ...'::text,'tamir ettirmiş'::text,'tamir ettirmiş'::text,'tamir ettirerek'::text,'Kızım, galiba ev sahibesi lavaboyu ona kendi kendine tamir ettirmiş.'::text),
(353898,39322,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a főbérlője vele ... meg a mosogatót.'::text,'javíttatta'::text,'javíttatta'::text,'javíttatva'::text,'Csajszi, állítólag a főbérlője vele javíttatta meg a mosogatót.'::text),
(353910,39324,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Typ, ... Stirnlampe an ist, hat die Spüle repariert wie ein Profi, echt.'::text,'dessen'::text,'der'::text,'die'::text,'Digga, der Typ, dessen Stirnlampe an ist, hat die Spüle repariert wie ein Profi, echt.'::text),
(353914,39324,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, хлопець, ... налобний ліхтарик увімкнений, полагодив ту раковину як профі, реально.'::text,'чий'::text,'який'::text,'що'::text,'Бро, хлопець, чий налобний ліхтарик увімкнений, полагодив ту раковину як профі, реально.'::text),
(353913,39324,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, el tío ... linterna frontal está encendida arregló ese fregadero como un pro, en serio.'::text,'cuya'::text,'que'::text,'el cual'::text,'Bro, el tío cuya linterna frontal está encendida arregló ese fregadero como un pro, en serio.'::text),
(353912,39324,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, le gars ... la lampe frontale est allumée a réparé cet évier comme un pro, grave.'::text,'dont'::text,'qui'::text,'que'::text,'Frérot, le gars dont la lampe frontale est allumée a réparé cet évier comme un pro, grave.'::text),
(353915,39324,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... kafa lambası yanan çocuk o lavaboyu profesyonel gibi tamir etti, cidden.'::text,''::text,NULL::text,NULL::text,'Kanka, kafa lambası yanan çocuk o lavaboyu profesyonel gibi tamir etti, cidden.'::text),
(353916,39324,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a srác, ... a fejlámpája világít, úgy megjavította azt a mosogatót, mint egy profi, komolyan.'::text,'akinek'::text,'aki'::text,'amely'::text,'Tesó, a srác, akinek a fejlámpája világít, úgy megjavította azt a mosogatót, mint egy profi, komolyan.'::text),
(353919,39325,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des dunklen Schranks reparierte er das Leck in ein paar Minuten.'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz des dunklen Schranks reparierte er das Leck in ein paar Minuten.'::text),
(353923,39325,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... темну шафку, він полагодив протікання за кілька хвилин.'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри темну шафку, він полагодив протікання за кілька хвилин.'::text),
(353922,39325,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el armario oscuro, arregló la fuga en unos minutos.'::text,'A pesar de'::text,'Aunque'::text,'Debido a'::text,'A pesar de el armario oscuro, arregló la fuga en unos minutos.'::text),
(353921,39325,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... le placard sombre, il a réparé la fuite en quelques minutes.'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré le placard sombre, il a réparé la fuite en quelques minutes.'::text),
(353924,39325,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karanlık dolaba ..., sızıntıyı birkaç dakikada tamir etti.'::text,'rağmen'::text,'karşın'::text,'yüzünden'::text,'Karanlık dolaba rağmen, sızıntıyı birkaç dakikada tamir etti.'::text),
(353925,39325,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sötét szekrény ... pár perc alatt megjavította a szivárgást.'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A sötét szekrény ellenére pár perc alatt megjavította a szivárgást.'::text),
(353928,39326,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte dem Vermieter, dass er die Spüle vor der Deadline um 12:00 ...'::text,'reparieren würde'::text,'reparieren wird'::text,'gerade repariert'::text,'Er sagte dem Vermieter, dass er die Spüle vor der Deadline um 12:00 reparieren würde.'::text),
(353932,39326,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав орендодавцю, що ... раковину до дедлайну о 12:00.'::text,'полагодить'::text,'полагодить'::text,'лагодить'::text,'Він сказав орендодавцю, що полагодить раковину до дедлайну о 12:00.'::text),
(353931,39326,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le dijo al casero que ... el fregadero antes del plazo de las 12:00.'::text,'arreglaría'::text,'arreglará'::text,'está arreglando'::text,'Le dijo al casero que arreglaría el fregadero antes del plazo de las 12:00.'::text),
(353930,39326,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit au propriétaire qu''il ... l''évier avant l''échéance de 12 h.'::text,'réparerait'::text,'réparera'::text,'répare'::text,'Il a dit au propriétaire qu''il réparerait l''évier avant l''échéance de 12 h.'::text),
(353933,39326,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev sahibine lavaboyu saat 12.00 teslim tarihinden önce ... söyledi.'::text,'tamir edeceğini'::text,'tamir edeceğini'::text,'tamir ettiğini'::text,'Ev sahibine lavaboyu saat 12.00 teslim tarihinden önce tamir edeceğini söyledi.'::text),
(353934,39326,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta a főbérlőnek, hogy a 12:00-s határidő előtt ... a mosogatót.'::text,'megjavítja'::text,'meg fogja javítani'::text,'éppen javítja'::text,'Azt mondta a főbérlőnek, hogy a 12:00-s határidő előtt megjavítja a mosogatót.'::text),
(353937,39327,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Moment ... er das Abflussrohr mit einem roten Schraubenschlüssel.'::text,'repariert'::text,'repariert'::text,'reparierte'::text,'Im Moment repariert er das Abflussrohr mit einem roten Schraubenschlüssel.'::text),
(353941,39327,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз він ... зливну трубу червоним ключем.'::text,'лагодить'::text,'лагодить'::text,'полагодив'::text,'Зараз він лагодить зливну трубу червоним ключем.'::text),
(353940,39327,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento, ... la tubería de desagüe con una llave roja.'::text,'está arreglando'::text,'arregla'::text,'ha arreglado'::text,'En este momento, está arreglando la tubería de desagüe con una llave roja.'::text),
(353939,39327,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, il ... le tuyau d''évacuation avec une clé rouge.'::text,'répare'::text,'répare'::text,'a réparé'::text,'En ce moment, il répare le tuyau d''évacuation avec une clé rouge.'::text),
(353942,39327,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda gider borusunu kırmızı bir anahtarla ...'::text,'tamir ediyor'::text,'tamir eder'::text,'tamir etti'::text,'Şu anda gider borusunu kırmızı bir anahtarla tamir ediyor.'::text),
(353943,39327,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Éppen ... a lefolyócsövet egy piros csavarkulccsal.'::text,'javítja'::text,'javítja'::text,'megjavította'::text,'Éppen javítja a lefolyócsövet egy piros csavarkulccsal.'::text),
(353946,39328,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wasser ... etwa eine Stunde lang in den Eimer, bevor er den Abfluss reparierte.'::text,'tropfte'::text,'tropft'::text,'tropft'::text,'Wasser tropfte etwa eine Stunde lang in den Eimer, bevor er den Abfluss reparierte.'::text),
(353950,39328,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вода ... у відро приблизно годину, перш ніж він полагодив злив.'::text,'капала'::text,'капає'::text,'капає'::text,'Вода капала у відро приблизно годину, перш ніж він полагодив злив.'::text),
(353949,39328,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El agua ... en el cubo durante aproximadamente una hora antes de que arreglara el desagüe.'::text,'había estado goteando'::text,'ha estado goteando'::text,'gotea'::text,'El agua había estado goteando en el cubo durante aproximadamente una hora antes de que arreglara el desagüe.'::text),
(353948,39328,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''eau ... dans le seau pendant environ une heure avant qu''il répare l''évacuation.'::text,'avait goutté'::text,'a goutté'::text,'goutte'::text,'L''eau avait goutté dans le seau pendant environ une heure avant qu''il répare l''évacuation.'::text),
(353951,39328,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O gideri tamir etmeden önce su yaklaşık bir saat boyunca kovaya ...'::text,'damlıyordu'::text,'damlıyor'::text,'damlar'::text,'O gideri tamir etmeden önce su yaklaşık bir saat boyunca kovaya damlıyordu.'::text),
(353952,39328,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A víz körülbelül egy órán át ... a vödörbe, mielőtt megjavította a lefolyót.'::text,'csöpögött'::text,'csöpög'::text,'csöpög'::text,'A víz körülbelül egy órán át csöpögött a vödörbe, mielőtt megjavította a lefolyót.'::text),
(353955,39329,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis heute Abend wirst du jedes Leck in dieser Küche ..., ganz ehrlich.'::text,'repariert haben'::text,'reparieren'::text,'reparieren'::text,'Bis heute Abend wirst du jedes Leck in dieser Küche repariert haben, ganz ehrlich.'::text),
(353959,39329,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До вечора ти ... кожне протікання на цій кухні, чесно.'::text,'полагодиш'::text,'лагодитимеш'::text,'лагодиш'::text,'До вечора ти полагодиш кожне протікання на цій кухні, чесно.'::text),
(353958,39329,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para esta noche ... todas las fugas de esta cocina, no te voy a mentir.'::text,'habrás arreglado'::text,'arreglarás'::text,'arreglas'::text,'Para esta noche habrás arreglado todas las fugas de esta cocina, no te voy a mentir.'::text),
(353957,39329,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici ce soir, tu ... toutes les fuites de cette cuisine, je vais pas mentir.'::text,'auras réparé'::text,'répareras'::text,'répares'::text,'D''ici ce soir, tu auras réparé toutes les fuites de cette cuisine, je vais pas mentir.'::text),
(353960,39329,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu akşama kadar bu mutfaktaki her sızıntıyı ..., yalan yok.'::text,'tamir etmiş olacaksın'::text,'tamir edeceksin'::text,'tamir edersin'::text,'Bu akşama kadar bu mutfaktaki her sızıntıyı tamir etmiş olacaksın, yalan yok.'::text),
(353961,39329,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estére ... ebben a konyhában minden szivárgást, nem hazudok.'::text,'megjavítod'::text,'meg fogod javítani'::text,'javítod'::text,'Estére megjavítod ebben a konyhában minden szivárgást, nem hazudok.'::text),
(380784,42310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Selten ... so glücklich über einen Goldstern als Belohnung aus.'::text,'sah ein Schüler'::text,'ein Schüler sah'::text,'sah ein Schüler'::text,'Selten sah ein Schüler so glücklich über einen Goldstern als Belohnung aus.'::text),
(380788,42310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Рідко ... таким щасливим через золоту зірочку в нагороду.'::text,'виглядав учень'::text,'учень виглядав'::text,'виглядав учень'::text,'Рідко виглядав учень таким щасливим через золоту зірочку в нагороду.'::text),
(380787,42310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rara vez ... tan feliz por una estrella dorada de premio.'::text,'ha parecido un alumno'::text,'un alumno ha parecido'::text,'pareció un alumno'::text,'Rara vez ha parecido un alumno tan feliz por una estrella dorada de premio.'::text),
(380786,42310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rarement ... aussi heureux d''une étoile dorée en récompense.'::text,'un élève a-t-il semblé'::text,'un élève a semblé'::text,'un élève sembla-t-il'::text,'Rarement un élève a-t-il semblé aussi heureux d''une étoile dorée en récompense.'::text),
(380789,42310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nadiren bir öğrenci ödül olarak verilen altın yıldızdan bu kadar mutlu ...'::text,'görünmüştür'::text,'görünmüştür'::text,'göründü'::text,'Nadiren bir öğrenci ödül olarak verilen altın yıldızdan bu kadar mutlu görünmüştür.'::text),
(380790,42310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ritkán ... egy diák ilyen boldognak egy aranycsillag jutalom miatt.'::text,'tűnt'::text,'tűnt'::text,'tűnt'::text,'Ritkán tűnt egy diák ilyen boldognak egy aranycsillag jutalom miatt.'::text),
(380793,42311,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal: Ich hab gehört, sie hat die Lehrerin dazu gebracht, ihr als Belohnung einen Goldstern auf die Seite zu ...'::text,'kleben'::text,'kleben'::text,'kleben'::text,'Rate mal: Ich hab gehört, sie hat die Lehrerin dazu gebracht, ihr als Belohnung einen Goldstern auf die Seite zu kleben.'::text),
(380797,42311,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що: я чула, вона вмовила вчительку ... їй на сторінку золоту зірочку в нагороду.'::text,'наклеїти'::text,'наклеїти'::text,'наклеювання'::text,'Вгадай що: я чула, вона вмовила вчительку наклеїти їй на сторінку золоту зірочку в нагороду.'::text),
(380796,42311,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina qué: oí que consiguió que la profe le ... una estrella dorada en la página como premio.'::text,'pegara'::text,'pegara'::text,'pegando'::text,'Adivina qué: oí que consiguió que la profe le pegara una estrella dorada en la página como premio.'::text),
(380795,42311,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi : j''ai entendu dire qu''elle a réussi à faire ... une étoile dorée sur sa page par la prof en récompense.'::text,'coller'::text,'coller'::text,'collant'::text,'Devine quoi : j''ai entendu dire qu''elle a réussi à faire coller une étoile dorée sur sa page par la prof en récompense.'::text),
(380798,42311,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım: duydum ki öğretmene ödül olarak sayfasına altın yıldız ...'::text,'yapıştırtmış'::text,'yapıştırtmış'::text,'yapıştırtarak'::text,'Bil bakalım: duydum ki öğretmene ödül olarak sayfasına altın yıldız yapıştırtmış.'::text),
(380799,42311,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld: azt hallottam, rávette a tanárnőt, hogy ... egy aranycsillagot az oldalára jutalomként.'::text,'ragasszon'::text,'ragasszon'::text,'ragasztva'::text,'Képzeld: azt hallottam, rávette a tanárnőt, hogy ragasszon egy aranycsillagot az oldalára jutalomként.'::text),
(380802,42312,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir gesagt, sie wünscht sich, ihre Lehrerin ... ihr für jede Seite einen Goldstern als Belohnung.'::text,'gäbe'::text,'gibt'::text,'gibt'::text,'Hör zu, sie hat mir gesagt, sie wünscht sich, ihre Lehrerin gäbe ihr für jede Seite einen Goldstern als Belohnung.'::text),
(380806,42312,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала мені, що хотіла б, щоб учителька ... їй золоту зірочку в нагороду за кожну сторінку.'::text,'давала'::text,'дасть'::text,'дає'::text,'Слухай, вона сказала мені, що хотіла б, щоб учителька давала їй золоту зірочку в нагороду за кожну сторінку.'::text),
(380805,42312,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo que ojalá su profe le ... una estrella dorada de premio por cada página.'::text,'diera'::text,'dará'::text,'da'::text,'Oye, me dijo que ojalá su profe le diera una estrella dorada de premio por cada página.'::text),
(380804,42312,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit qu''elle aimerait que sa prof lui ... une étoile dorée en récompense pour chaque page.'::text,'donne'::text,'donnera'::text,'donne'::text,'Écoute, elle m''a dit qu''elle aimerait que sa prof lui donne une étoile dorée en récompense pour chaque page.'::text),
(380807,42312,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana öğretmeninin her sayfa için ödül olarak altın yıldız ... istediğini söyledi.'::text,'vermesini'::text,'vereceğini'::text,'verdiğini'::text,'Dinle, bana öğretmeninin her sayfa için ödül olarak altın yıldız vermesini istediğini söyledi.'::text),
(380808,42312,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, azt szeretné, ha a tanárnője minden oldalért ... egy aranycsillagot jutalomként.'::text,'adna'::text,'adni fog'::text,'ad'::text,'Figyelj, azt mondta, azt szeretné, ha a tanárnője minden oldalért adna egy aranycsillagot jutalomként.'::text),
(380811,42313,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Belohnung, ... ein einziger Glitzersticker war, hat offensichtlich ihr Leben verändert.'::text,'die'::text,'die'::text,'deren'::text,'Ihre Belohnung, die ein einziger Glitzersticker war, hat offensichtlich ihr Leben verändert.'::text),
(380815,42313,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її нагорода, ... була однією блискучою наліпкою, очевидно, змінила їй життя.'::text,'яка'::text,'що'::text,'чия'::text,'Її нагорода, яка була однією блискучою наліпкою, очевидно, змінила їй життя.'::text),
(380814,42313,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su premio, ... fue una sola pegatina brillante, obviamente le cambió la vida.'::text,'que'::text,'que'::text,'cuyo'::text,'Su premio, que fue una sola pegatina brillante, obviamente le cambió la vida.'::text),
(380813,42313,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa récompense, ... était un seul autocollant pailleté, a évidemment changé sa vie.'::text,'qui'::text,'que'::text,'dont'::text,'Sa récompense, qui était un seul autocollant pailleté, a évidemment changé sa vie.'::text),
(380816,42313,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... tek bir simli çıkartmadan ibaret olan ödülü, belli ki hayatını değiştirdi.'::text,''::text,NULL::text,NULL::text,'Tek bir simli çıkartmadan ibaret olan ödülü, belli ki hayatını değiştirdi.'::text),
(380817,42313,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jutalma, ... egyetlen csillámos matrica volt, nyilván megváltoztatta az életét.'::text,'amely'::text,'ami'::text,'amelynek'::text,'A jutalma, amely egyetlen csillámos matrica volt, nyilván megváltoztatta az életét.'::text),
(380820,42314,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., die sie für eine ganze Seite bekam, war ein einziger Sticker. Ganz klar sehr großzügig.'::text,'Die Belohnung'::text,'Eine Belohnung'::text,'Belohnung'::text,'Die Belohnung, die sie für eine ganze Seite bekam, war ein einziger Sticker. Ganz klar sehr großzügig.'::text),
(380824,42314,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., яку вона отримала за цілу сторінку, була однією наліпкою. Явно дуже щедро.'::text,'Нагорода'::text,'Нагорода'::text,'Нагорода'::text,'Нагорода, яку вона отримала за цілу сторінку, була однією наліпкою. Явно дуже щедро.'::text),
(380823,42314,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... que se ganó por una página entera fue una pegatina. Claramente muy generoso.'::text,'El premio'::text,'Un premio'::text,'Premio'::text,'El premio que se ganó por una página entera fue una pegatina. Claramente muy generoso.'::text),
(380822,42314,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... qu''elle a gagnée pour une page entière était un seul autocollant. Clairement très généreux.'::text,'La récompense'::text,'Une récompense'::text,'Récompense'::text,'La récompense qu''elle a gagnée pour une page entière était un seul autocollant. Clairement très généreux.'::text),
(380825,42314,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir sayfa için kazandığı ... tek bir çıkartmaydı. Belli ki çok cömert.'::text,'ödül'::text,'bir ödül'::text,'ödül'::text,'Tam bir sayfa için kazandığı ödül tek bir çıkartmaydı. Belli ki çok cömert.'::text),
(380826,42314,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'..., amit egy egész oldalért kapott, egyetlen matrica volt. Nyilván nagyon nagyvonalú.'::text,'A jutalom'::text,'Egy jutalom'::text,'Jutalom'::text,'A jutalom, amit egy egész oldalért kapott, egyetlen matrica volt. Nyilván nagyon nagyvonalú.'::text),
(380829,42315,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Mädchen bekam einen Goldstern als Belohnung ... der Tatsache, dass ihre Seite voll war.'::text,'aufgrund'::text,'trotz'::text,'vorausgesetzt'::text,'Das Mädchen bekam einen Goldstern als Belohnung aufgrund der Tatsache, dass ihre Seite voll war.'::text),
(380833,42315,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дівчинка отримала золоту зірочку в нагороду ..., що її сторінка була заповнена.'::text,'завдяки тому'::text,'попри те'::text,'за умови'::text,'Дівчинка отримала золоту зірочку в нагороду завдяки тому, що її сторінка була заповнена.'::text),
(380832,42315,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La chica recibió una estrella dorada como premio ... el hecho de que su página estaba llena.'::text,'debido a'::text,'a pesar de'::text,'siempre que'::text,'La chica recibió una estrella dorada como premio debido a el hecho de que su página estaba llena.'::text),
(380831,42315,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La fille a reçu une étoile dorée en récompense ... que sa page était pleine.'::text,'du fait'::text,'malgré le fait'::text,'pourvu'::text,'La fille a reçu une étoile dorée en récompense du fait que sa page était pleine.'::text),
(380834,42315,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kız, sayfası dolu olduğu ... ödül olarak altın yıldız aldı.'::text,'için'::text,'halde'::text,'takdirde'::text,'Kız, sayfası dolu olduğu için ödül olarak altın yıldız aldı.'::text),
(380835,42315,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A lány aranycsillagot kapott jutalmul ..., hogy tele volt az oldala.'::text,'annak köszönhetően'::text,'annak ellenére'::text,'feltéve'::text,'A lány aranycsillagot kapott jutalmul annak köszönhetően, hogy tele volt az oldala.'::text),
(380838,42316,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie wusste, dass die Lehrerin ihr einen Goldstern als Belohnung ..., ohne Scheiß.'::text,'geben würde'::text,'geben wird'::text,'gibt'::text,'Digga, sie wusste, dass die Lehrerin ihr einen Goldstern als Belohnung geben würde, ohne Scheiß.'::text),
(380842,42316,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона знала, що вчителька ... їй золоту зірочку в нагороду, без жартів.'::text,'дасть'::text,'дасть'::text,'дає'::text,'Бро, вона знала, що вчителька дасть їй золоту зірочку в нагороду, без жартів.'::text),
(380841,42316,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, sabía que la profe le ... una estrella dorada de premio, sin mentir.'::text,'daría'::text,'dará'::text,'está dando'::text,'Bro, sabía que la profe le daría una estrella dorada de premio, sin mentir.'::text),
(380840,42316,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle savait que la prof lui ... une étoile dorée en récompense, sans mentir.'::text,'donnerait'::text,'donnera'::text,'donne'::text,'Frérot, elle savait que la prof lui donnerait une étoile dorée en récompense, sans mentir.'::text),
(380843,42316,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, öğretmenin ona ödül olarak altın yıldız ... biliyordu, yalan yok.'::text,'vereceğini'::text,'vereceğini'::text,'verdiğini'::text,'Kanka, öğretmenin ona ödül olarak altın yıldız vereceğini biliyordu, yalan yok.'::text),
(380844,42316,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, tudta, hogy a tanárnő ... neki egy aranycsillagot jutalmul, komolyan.'::text,'adni fog'::text,'adni fog'::text,'ad'::text,'Tesó, tudta, hogy a tanárnő adni fog neki egy aranycsillagot jutalmul, komolyan.'::text),
(380847,42317,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aktuell ... die Lehrerin einen Goldstern als Belohnung pro 10 Zeilen, im Rahmen des Budgets.'::text,'vergibt'::text,'vergibt'::text,'vergab'::text,'Aktuell vergibt die Lehrerin einen Goldstern als Belohnung pro 10 Zeilen, im Rahmen des Budgets.'::text),
(380851,42317,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наразі вчителька ... золоту зірочку в нагороду за кожні 10 рядків, у межах бюджету.'::text,'роздає'::text,'роздає'::text,'роздала'::text,'Наразі вчителька роздає золоту зірочку в нагороду за кожні 10 рядків, у межах бюджету.'::text),
(380850,42317,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actualmente la profesora ... una estrella dorada de premio por cada 10 líneas, dentro del presupuesto.'::text,'está repartiendo'::text,'reparte'::text,'ha repartido'::text,'Actualmente la profesora está repartiendo una estrella dorada de premio por cada 10 líneas, dentro del presupuesto.'::text),
(380849,42317,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Actuellement, la prof ... une étoile dorée en récompense toutes les 10 lignes, dans le respect du budget.'::text,'distribue'::text,'distribue'::text,'a distribué'::text,'Actuellement, la prof distribue une étoile dorée en récompense toutes les 10 lignes, dans le respect du budget.'::text),
(380852,42317,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda öğretmen her 10 satır için ödül olarak bir altın yıldız ..., bütçe dahilinde.'::text,'dağıtıyor'::text,'dağıtır'::text,'dağıttı'::text,'Şu anda öğretmen her 10 satır için ödül olarak bir altın yıldız dağıtıyor, bütçe dahilinde.'::text),
(380853,42317,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jelenleg a tanárnő 10 soronként ... egy aranycsillagot jutalomként, a kereten belül.'::text,'oszt ki'::text,'kioszt'::text,'kiosztott'::text,'Jelenleg a tanárnő 10 soronként oszt ki egy aranycsillagot jutalomként, a kereten belül.'::text),
(380856,42318,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Goldstern-Belohnung kam, ... das Mädchen schon die ganze Seite gefüllt.'::text,'hatte'::text,'füllte'::text,'hat'::text,'Als die Goldstern-Belohnung kam, hatte das Mädchen schon die ganze Seite gefüllt.'::text),
(380860,42318,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки прийшла нагорода — золота зірочка, дівчинка вже ... всю сторінку.'::text,'заповнила'::text,'заповнила'::text,'заповнила'::text,'Поки прийшла нагорода — золота зірочка, дівчинка вже заповнила всю сторінку.'::text),
(380859,42318,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegó el premio de la estrella dorada, la chica ya ... toda la página.'::text,'había llenado'::text,'llenó'::text,'ha llenado'::text,'Para cuando llegó el premio de la estrella dorada, la chica ya había llenado toda la página.'::text),
(380858,42318,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand la récompense en étoile dorée est arrivée, la fille ... toute la page.'::text,'avait déjà rempli'::text,'remplit'::text,'a déjà rempli'::text,'Quand la récompense en étoile dorée est arrivée, la fille avait déjà rempli toute la page.'::text),
(380861,42318,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Altın yıldız ödülü geldiğinde kız bütün sayfayı çoktan ...'::text,'doldurmuştu'::text,'doldurdu'::text,'doldurdu'::text,'Altın yıldız ödülü geldiğinde kız bütün sayfayı çoktan doldurmuştu.'::text),
(380862,42318,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire megérkezett az aranycsillag jutalom, a lány már ... az egész oldalt.'::text,'teleírta'::text,'teleírta'::text,'teleírta'::text,'Mire megérkezett az aranycsillag jutalom, a lány már teleírta az egész oldalt.'::text),
(347376,38598,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, sie ... dieses Diagramm schon so zwanzig Minuten, und es ist irgendwie Kunst.'::text,'zeichnet'::text,'zeichnet'::text,'zeichnet'::text,'Digga, sie zeichnet dieses Diagramm schon so zwanzig Minuten, und es ist irgendwie Kunst.'::text),
(347380,38598,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, вона ... цю схему вже хвилин двадцять, і це, по ходу, мистецтво.'::text,'малює'::text,'малює'::text,'малює'::text,'Бро, вона малює цю схему вже хвилин двадцять, і це, по ходу, мистецтво.'::text),
(347379,38598,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ella ... ese diagrama como veinte minutos y en plan es arte.'::text,'lleva dibujando'::text,'está dibujando'::text,'dibuja'::text,'Bro, ella lleva dibujando ese diagrama como veinte minutos y en plan es arte.'::text),
(347378,38598,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, elle ... ce schéma depuis genre vingt minutes et c''est carrément de l''art.'::text,'dessine'::text,'dessine'::text,'dessine'::text,'Frérot, elle dessine ce schéma depuis genre vingt minutes et c''est carrément de l''art.'::text),
(347381,38598,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o diyagramı yirmi dakikadır falan ... ve resmen sanat.'::text,'çiziyor'::text,'çiziyor'::text,'çizer'::text,'Kanka, o diyagramı yirmi dakikadır falan çiziyor ve resmen sanat.'::text),
(347382,38598,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, vagy húsz perce ... azt az ábrát, és simán művészet.'::text,'rajzolja'::text,'rajzolja'::text,'rajzolja'::text,'Tesó, vagy húsz perce rajzolja azt az ábrát, és simán művészet.'::text),
(347385,38599,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... sie das ganze Diagramm in 4 Minuten, weit vor der Deadline.'::text,'zeichnete'::text,'zeichnete gerade'::text,'hat gezeichnet'::text,'Gestern zeichnete sie das ganze Diagramm in 4 Minuten, weit vor der Deadline.'::text),
(347389,38599,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора вона ... всю схему за 4 хвилини, задовго до дедлайну.'::text,'намалювала'::text,'малювала'::text,'намалювала'::text,'Учора вона намалювала всю схему за 4 хвилини, задовго до дедлайну.'::text),
(347388,38599,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer ... todo el diagrama en 4 minutos, con mucho margen antes del plazo.'::text,'dibujó'::text,'estaba dibujando'::text,'ha dibujado'::text,'Ayer dibujó todo el diagrama en 4 minutos, con mucho margen antes del plazo.'::text),
(347387,38599,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, elle ... tout le schéma en 4 minutes, bien avant l''échéance.'::text,'a dessiné'::text,'dessinait'::text,'a dessiné'::text,'Hier, elle a dessiné tout le schéma en 4 minutes, bien avant l''échéance.'::text),
(347390,38599,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün bütün diyagramı 4 dakikada ..., teslim tarihinden çok önce.'::text,'çizdi'::text,'çiziyordu'::text,'çizmiştir'::text,'Dün bütün diyagramı 4 dakikada çizdi, teslim tarihinden çok önce.'::text),
(347391,38599,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap 4 perc alatt ... az egész ábrát, jóval a határidő előtt.'::text,'megrajzolta'::text,'rajzolta'::text,'megrajzolta'::text,'Tegnap 4 perc alatt megrajzolta az egész ábrát, jóval a határidő előtt.'::text),
(347394,38600,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... heute ein Diagramm gezeichnet, also ist ein Diagramm an der Tafel.'::text,'hat'::text,'hat'::text,'zeichnet'::text,'Sie hat heute ein Diagramm gezeichnet, also ist ein Diagramm an der Tafel.'::text),
(347398,38600,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вона ... одну схему, тож на дошці одна схема.'::text,'намалювала'::text,'малювала'::text,'малює'::text,'Сьогодні вона намалювала одну схему, тож на дошці одна схема.'::text),
(347397,38600,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoy ... un diagrama, así que hay un diagrama en la pizarra.'::text,'ha dibujado'::text,'ha estado dibujando'::text,'está dibujando'::text,'Hoy ha dibujado un diagrama, así que hay un diagrama en la pizarra.'::text),
(347396,38600,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un schéma aujourd''hui, donc il y a un schéma au tableau.'::text,'a dessiné'::text,'a dessiné'::text,'dessine'::text,'Elle a dessiné un schéma aujourd''hui, donc il y a un schéma au tableau.'::text),
(347399,38600,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bugün bir diyagram ..., yani tahtada bir diyagram var.'::text,'çizdi'::text,'çiziyordu'::text,'çiziyor'::text,'Bugün bir diyagram çizdi, yani tahtada bir diyagram var.'::text),
(347400,38600,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma egy ábrát ..., szóval egy ábra van a táblán.'::text,'rajzolt'::text,'rajzolgatott'::text,'rajzol'::text,'Ma egy ábrát rajzolt, szóval egy ábra van a táblán.'::text),
(347403,38601,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Anfangs war die Tafel leer; am Ende ... die Dozentin ein vollständiges Diagramm gezeichnet.'::text,'hatte'::text,'hat'::text,'zeichnet'::text,'Anfangs war die Tafel leer; am Ende hatte die Dozentin ein vollständiges Diagramm gezeichnet.'::text),
(347407,38601,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спочатку дошка була порожня; наприкінці лекторка вже ... повну схему.'::text,'намалювала'::text,'намалювала'::text,'малює'::text,'Спочатку дошка була порожня; наприкінці лекторка вже намалювала повну схему.'::text),
(347406,38601,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al principio la pizarra estaba vacía; al final, la profesora ... un diagrama completo.'::text,'había dibujado'::text,'ha dibujado'::text,'dibuja'::text,'Al principio la pizarra estaba vacía; al final, la profesora había dibujado un diagrama completo.'::text),
(347405,38601,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au départ, le tableau était vide ; à la fin, la conférencière ... un schéma complet.'::text,'avait dessiné'::text,'a dessiné'::text,'dessine'::text,'Au départ, le tableau était vide ; à la fin, la conférencière avait dessiné un schéma complet.'::text),
(347408,38601,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlangıçta tahta boştu; sonunda öğretim görevlisi eksiksiz bir diyagram ...'::text,'çizmişti'::text,'çizdi'::text,'çiziyor'::text,'Başlangıçta tahta boştu; sonunda öğretim görevlisi eksiksiz bir diyagram çizmişti.'::text),
(347409,38601,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kezdetben a tábla üres volt; a végére az előadó ... egy teljes ábrát.'::text,'megrajzolt'::text,'megrajzolt'::text,'rajzol'::text,'Kezdetben a tábla üres volt; a végére az előadó megrajzolt egy teljes ábrát.'::text),
(347412,38602,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du noch so ein Diagramm zeichnest, ... der ganze Saal wieder. Respekt.'::text,'klatscht'::text,'klatschte'::text,'klatschte'::text,'Wenn du noch so ein Diagramm zeichnest, klatscht der ganze Saal wieder. Respekt.'::text),
(347416,38602,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо ти намалюєш ще одну таку схему, уся зала знову ... Респект.'::text,'аплодуватиме'::text,'аплодувала б'::text,'аплодувала'::text,'Якщо ти намалюєш ще одну таку схему, уся зала знову аплодуватиме Респект.'::text),
(347415,38602,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si dibujas otro diagrama así, toda la sala ... otra vez. Respeto.'::text,'aplaudirá'::text,'aplaudiría'::text,'aplaudió'::text,'Si dibujas otro diagrama así, toda la sala aplaudirá otra vez. Respeto.'::text),
(347414,38602,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu dessines un autre schéma comme ça, toute la salle ... encore. Respect.'::text,'applaudira'::text,'applaudirait'::text,'a applaudi'::text,'Si tu dessines un autre schéma comme ça, toute la salle applaudira encore. Respect.'::text),
(347417,38602,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Böyle bir diyagram daha çizersen bütün salon yine ... Saygı.'::text,'alkışlayacak'::text,'alkışlardı'::text,'alkışladı'::text,'Böyle bir diyagram daha çizersen bütün salon yine alkışlayacak Saygı.'::text),
(347418,38602,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha rajzolsz még egy ilyen ábrát, az egész terem újra ... Respekt.'::text,'tapsolni fog'::text,'tapsolna'::text,'tapsolt'::text,'Ha rajzolsz még egy ilyen ábrát, az egész terem újra tapsolni fog Respekt.'::text),
(347421,38603,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ich so ein Diagramm zeichnen könnte wie du, ... ich auch Physik unterrichten, ganz ehrlich.'::text,'würde'::text,'werde'::text,'werde'::text,'Wenn ich so ein Diagramm zeichnen könnte wie du, würde ich auch Physik unterrichten, ganz ehrlich.'::text),
(347425,38603,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби я вмів малювати схему, як ти, я теж ... фізику, чесно.'::text,'викладав би'::text,'викладатиму'::text,'викладаю'::text,'Якби я вмів малювати схему, як ти, я теж викладав би фізику, чесно.'::text),
(347424,38603,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si supiera dibujar un diagrama como tú, yo también ... física, no te voy a mentir.'::text,'enseñaría'::text,'enseñaré'::text,'enseño'::text,'Si supiera dibujar un diagrama como tú, yo también enseñaría física, no te voy a mentir.'::text),
(347423,38603,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si je savais dessiner un schéma comme toi, moi aussi, je ... la physique, sans mentir.'::text,'enseignerais'::text,'enseignerai'::text,'enseigne'::text,'Si je savais dessiner un schéma comme toi, moi aussi, je enseignerais la physique, sans mentir.'::text),
(347426,38603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senin gibi diyagram çizebilseydim ben de fizik ..., yalan yok.'::text,'öğretirdim'::text,'öğreteceğim'::text,'öğretiyorum'::text,'Senin gibi diyagram çizebilseydim ben de fizik öğretirdim, yalan yok.'::text),
(347427,38603,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha úgy tudnék ábrát rajzolni, mint te, én is fizikát ..., nem hazudok.'::text,'tanítanék'::text,'fogok tanítani'::text,'tanítok'::text,'Ha úgy tudnék ábrát rajzolni, mint te, én is fizikát tanítanék, nem hazudok.'::text),
(347430,38604,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Diagramm ... mit weißer Kreide an die grüne Tafel gezeichnet.'::text,'wurde'::text,'zeichnet'::text,'zeichnete'::text,'Das Diagramm wurde mit weißer Kreide an die grüne Tafel gezeichnet.'::text),
(347434,38604,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Схему ... на зеленій дошці білою крейдою.'::text,'намалювали'::text,'малює'::text,'намалювала'::text,'Схему намалювали на зеленій дошці білою крейдою.'::text),
(347433,38604,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El diagrama ... en la pizarra verde con tiza blanca.'::text,'fue dibujado'::text,'está dibujando'::text,'dibujó'::text,'El diagrama fue dibujado en la pizarra verde con tiza blanca.'::text),
(347432,38604,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le schéma ... sur le tableau vert à la craie blanche.'::text,'a été dessiné'::text,'dessine'::text,'a dessiné'::text,'Le schéma a été dessiné sur le tableau vert à la craie blanche.'::text),
(347435,38604,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Diyagram yeşil tahtaya beyaz tebeşirle ...'::text,'çizildi'::text,'çiziyor'::text,'çizdi'::text,'Diyagram yeşil tahtaya beyaz tebeşirle çizildi.'::text),
(347436,38604,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ábrát fehér krétával ... a zöld táblára.'::text,'rajzolták'::text,'rajzolja'::text,'rajzolta'::text,'Az ábrát fehér krétával rajzolták a zöld táblára.'::text),
(347439,38605,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ganze Publikum ... das Diagramm aufmerksam. Offensichtlich total fesselnd.'::text,'studierte'::text,'wurde studiert'::text,'studierend'::text,'Das ganze Publikum studierte das Diagramm aufmerksam. Offensichtlich total fesselnd.'::text),
(347443,38605,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уся аудиторія уважно ... схему. Явно захопливі речі.'::text,'вивчала'::text,'була вивчена'::text,'вивчаючи'::text,'Уся аудиторія уважно вивчала схему. Явно захопливі речі.'::text),
(347442,38605,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo el público ... el diagrama con atención. Claramente algo apasionante.'::text,'estudió'::text,'fue estudiado'::text,'estudiando'::text,'Todo el público estudió el diagrama con atención. Claramente algo apasionante.'::text),
(347441,38605,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le public ... le schéma attentivement. Clairement passionnant.'::text,'a étudié'::text,'a été étudié'::text,'étudiant'::text,'Tout le public a étudié le schéma attentivement. Clairement passionnant.'::text),
(347444,38605,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün seyirciler diyagramı dikkatle ... Belli ki çok sürükleyici şeyler.'::text,'inceledi'::text,'incelendi'::text,'inceleyerek'::text,'Bütün seyirciler diyagramı dikkatle inceledi Belli ki çok sürükleyici şeyler.'::text),
(347445,38605,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az egész közönség figyelmesen ... az ábrát. Nyilván lebilincselő cucc.'::text,'tanulmányozta'::text,'tanulmányozva lett'::text,'tanulmányozva'::text,'Az egész közönség figyelmesen tanulmányozta az ábrát. Nyilván lebilincselő cucc.'::text),
(347457,38607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Diagramm, ... sie gezeichnet hat, hat einen Kreis und beschriftete Pfeile.'::text,'das'::text,'wer'::text,'dessen'::text,'Das Diagramm, das sie gezeichnet hat, hat einen Kreis und beschriftete Pfeile.'::text),
(347461,38607,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Схема, ... вона намалювала, має коло й підписані стрілки.'::text,'яку'::text,'хто'::text,'чию'::text,'Схема, яку вона намалювала, має коло й підписані стрілки.'::text),
(347460,38607,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El diagrama ... dibujó tiene un círculo y flechas con etiquetas.'::text,'que'::text,'quien'::text,'cuyo'::text,'El diagrama que dibujó tiene un círculo y flechas con etiquetas.'::text),
(347459,38607,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le schéma ... a dessiné a un cercle et des flèches légendées.'::text,'qu''elle'::text,'qui elle'::text,'dont elle'::text,'Le schéma qu''elle a dessiné a un cercle et des flèches légendées.'::text),
(347462,38607,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... çizdiği diyagramda bir daire ve etiketli oklar var.'::text,''::text,NULL::text,NULL::text,'Çizdiği diyagramda bir daire ve etiketli oklar var.'::text),
(347463,38607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ábra, ... rajzolt, egy kört és feliratos nyilakat tartalmaz.'::text,'amelyet'::text,'aki'::text,'amelynek'::text,'Az ábra, amelyet rajzolt, egy kört és feliratos nyilakat tartalmaz.'::text),
(391935,43549,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... das Taxi den ganzen Tag durch den Verkehr, also fährt sie den ganzen Tag.'::text,'lenkt'::text,'lenkt'::text,'lenkt'::text,'Sie lenkt das Taxi den ganzen Tag durch den Verkehr, also fährt sie den ganzen Tag.'::text),
(391939,43549,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... таксі крізь затори весь день, тож весь день кермує.'::text,'веде'::text,'веде'::text,'веде'::text,'Вона веде таксі крізь затори весь день, тож весь день кермує.'::text),
(391938,43549,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... el taxi entre el tráfico todo el día, así que lleva todo el día conduciendo.'::text,'ha estado guiando'::text,'está guiando'::text,'guía'::text,'Ella ha estado guiando el taxi entre el tráfico todo el día, así que lleva todo el día conduciendo.'::text),
(391937,43549,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... le taxi dans la circulation toute la journée, donc elle conduit toute la journée.'::text,'dirige'::text,'dirige'::text,'dirige'::text,'Elle dirige le taxi dans la circulation toute la journée, donc elle conduit toute la journée.'::text),
(391940,43549,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün gün taksiyi trafikte ..., yani bütün gün araba kullanıyor.'::text,'sürüyor'::text,'sürüyor'::text,'sürer'::text,'Bütün gün taksiyi trafikte sürüyor, yani bütün gün araba kullanıyor.'::text),
(391941,43549,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egész nap ... a taxit a forgalomban, szóval egész nap vezet.'::text,'kormányozza'::text,'kormányozza'::text,'kormányozza'::text,'Egész nap kormányozza a taxit a forgalomban, szóval egész nap vezet.'::text),
(391944,43550,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wie dokumentiert, ... die Person das Taxi durch den Verkehr, als die Sonne tief sank.'::text,'lenkte gerade'::text,'lenkte'::text,'hat gelenkt'::text,'Wie dokumentiert, lenkte gerade die Person das Taxi durch den Verkehr, als die Sonne tief sank.'::text),
(391948,43550,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Як задокументовано, досліджувана ... таксі крізь потік, коли сонце опустилося низько.'::text,'вела'::text,'повела'::text,'повела'::text,'Як задокументовано, досліджувана вела таксі крізь потік, коли сонце опустилося низько.'::text),
(391947,43550,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Según lo documentado, el sujeto ... el taxi entre el tráfico cuando el sol bajó.'::text,'estaba guiando'::text,'guió'::text,'ha guiado'::text,'Según lo documentado, el sujeto estaba guiando el taxi entre el tráfico cuando el sol bajó.'::text),
(391946,43550,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Comme documenté, le sujet ... le taxi dans la circulation quand le soleil est descendu bas.'::text,'dirigeait'::text,'dirigea'::text,'a dirigé'::text,'Comme documenté, le sujet dirigeait le taxi dans la circulation quand le soleil est descendu bas.'::text),
(391949,43550,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belgelendiği üzere, güneş alçaldığında denek taksiyi trafikte ...'::text,'sürüyordu'::text,'sürdü'::text,'sürmüştür'::text,'Belgelendiği üzere, güneş alçaldığında denek taksiyi trafikte sürüyordu.'::text),
(391950,43550,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahogy dokumentálva van, az alany ... a taxit a forgalomban, amikor a nap alacsonyra süllyedt.'::text,'kormányozta éppen'::text,'kormányozta'::text,'kormányozta'::text,'Ahogy dokumentálva van, az alany kormányozta éppen a taxit a forgalomban, amikor a nap alacsonyra süllyedt.'::text),
(391953,43551,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lowkey beeindruckt: Du ... den ganzen Nachmittag wie ein Profi durch diesen Verkehr.'::text,'manövrierst'::text,'manövriertest'::text,'manövrierst'::text,'Lowkey beeindruckt: Du manövrierst den ganzen Nachmittag wie ein Profi durch diesen Verkehr.'::text),
(391957,43551,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Трохи вражений: ти ... крізь цей потік як профі все пообіддя.'::text,'маневруєш'::text,'маневрувала'::text,'маневруєш'::text,'Трохи вражений: ти маневруєш крізь цей потік як профі все пообіддя.'::text),
(391956,43551,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me tienes un poco impresionado: ... toda la tarde entre este tráfico como una pro.'::text,'llevas maniobrando'::text,'maniobraste'::text,'estás maniobrando'::text,'Me tienes un poco impresionado: llevas maniobrando toda la tarde entre este tráfico como una pro.'::text),
(391955,43551,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un peu impressionné : tu ... dans cette circulation comme une pro tout l''après-midi.'::text,'manœuvres'::text,'as manœuvré'::text,'manœuvres'::text,'Un peu impressionné : tu manœuvres dans cette circulation comme une pro tout l''après-midi.'::text),
(391958,43551,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası etkilendim: bütün öğleden sonra bu trafikte profesyonel gibi ...'::text,'manevra yapıyorsun'::text,'manevra yaptın'::text,'manevra yapıyorsun'::text,'Açıkçası etkilendim: bütün öğleden sonra bu trafikte profesyonel gibi manevra yapıyorsun.'::text),
(391959,43551,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Titokban lenyűgözve: egész délután úgy ... ebben a forgalomban, mint egy profi.'::text,'manőverezel'::text,'manővereztél'::text,'manőverezel'::text,'Titokban lenyűgözve: egész délután úgy manőverezel ebben a forgalomban, mint egy profi.'::text),
(391962,43552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, als du deine Mütze gelüftet hast, ... du das Taxi schon durch die halbe Stadt gelenkt.'::text,'hattest'::text,'hast'::text,'lenkst'::text,'Ehrlich gesagt, als du deine Mütze gelüftet hast, hattest du das Taxi schon durch die halbe Stadt gelenkt.'::text),
(391966,43552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, поки ти торкнулася кашкета, ти вже ... те таксі через пів міста.'::text,'провела'::text,'провела'::text,'ведеш'::text,'Не буду брехати, поки ти торкнулася кашкета, ти вже провела те таксі через пів міста.'::text),
(391965,43552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No voy a mentir, para cuando te tocaste la gorra, ya ... ese taxi por media ciudad.'::text,'habías llevado'::text,'has llevado'::text,'llevas'::text,'No voy a mentir, para cuando te tocaste la gorra, ya habías llevado ese taxi por media ciudad.'::text),
(391964,43552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, quand tu as touché ta casquette, tu ... ce taxi à travers la moitié de la ville.'::text,'avais déjà conduit'::text,'as déjà conduit'::text,'conduis'::text,'Je vais pas mentir, quand tu as touché ta casquette, tu avais déjà conduit ce taxi à travers la moitié de la ville.'::text),
(391967,43552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, kasketine dokunduğunda o taksiyi şehrin yarısında çoktan ...'::text,'sürmüştün'::text,'sürdün'::text,'sürüyorsun'::text,'Yalan yok, kasketine dokunduğunda o taksiyi şehrin yarısında çoktan sürmüştün.'::text),
(391968,43552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, mire megbillentetted a sapkádat, már ... azt a taxit a fél városon.'::text,'átkormányoztad'::text,'átkormányoztad'::text,'kormányozod'::text,'Nem hazudok, mire megbillentetted a sapkádat, már átkormányoztad azt a taxit a fél városon.'::text),
(391971,43553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn du morgen so lenkst, ... du die entspannteste Fahrerin der Stadt, ehrlich.'::text,'bist'::text,'wärst'::text,'warst'::text,'Wenn du morgen so lenkst, bist du die entspannteste Fahrerin der Stadt, ehrlich.'::text),
(391975,43553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо завтра ти так кермуватимеш, ти ... найплавнішою водійкою в місті, чесно.'::text,'будеш'::text,'була б'::text,'була'::text,'Якщо завтра ти так кермуватимеш, ти будеш найплавнішою водійкою в місті, чесно.'::text),
(391974,43553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si mañana conduces así, ... la conductora más suave de la ciudad, en serio.'::text,'serás'::text,'serías'::text,'eras'::text,'Si mañana conduces así, serás la conductora más suave de la ciudad, en serio.'::text),
(391973,43553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si tu conduis comme ça demain, tu ... la conductrice la plus fluide de la ville, franchement.'::text,'seras'::text,'serais'::text,'étais'::text,'Si tu conduis comme ça demain, tu seras la conductrice la plus fluide de la ville, franchement.'::text),
(391976,43553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın böyle sürersen şehrin en yumuşak şoförü ..., cidden.'::text,'olacaksın'::text,'olurdun'::text,'oldun'::text,'Yarın böyle sürersen şehrin en yumuşak şoförü olacaksın, cidden.'::text),
(391977,43553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha holnap így vezetsz, a város legsimább sofőrje ..., őszintén.'::text,'leszel'::text,'lennél'::text,'voltál'::text,'Ha holnap így vezetsz, a város legsimább sofőrje leszel, őszintén.'::text),
(391980,43554,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Natürlich, wenn sie mit beiden Händen ..., würde sich die Fahrt viel weniger aufregend anfühlen.'::text,'lenkte'::text,'lenkt'::text,'lenken würde'::text,'Natürlich, wenn sie mit beiden Händen lenkte, würde sich die Fahrt viel weniger aufregend anfühlen.'::text),
(391984,43554,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, якби вона ... обома руками, поїздка була б набагато менш захопливою.'::text,'кермувала'::text,'кермує'::text,'кермувала б'::text,'Звісно, якби вона кермувала обома руками, поїздка була б набагато менш захопливою.'::text),
(391983,43554,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claro, si ... con las dos manos, el viaje sería mucho menos emocionante.'::text,'condujera'::text,'conduce'::text,'conduciría'::text,'Claro, si condujera con las dos manos, el viaje sería mucho menos emocionante.'::text),
(391982,43554,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bien sûr, si elle ... à deux mains, la course serait bien moins excitante.'::text,'conduisait'::text,'conduit'::text,'conduirait'::text,'Bien sûr, si elle conduisait à deux mains, la course serait bien moins excitante.'::text),
(391985,43554,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki iki eliyle ..., yolculuk çok daha az heyecanlı olurdu.'::text,'sürseydi'::text,'sürüyor'::text,'sürerdi'::text,'Tabii ki iki eliyle sürseydi, yolculuk çok daha az heyecanlı olurdu.'::text),
(391986,43554,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Persze, ha két kézzel ..., az út sokkal kevésbé lenne izgalmas.'::text,'kormányozna'::text,'kormányoz'::text,'kormányozna'::text,'Persze, ha két kézzel kormányozna, az út sokkal kevésbé lenne izgalmas.'::text),
(391998,43556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die junge Fahrerin ... das Taxi durch den Abendverkehr.'::text,'lenkte'::text,'wurde gelenkt'::text,'lenkend'::text,'Die junge Fahrerin lenkte das Taxi durch den Abendverkehr.'::text),
(392002,43556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молода водійка ... таксі крізь вечірній потік.'::text,'вела'::text,'була ведена'::text,'ведучи'::text,'Молода водійка вела таксі крізь вечірній потік.'::text),
(392001,43556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La joven conductora ... el taxi entre el tráfico de la tarde.'::text,'guió'::text,'fue guiada'::text,'guiando'::text,'La joven conductora guió el taxi entre el tráfico de la tarde.'::text),
(392000,43556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La jeune conductrice ... le taxi dans la circulation du soir.'::text,'a conduit'::text,'a été conduite'::text,'conduisant'::text,'La jeune conductrice a conduit le taxi dans la circulation du soir.'::text),
(392003,43556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç şoför taksiyi akşam trafiğinde ...'::text,'sürdü'::text,'sürüldü'::text,'sürerek'::text,'Genç şoför taksiyi akşam trafiğinde sürdü.'::text),
(392004,43556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatal sofőr ... a taxit az esti forgalomban.'::text,'kormányozta'::text,'kormányozva volt'::text,'kormányozva'::text,'A fiatal sofőr kormányozta a taxit az esti forgalomban.'::text),
(392007,43557,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lenkt so ruhig, sie ... eine erfahrene Fahrerin sein.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Sie lenkt so ruhig, sie muss eine erfahrene Fahrerin sein.'::text),
(392011,43557,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона кермує так спокійно, що ... бути досвідченою водійкою.'::text,'мусить'::text,'не може'::text,'мала б'::text,'Вона кермує так спокійно, що мусить бути досвідченою водійкою.'::text),
(392010,43557,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Conduce con tanta calma que ... ser una conductora experimentada.'::text,'debe de'::text,'no puede'::text,'debería'::text,'Conduce con tanta calma que debe de ser una conductora experimentada.'::text),
(392009,43557,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle conduit si calmement qu''elle ... être une conductrice expérimentée.'::text,'doit'::text,'ne peut pas'::text,'devrait'::text,'Elle conduit si calmement qu''elle doit être une conductrice expérimentée.'::text),
(392012,43557,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O kadar sakin sürüyor ki deneyimli bir şoför ...'::text,'olmalı'::text,'olamaz'::text,'olması gerek'::text,'O kadar sakin sürüyor ki deneyimli bir şoför olmalı.'::text),
(392013,43557,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olyan nyugodtan vezet, hogy ... tapasztalt sofőr.'::text,'biztos'::text,'nem lehet'::text,'kellene legyen'::text,'Olyan nyugodtan vezet, hogy biztos tapasztalt sofőr.'::text),
(392016,43558,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau, ... das gelbe Taxi lenkt, trägt eine Schiebermütze.'::text,'die'::text,'die'::text,'deren'::text,'Die Frau, die das gelbe Taxi lenkt, trägt eine Schiebermütze.'::text),
(392020,43558,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка, ... кермує жовтим таксі, носить кашкет-восьмиклинку.'::text,'яка'::text,'котра'::text,'чия'::text,'Жінка, яка кермує жовтим таксі, носить кашкет-восьмиклинку.'::text),
(392019,43558,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer ... conduce el taxi amarillo lleva una gorra plana.'::text,'que'::text,'la cual'::text,'cuya'::text,'La mujer que conduce el taxi amarillo lleva una gorra plana.'::text),
(392018,43558,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ... conduit le taxi jaune porte une casquette plate.'::text,'qui'::text,'que'::text,'dont'::text,'La femme qui conduit le taxi jaune porte une casquette plate.'::text),
(392021,43558,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... sarı taksiyi süren kadın kasket takıyor.'::text,''::text,NULL::text,NULL::text,'Sarı taksiyi süren kadın kasket takıyor.'::text),
(392022,43558,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a nő, ... a sárga taxit vezeti, simlis sapkát visel.'::text,'aki'::text,'amely'::text,'akinek'::text,'Az a nő, aki a sárga taxit vezeti, simlis sapkát visel.'::text),
(392025,43559,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fahrerin sagte ihrem Manager, dass sie das Taxi vor der Deadline noch durch 12 Straßen ...'::text,'lenken würde'::text,'lenken wird'::text,'lenkt'::text,'Die Fahrerin sagte ihrem Manager, dass sie das Taxi vor der Deadline noch durch 12 Straßen lenken würde.'::text),
(392029,43559,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Водійка сказала менеджеру, що ... таксі ще через 12 вулиць до дедлайну.'::text,'проведе'::text,'проведе'::text,'веде'::text,'Водійка сказала менеджеру, що проведе таксі ще через 12 вулиць до дедлайну.'::text),
(392028,43559,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La conductora le dijo a su jefe que ... el taxi por 12 calles más antes del plazo.'::text,'llevaría'::text,'llevará'::text,'lleva'::text,'La conductora le dijo a su jefe que llevaría el taxi por 12 calles más antes del plazo.'::text),
(392027,43559,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La conductrice a dit à son manager qu''elle ... le taxi dans 12 rues de plus avant l''échéance.'::text,'conduirait'::text,'conduira'::text,'conduit'::text,'La conductrice a dit à son manager qu''elle conduirait le taxi dans 12 rues de plus avant l''échéance.'::text),
(392030,43559,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şoför yöneticisine taksiyi teslim tarihinden önce 12 sokak daha ... söyledi.'::text,'süreceğini'::text,'süreceğini'::text,'sürdüğünü'::text,'Şoför yöneticisine taksiyi teslim tarihinden önce 12 sokak daha süreceğini söyledi.'::text),
(392031,43559,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A sofőr azt mondta a menedzserének, hogy a határidő előtt még 12 utcán ... végig a taxit.'::text,'viszi'::text,'fogja vinni'::text,'viszi'::text,'A sofőr azt mondta a menedzserének, hogy a határidő előtt még 12 utcán viszi végig a taxit.'::text),
(359670,39964,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sie ihr Headset aufsetzte, ... sie jeden Schalter schon zweimal umgelegt. Eindeutig entspannt.'::text,'hatte'::text,'hat'::text,'legt'::text,'Als sie ihr Headset aufsetzte, hatte sie jeden Schalter schon zweimal umgelegt. Eindeutig entspannt.'::text),
(359674,39964,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки вона одягла гарнітуру, вона ... кожен перемикач двічі. Явно розслаблена.'::text,'уже перемкнула'::text,'перемкнула'::text,'перемикає'::text,'Поки вона одягла гарнітуру, вона уже перемкнула кожен перемикач двічі. Явно розслаблена.'::text),
(359673,39964,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando se puso el casco, ya ... cada interruptor dos veces. Claramente relajada.'::text,'había accionado'::text,'ha accionado'::text,'acciona'::text,'Para cuando se puso el casco, ya había accionado cada interruptor dos veces. Claramente relajada.'::text),
(359672,39964,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand elle a mis son casque, elle ... chaque interrupteur deux fois. Clairement détendue.'::text,'avait déjà actionné'::text,'a déjà actionné'::text,'actionne'::text,'Quand elle a mis son casque, elle avait déjà actionné chaque interrupteur deux fois. Clairement détendue.'::text),
(359675,39964,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlığını taktığında her anahtarı iki kez ... Belli ki rahat.'::text,'çevirmişti'::text,'çevirdi'::text,'çeviriyor'::text,'Başlığını taktığında her anahtarı iki kez çevirmişti Belli ki rahat.'::text),
(359676,39964,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire feltette a headsetjét, már ... minden kapcsolót kétszer. Nyilvánvalóan laza.'::text,'átkapcsolta'::text,'átkapcsolta'::text,'átkapcsolja'::text,'Mire feltette a headsetjét, már átkapcsolta minden kapcsolót kétszer. Nyilvánvalóan laza.'::text),
(359679,39965,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ihr Headset ausfällt, ... sie den Tower mit Handzeichen. Offensichtlich ein toller Plan.'::text,'ruft'::text,'riefe'::text,'rief'::text,'Wenn ihr Headset ausfällt, ruft sie den Tower mit Handzeichen. Offensichtlich ein toller Plan.'::text),
(359683,39965,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо її гарнітура перестане працювати, вона ... вежу жестами. Очевидно, чудовий план.'::text,'викличе'::text,'викликала б'::text,'викликала'::text,'Якщо її гарнітура перестане працювати, вона викличе вежу жестами. Очевидно, чудовий план.'::text),
(359682,39965,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si su casco deja de funcionar, ... a la torre con señas. Obviamente, un gran plan.'::text,'llamará'::text,'llamaría'::text,'llamó'::text,'Si su casco deja de funcionar, llamará a la torre con señas. Obviamente, un gran plan.'::text),
(359681,39965,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si son casque tombe en panne, elle ... la tour avec des signes de la main. Évidemment un super plan.'::text,'appellera'::text,'appellerait'::text,'a appelé'::text,'Si son casque tombe en panne, elle appellera la tour avec des signes de la main. Évidemment un super plan.'::text),
(359684,39965,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlığı çalışmayı bırakırsa kuleyi el işaretleriyle ... Belli ki harika bir plan.'::text,'arayacak'::text,'arardı'::text,'aradı'::text,'Başlığı çalışmayı bırakırsa kuleyi el işaretleriyle arayacak Belli ki harika bir plan.'::text),
(359685,39965,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a headsetje felmondja a szolgálatot, kézjelekkel ... a tornyot. Nyilván remek terv.'::text,'hívja'::text,'hívná'::text,'hívta'::text,'Ha a headsetje felmondja a szolgálatot, kézjelekkel hívja a tornyot. Nyilván remek terv.'::text),
(359688,39966,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie das Headset nicht trüge, ... sie kein Wort vom Tower. Makellose Idee.'::text,'hörte'::text,'hört'::text,'hört'::text,'Wenn sie das Headset nicht trüge, hörte sie kein Wort vom Tower. Makellose Idee.'::text),
(359692,39966,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби вона не носила гарнітуру, вона ... жодного слова з вежі. Бездоганна ідея.'::text,'не чула б'::text,'не чутиме'::text,'не чує'::text,'Якби вона не носила гарнітуру, вона не чула б жодного слова з вежі. Бездоганна ідея.'::text),
(359691,39966,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no llevara el casco, ... ni una palabra de la torre. Idea impecable.'::text,'no oiría'::text,'no oirá'::text,'no oye'::text,'Si no llevara el casco, no oiría ni una palabra de la torre. Idea impecable.'::text),
(359690,39966,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle ne portait pas le casque, elle ... pas un mot de la tour. Idée impeccable.'::text,'n''entendrait'::text,'n''entendra'::text,'n''entend'::text,'Si elle ne portait pas le casque, elle n''entendrait pas un mot de la tour. Idée impeccable.'::text),
(359693,39966,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlığı takmasaydı kuleden tek kelime ... Kusursuz fikir.'::text,'duymazdı'::text,'duymayacak'::text,'duymuyor'::text,'Başlığı takmasaydı kuleden tek kelime duymazdı Kusursuz fikir.'::text),
(359694,39966,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem viselné a headsetet, egy szót sem ... a toronyból. Hibátlan ötlet.'::text,'hallana'::text,'fog hallani'::text,'hall'::text,'Ha nem viselné a headsetet, egy szót sem hallana a toronyból. Hibátlan ötlet.'::text),
(359697,39967,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Headset ... im Terminal vergessen, und der ganze Flug war fast ruiniert!'::text,'wurde'::text,'vergaß'::text,'wird'::text,'Das Headset wurde im Terminal vergessen, und der ganze Flug war fast ruiniert!'::text),
(359701,39967,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гарнітуру ... в терміналі, і весь рейс мало не зірвався!'::text,'забули'::text,'забула'::text,'забувають'::text,'Гарнітуру забули в терміналі, і весь рейс мало не зірвався!'::text),
(359700,39967,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El casco ... en la terminal y todo el vuelo casi se arruina!'::text,'fue olvidado'::text,'olvidó'::text,'es olvidado'::text,'¡El casco fue olvidado en la terminal y todo el vuelo casi se arruina!'::text),
(359699,39967,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le casque ... dans le terminal, et tout le vol a failli être gâché !'::text,'a été oublié'::text,'a oublié'::text,'est oublié'::text,'Le casque a été oublié dans le terminal, et tout le vol a failli être gâché !'::text),
(359702,39967,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlık terminalde ... ve bütün uçuş neredeyse mahvoluyordu!'::text,'unutuldu'::text,'unuttu'::text,'unutuluyor'::text,'Başlık terminalde unutuldu ve bütün uçuş neredeyse mahvoluyordu!'::text),
(359703,39967,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A headsetet ... a terminálban, és majdnem tönkrement az egész repülés!'::text,'elfelejtették'::text,'elfelejtette'::text,'elfelejtik'::text,'A headsetet elfelejtették a terminálban, és majdnem tönkrement az egész repülés!'::text),
(359706,39968,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pilotin ... sich vor dem Start das grüne Headset über die Ohren.'::text,'zog'::text,'wurde gezogen'::text,'ziehend'::text,'Die Pilotin zog sich vor dem Start das grüne Headset über die Ohren.'::text),
(359710,39968,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пілотка перед зльотом ... зелену гарнітуру на вуха.'::text,'натягнула'::text,'була натягнута'::text,'натягуючи'::text,'Пілотка перед зльотом натягнула зелену гарнітуру на вуха.'::text),
(359709,39968,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La piloto ... el casco verde sobre las orejas antes del despegue.'::text,'se puso'::text,'fue puesta'::text,'poniéndose'::text,'La piloto se puso el casco verde sobre las orejas antes del despegue.'::text),
(359708,39968,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pilote ... le casque vert sur ses oreilles avant le décollage.'::text,'a mis'::text,'a été mise'::text,'mettant'::text,'La pilote a mis le casque vert sur ses oreilles avant le décollage.'::text),
(359711,39968,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pilot kalkıştan önce yeşil başlığı kulaklarına ...'::text,'geçirdi'::text,'geçirildi'::text,'geçirerek'::text,'Pilot kalkıştan önce yeşil başlığı kulaklarına geçirdi.'::text),
(359712,39968,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pilóta felszállás előtt a fülére ... a zöld headsetet.'::text,'húzta'::text,'rá lett húzva'::text,'húzva'::text,'A pilóta felszállás előtt a fülére húzta a zöld headsetet.'::text),
(359715,39969,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie lächelt mit ihrem Headset, also ... mit dem Flug zufrieden sein.'::text,'muss sie'::text,'kann sie nicht'::text,'darf sie nicht'::text,'Sie lächelt mit ihrem Headset, also muss sie mit dem Flug zufrieden sein.'::text),
(359719,39969,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона усміхається в гарнітурі, тож ... бути задоволеною польотом.'::text,'мусить'::text,'не може'::text,'не повинна'::text,'Вона усміхається в гарнітурі, тож мусить бути задоволеною польотом.'::text),
(359718,39969,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonríe con el casco puesto, así que ... estar contenta con el vuelo.'::text,'debe de'::text,'no puede'::text,'no debe'::text,'Sonríe con el casco puesto, así que debe de estar contenta con el vuelo.'::text),
(359717,39969,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle sourit avec son casque, donc elle ... être contente du vol.'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'Elle sourit avec son casque, donc elle doit être contente du vol.'::text),
(359720,39969,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başlığıyla gülümsüyor, yani uçuştan memnun ...'::text,'olmalı'::text,'olamaz'::text,'olmamalı'::text,'Başlığıyla gülümsüyor, yani uçuştan memnun olmalı.'::text),
(359721,39969,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mosolyog a headsetjében, szóval ... elégedett a repüléssel.'::text,'biztos'::text,'nem lehet'::text,'nem szabad'::text,'Mosolyog a headsetjében, szóval biztos elégedett a repüléssel.'::text),
(359724,39970,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Headset, ... sie im Cockpit trägt, ist grün.'::text,'das'::text,'wer'::text,'was'::text,'Das Headset, das sie im Cockpit trägt, ist grün.'::text),
(359728,39970,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гарнітура, ... вона носить у кабіні, зелена.'::text,'яку'::text,'хто'::text,'що'::text,'Гарнітура, яку вона носить у кабіні, зелена.'::text),
(359727,39970,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El casco ... lleva en la cabina es verde.'::text,'que'::text,'quien'::text,'lo que'::text,'El casco que lleva en la cabina es verde.'::text),
(359726,39970,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le casque ... porte dans le cockpit est vert.'::text,'qu''elle'::text,'qui elle'::text,'ce qu''elle'::text,'Le casque qu''elle porte dans le cockpit est vert.'::text),
(359729,39970,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kokpitte taktığı başlık yeşil.'::text,''::text,NULL::text,NULL::text,'Kokpitte taktığı başlık yeşil.'::text),
(359730,39970,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A headset, ... a pilótafülkében visel, zöld.'::text,'amelyet'::text,'aki'::text,'amit'::text,'A headset, amelyet a pilótafülkében visel, zöld.'::text),
(359733,39971,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Pilotin gab an, dass das Headset während des Starts einwandfrei ...'::text,'funktioniert habe'::text,'funktioniert hat'::text,'funktioniert'::text,'Die Pilotin gab an, dass das Headset während des Starts einwandfrei funktioniert habe.'::text),
(359737,39971,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пілотка зазначила, що гарнітура під час зльоту ... бездоганно.'::text,'працювала'::text,'працювала'::text,'працює'::text,'Пілотка зазначила, що гарнітура під час зльоту працювала бездоганно.'::text),
(359736,39971,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La piloto indicó que el casco ... perfectamente durante el despegue.'::text,'había funcionado'::text,'ha funcionado'::text,'funciona'::text,'La piloto indicó que el casco había funcionado perfectamente durante el despegue.'::text),
(359735,39971,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pilote a indiqué que le casque ... parfaitement pendant le décollage.'::text,'avait fonctionné'::text,'a fonctionné'::text,'fonctionne'::text,'La pilote a indiqué que le casque avait fonctionné parfaitement pendant le décollage.'::text),
(359738,39971,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pilot, başlığın kalkış sırasında kusursuz ... belirtti.'::text,'çalışmış olduğunu'::text,'çalıştığını'::text,'çalıştığını'::text,'Pilot, başlığın kalkış sırasında kusursuz çalışmış olduğunu belirtti.'::text),
(359739,39971,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pilóta jelezte, hogy a headset felszállás közben tökéletesen ...'::text,'működött'::text,'működött'::text,'működik'::text,'A pilóta jelezte, hogy a headset felszállás közben tökéletesen működött.'::text),
(359742,39972,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... ein altes graues Headset, und ehrlich, das grüne ist ikonisch.'::text,'hattest früher'::text,'hattest'::text,'hattest'::text,'Du hattest früher ein altes graues Headset, und ehrlich, das grüne ist ikonisch.'::text),
(359746,39972,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... стару сіру гарнітуру, і чесно, зелена — просто ікона.'::text,'колись мала'::text,'мала'::text,'звикла мати'::text,'Ти колись мала стару сіру гарнітуру, і чесно, зелена — просто ікона.'::text),
(359745,39972,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tú ... un casco gris viejo y, sinceramente, el verde es icónico.'::text,'solías tener'::text,'tenías'::text,'estabas acostumbrada a tener'::text,'Tú solías tener un casco gris viejo y, sinceramente, el verde es icónico.'::text),
(359744,39972,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... un vieux casque gris, et franchement, le vert est iconique.'::text,'avais avant'::text,'avais'::text,'avais l''habitude d''avoir'::text,'Tu avais avant un vieux casque gris, et franchement, le vert est iconique.'::text),
(359747,39972,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senin eskiden gri, eski bir başlığın ... ve açıkçası yeşili efsane.'::text,'vardı'::text,'vardı'::text,'olurdu'::text,'Senin eskiden gri, eski bir başlığın vardı ve açıkçası yeşili efsane.'::text),
(359748,39972,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Neked ... egy régi szürke headseted, és őszintén, a zöld ikonikus.'::text,'régen volt'::text,'volt'::text,'volt'::text,'Neked régen volt egy régi szürke headseted, és őszintén, a zöld ikonikus.'::text),
(359751,39973,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du vergisst nie, dein Headset vor dem Start zu ..., Respekt.'::text,'checken'::text,'checken'::text,'checken'::text,'Ehrlich, du vergisst nie, dein Headset vor dem Start zu checken, Respekt.'::text),
(359755,39973,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ніколи не забуваєш ... гарнітуру перед зльотом, респект.'::text,'перевірити'::text,'перевіряння'::text,'перевірити'::text,'Чесно, ти ніколи не забуваєш перевірити гарнітуру перед зльотом, респект.'::text),
(359754,39973,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sinceramente, nunca te olvidas de ... el casco antes del despegue, respeto.'::text,'revisar'::text,'revisar'::text,'revisar'::text,'Sinceramente, nunca te olvidas de revisar el casco antes del despegue, respeto.'::text),
(359753,39973,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu n''oublies jamais de ... ton casque avant le décollage, respect.'::text,'vérifier'::text,'vérifier'::text,'vérifier'::text,'Franchement, tu n''oublies jamais de vérifier ton casque avant le décollage, respect.'::text),
(359756,39973,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, kalkıştan önce başlığını ... asla unutmuyorsun, saygı.'::text,'kontrol etmeyi'::text,'kontrol etmeyi'::text,'kontrol etmeyi'::text,'Açıkçası, kalkıştan önce başlığını kontrol etmeyi asla unutmuyorsun, saygı.'::text),
(359757,39973,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, sosem felejted el ... a headseted felszállás előtt, respekt.'::text,'ellenőrizni'::text,'ellenőrizni'::text,'ellenőrizni'::text,'Őszintén, sosem felejted el ellenőrizni a headseted felszállás előtt, respekt.'::text),
(341355,37929,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen bei Sonnenuntergang ... sie stundenlang den Kompass. Was für ein aufregender Abend.'::text,'checkt'::text,'checkt'::text,'checkt'::text,'Morgen bei Sonnenuntergang checkt sie stundenlang den Kompass. Was für ein aufregender Abend.'::text),
(341359,37929,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра на заході сонця вона годинами ... компас. Який захопливий вечір.'::text,'перевірятиме'::text,'перевірить'::text,'перевіряє'::text,'Завтра на заході сонця вона годинами перевірятиме компас. Який захопливий вечір.'::text),
(341358,37929,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana al atardecer ... la brújula durante horas. Qué noche tan emocionante.'::text,'estará revisando'::text,'revisará'::text,'revisa'::text,'Mañana al atardecer estará revisando la brújula durante horas. Qué noche tan emocionante.'::text),
(341357,37929,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain au coucher du soleil, elle ... la boussole pendant des heures. Quelle soirée palpitante.'::text,'sera en train de vérifier'::text,'vérifiera'::text,'vérifie'::text,'Demain au coucher du soleil, elle sera en train de vérifier la boussole pendant des heures. Quelle soirée palpitante.'::text),
(341360,37929,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın gün batımında saatlerce pusulayı ... Ne heyecan verici bir akşam.'::text,'kontrol ediyor olacak'::text,'kontrol edecek'::text,'kontrol eder'::text,'Yarın gün batımında saatlerce pusulayı kontrol ediyor olacak Ne heyecan verici bir akşam.'::text),
(341361,37929,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap naplementekor órákig ... az iránytűt. Micsoda izgalmas este.'::text,'fogja nézegetni'::text,'megnézi'::text,'nézegeti'::text,'Holnap naplementekor órákig fogja nézegetni az iránytűt. Micsoda izgalmas este.'::text),
(341364,37930,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie verspricht, dass sie diesmal den Kompass ... Der letzte Trip war makellos.'::text,'checken wird'::text,'checken wird'::text,'gerade checkt'::text,'Sie verspricht, dass sie diesmal den Kompass checken wird Der letzte Trip war makellos.'::text),
(341368,37930,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона обіцяє, що цього разу ... компас. Минула поїздка була бездоганною.'::text,'перевірить'::text,'перевірятиме'::text,'перевіряє'::text,'Вона обіцяє, що цього разу перевірить компас. Минула поїздка була бездоганною.'::text),
(341367,37930,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Promete que esta vez ... la brújula. El último viaje fue impecable.'::text,'revisará'::text,'estará revisando'::text,'está revisando'::text,'Promete que esta vez revisará la brújula. El último viaje fue impecable.'::text),
(341366,37930,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle promet qu''elle ... la boussole cette fois. Le dernier voyage était impeccable.'::text,'vérifiera'::text,'sera en train de vérifier'::text,'vérifie'::text,'Elle promet qu''elle vérifiera la boussole cette fois. Le dernier voyage était impeccable.'::text),
