(341373,37931,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Kapitän den Kompass ..., verirrt sich das Boot komplett!'::text,'ignoriert'::text,'ignorierte'::text,'ignorieren wird'::text,'Wenn ein Kapitän den Kompass ignoriert, verirrt sich das Boot komplett!'::text),
