(341376,37931,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Si un capitán ... la brújula, el barco acaba totalmente perdido!'::text,'ignora'::text,'ignoró'::text,'ignorará'::text,'¡Si un capitán ignora la brújula, el barco acaba totalmente perdido!'::text),
