(341385,37932,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Gritó que alguien ... la brújula y que el viaje estaba arruinado!'::text,'había movido'::text,'ha movido'::text,'mueve'::text,'¡Gritó que alguien había movido la brújula y que el viaje estaba arruinado!'::text),
